def public_api_surface(cfg: AidealConfig, override_filter: str | None = None) -> set[str]:
    """Public API names, optionally narrowed to the INTENDED API by a general,
    codebase-agnostic `surface_filter` (pass override_filter='all' for the raw
    discovered surface):
      all                       - every visible public def (raw surface)
      documented                - has a doc comment (author signalled intent)
      non_override              - not an `override` (excludes inherited/interface impls)
      documented_non_override   - both (tightest intended-API set)
    Default `all` (back-compat)."""
    model = visibility_model(cfg)
    flt = (override_filter or cfg.surface_filter or "all").lower()
    if flt in ("intent_score", "intent"):
        from .api_intent import intent_scores
        return {n for n, info in intent_scores(cfg).items() if info["selected"]}
    if flt in ("intended_llm", "intent_llm"):
        from .api_intent import intended_api_llm
        return intended_api_llm(cfg)[0]
    file_cache: dict[str, list[str]] = {}
    all_names: set[str] = set()
    documented: set[str] = set()
    non_override: set[str] = set()
    py_identities = _python_qualified_identities(cfg) if cfg.language.lower() == "python" else None
    for name, prefix, path, i, _line in _iter_defs(cfg):
        if name in cfg.exclude_names or not _is_public(name, prefix, model):
            continue
        if py_identities is not None:
            rel = str(Path(path).relative_to(cfg.root)).replace("\\", "/")
            if (rel, i + 1, name) not in py_identities:
                continue
        all_names.add(name)
        if not re.search(r"\boverride\b", prefix):
            non_override.add(name)
        if flt.startswith("documented"):
            lines = file_cache.setdefault(
                path, Path(path).read_text(encoding="utf-8", errors="ignore").splitlines())
            if _doc_at(cfg, lines, i).strip():
                documented.add(name)
    # Intent signals, in order of preference: documentation, then tests (a unit
    # test exercising an API is also author intent). Structural `non_override`
    # is the last resort because it's over-inclusive (can't tell API from
    # internal helper). So `documented` degrades: docs -> tested -> non_override
    # -> all, never empty.
    def _tested() -> set[str]:
        if not cfg.test_globs:
            return set()
        names = set()
        for g in cfg.test_globs:
            for p in globmod.glob(str(cfg.root / g), recursive=True):
                txt = Path(p).read_text(encoding="utf-8", errors="ignore")
                for nm in all_names:
                    if nm not in names and re.search(rf"\b{re.escape(nm)}\s*[\(\[]|\.{re.escape(nm)}\b", txt):
                        names.add(nm)
        return names

    if flt == "documented":
        return documented or _tested() or non_override or all_names
    if flt == "tested":
        return _tested() or documented or non_override or all_names
    if flt == "non_override":
        return non_override or all_names
    if flt in ("documented_non_override", "documented_and_non_override"):
        return (documented & non_override) or documented or _tested() or non_override or all_names
    if flt in ("documented_or_tested", "intended"):
        return (documented | _tested()) or non_override or all_names
    return all_names

def _tested() -> set[str]:
    if not cfg.test_globs:
        return set()
    names = set()
    for g in cfg.test_globs:
        for p in globmod.glob(str(cfg.root / g), recursive=True):
            txt = Path(p).read_text(encoding="utf-8", errors="ignore")
            for nm in all_names:
                if nm not in names and re.search(rf"\b{re.escape(nm)}\s*[\(\[]|\.{re.escape(nm)}\b", txt):
                    names.add(nm)
    return names

def render_api_surface(cfg: AidealConfig, include_nonpublic: bool = False) -> str:
    """Plain-text dump of the discovered API surface (Step 1 of the test plan)."""
    details = public_api_details(cfg)
    pub = [d for d in details if d["visibility"] == "public"]
    shown = details if include_nonpublic else pub
    by_name: dict[str, list[dict]] = {}
    for d in shown:
        by_name.setdefault(d["name"], []).append(d)
    lines = [
        f"API SURFACE — {cfg.project_name} ({cfg.language})",
        f"globs: {', '.join(cfg.source_globs)}",
        f"visibility model: {visibility_model(cfg).get('mode')}",
        f"public names: {len(by_name)}   public defs: {len(pub)}   "
        f"non-public defs filtered: {len(details) - len(pub)}",
        "=" * 64,
    ]
    for name in sorted(by_name):
        recs = by_name[name]
        lines.append(f"\n{name}  ({len(recs)} definition{'s' if len(recs) > 1 else ''})")
        for d in recs:
            lines.append(f"  - file   : {d['file']}:{d['line']}  [{d['visibility']}]")
            if d["params"]:
                pstr = "; ".join(
                    f"{p['name']}: {p['type']}" + (f" = {p['default']}" if p.get("default") else "")
                    if p.get("type") else p["name"]
                    for p in d["params"])
                lines.append(f"    params : {pstr}")
            else:
                lines.append("    params : (none)")
            lines.append(f"    returns: {d['returns'] or '(unspecified)'}")
            if d["description"]:
                lines.append(f"    doc    : {d['description'][:200]}")
    return "\n".join(lines)

def surface_audit(cfg: AidealConfig) -> dict:
    """Cross-check every LLM_readme catalog entry against the current API
    surface. Catches the private-function leak class after a visibility-model
    fix: entries whose canonical definition is non-public (private/protected,
    incl. scoped `private[pkg]` and non-public enclosing containers), whose
    file is excluded by `codebase.exclude_path_patterns`, or which fell below
    the intent threshold. These entries burn fix-loop rounds and can never
    pass from an external harness — prune or exclude them instead of fixing.

    Returns counts + per-entry verdicts; CLI: `aideal surface-audit`."""
    entries = [e.name for e in parse_readme(cfg.llm_readme)]
    det = public_api_details(cfg)
    by_name: dict[str, list[dict]] = {}
    for d in det:
        by_name.setdefault(d["name"], []).append(d)
    # modifier evidence per non-public site (via the same prefix _is_public saw)
    mods_of: dict[str, list[str]] = {}
    for name, prefix, path, i, _line in _iter_defs(cfg):
        if name not in entries:
            continue
        found = _NONPUBLIC_MOD_RE.findall(prefix)
        if found:
            rel = str(Path(path).relative_to(cfg.root))
            mods_of.setdefault(name, []).append(f"{' '.join(found)} @ {rel}:{i + 1}")
    selected = public_api_surface(cfg)   # respects surface_filter (intent_score...)
    verdicts: dict[str, dict] = {}
    for n in entries:
        recs = by_name.get(n, [])
        if not recs:
            verdicts[n] = {"status": "not-on-surface",
                           "why": "no definition matched (path-excluded via "
                                  "exclude_path_patterns, moved, or renamed)"}
        elif all(r["visibility"] != "public" for r in recs):
            verdicts[n] = {"status": "non-public",
                           "why": "; ".join(mods_of.get(n, [])[:3]) or
                                  "private/protected (incl. enclosing container)",
                           "sites": [f"{r['file']}:{r['line']}" for r in recs[:3]]}
        elif n not in selected:
            verdicts[n] = {"status": "deselected",
                           "why": f"below intent threshold under surface_filter="
                                  f"{cfg.surface_filter}"}
        else:
            verdicts[n] = {"status": "ok"}
    from collections import Counter
    counts = dict(Counter(v["status"] for v in verdicts.values()))
    prune = sorted(n for n, v in verdicts.items() if v["status"] != "ok")
    return {"check": "surface-audit",
            "catalog_entries": len(entries),
            "public_names_on_surface": len({d["name"] for d in det
                                            if d["visibility"] == "public"}),
            "counts": counts,
            "prune_candidates": prune,
            "verdicts": {n: v for n, v in verdicts.items() if v["status"] != "ok"}}

def _iter_test_blocks(text: str):
    """Yield (test_name, block_text) for each `test("...") { ... }` (brace-balanced).
    Generic for *Spec/FunSuite-style tests; falls back to nothing if none match."""
    for m in _TEST_BLOCK_RE.finditer(text):
        open_brace = text.index("{", m.end() - 1)
        depth = 0
        for k in range(open_brace, len(text)):
            if text[k] == "{":
                depth += 1
            elif text[k] == "}":
                depth -= 1
                if depth == 0:
                    yield m.group(1), text[open_brace:k + 1]
                    break

def _iter_test_blocks_java(text: str):
    """JUnit style: yield (method_name, body) for each @Test/@ParameterizedTest
    method (brace-balanced from its opening `{`)."""
    for m in _JAVA_TEST_RE.finditer(text):
        open_brace = text.index("{", m.end() - 1)
        depth = 0
        for k in range(open_brace, len(text)):
            if text[k] == "{":
                depth += 1
            elif text[k] == "}":
                depth -= 1
                if depth == 0:
                    yield m.group(1), text[open_brace:k + 1]
                    break

def api_test_examples(cfg: AidealConfig, max_per_api: int = 2, max_chars: int = 1400) -> dict[str, list[dict]]:
    """Search the configured test files and index real usage examples by API name.
    Returns {api_name: [{file, test, code}]}. These are compiling, ground-truth
    call patterns the generator/audience can learn from."""
    if not cfg.test_globs:
        return {}
    surface = public_api_surface(cfg)
    index: dict[str, list[dict]] = {}
    for g in cfg.test_globs:
        for path in sorted(globmod.glob(str(cfg.root / g), recursive=True)):
            text = Path(path).read_text(encoding="utf-8", errors="ignore")
            rel = str(Path(path).relative_to(cfg.root))
            for tname, block in _test_blocks_for(cfg, text):
                for name in surface:
                    if len(index.get(name, [])) >= max_per_api:
                        continue
                    # match a call/use of the name: `name(` `name[` or `.name`
                    if re.search(rf"\b{re.escape(name)}\s*[\(\[]|\.{re.escape(name)}\b", block):
                        index.setdefault(name, []).append(
                            {"file": rel, "test": tname, "code": block.strip()[:max_chars]})
    return index

def _names_called_in(text: str, names: set[str]) -> set[str]:
    """Subset of `names` that appear as a call/use in `text`."""
    if not text or not names:
        return set()
    alternatives = "|".join(sorted((re.escape(n) for n in names),
                                     key=len, reverse=True))
    pattern = re.compile(
        rf"\b(?P<call>{alternatives})\s*[\(\[]|\.\s*(?P<member>{alternatives})\b")
    return {m.group("call") or m.group("member") for m in pattern.finditer(text)}

def intended_api_llm(cfg: AidealConfig) -> tuple[set[str], dict]:
    """Token-efficient intended-API selection: STATIC evidence auto-includes the
    obvious (score >= include_threshold) and auto-excludes the clearly-internal
    (score <= exclude_threshold); the LLM adjudicates ONLY the ambiguous middle
    band, in batches, from COMPACT records (name/signature/doc/score/signals) —
    never source. Decisions are cached with provenance (`intended_api.cache`) so
    runs are reproducible. Returns (selected_names, decisions)."""
    import json as _json
    ia = (cfg.raw.get("codebase", {}) or {}).get("intended_api", {}) or {}
    inc_t = int(ia.get("static_include_threshold", 8))
    exc_t = int(ia.get("static_exclude_threshold", 1))
    batch = int(ia.get("batch_size", 25))
    selection_limit = int(ia.get("selection_limit", 0) or 0)
    rubric_version = int(ia.get("rubric_version", 2))
    refresh = bool(ia.get("refresh", False))
    cache_path = (cfg.root / ia.get("cache", "docs/intended_api_decisions.json")).resolve()

    scores = intent_scores(cfg)
    identity = str(ia.get("identity", "bare"))
    all_details = [d for d in public_api_details(cfg) if d["visibility"] == "public"]
    if identity == "qualified" and cfg.language.lower() == "python":
        # Exact qualified duplicates can arise from conditional definitions;
        # elect one canonical record deterministically. Distinct owners remain
        # distinct (RMSD.run != AnalysisBase.run).
        details = {}
        for d in sorted(all_details, key=lambda r: (
                r["qualified_name"], not bool(r["description"]),
                -len(r["params"]), r["file"], r["line"])):
            details.setdefault(d["qualified_name"], d)
        if ia.get("candidate_filter", "static_selected") == "static_selected":
            details = {q: d for q, d in details.items()
                       if scores.get(d["name"], {}).get("selected")}
        candidate_scores = {q: scores[d["name"]] for q, d in details.items()}
    else:
        details = {d["name"]: d for d in all_details}
        candidate_scores = scores
        if ia.get("candidate_filter", "static_selected") == "static_selected":
            candidate_scores = {n: info for n, info in scores.items()
                                if info.get("selected") and n in details}
            details = {n: details[n] for n in candidate_scores}
    selected: set[str] = set()
    decisions: dict[str, dict] = {}
    ambiguous: list[str] = []
    for name, info in candidate_scores.items():
        s = info["score"]
        if s >= inc_t:
            selected.add(name); decisions[name] = {"decision": "include", "by": "static", "score": s}
        elif s <= exc_t:
            decisions[name] = {"decision": "exclude", "by": "static", "score": s}
        else:
            ambiguous.append(name)

    cache: dict = {}
    if cache_path.exists() and not refresh:
        try:
            cache = _json.loads(cache_path.read_text(encoding="utf-8"))
        except Exception:
            cache = {}
    # A cached judgment is reusable only when it was produced with the same
    # rubric.  This prevents an older binary include/exclude pilot from being
    # silently mixed with a later scored ranking experiment.
    todo = [n for n in ambiguous
            if n not in cache or cache[n].get("rubric_version") != rubric_version]
    if todo:
        try:
            import hashlib as _hashlib
            from .llm import invoke_text
            from .prompts import load as load_prompt
            from .profile import require_profile
            require_profile(cfg)
            model = cfg.model_for_role("author")
            for i in range(0, len(todo), batch):
                chunk = todo[i:i + batch]
                recs = [{"name": n,
                         "bare_name": details.get(n, {}).get("name", n),
                         "module": details.get(n, {}).get("module", ""),
                         "owner": details.get(n, {}).get("owner", ""),
                         "kind": details.get(n, {}).get("definition_kind", ""),
                         "signature": details.get(n, {}).get("signature", n),
                         "doc": (details.get(n, {}).get("description", "") or "")[:240],
                         "static_score": candidate_scores[n]["score"],
                         "signals": candidate_scores[n]["reasons"],
                         "available_receiver_types": ia.get("available_receiver_types", [])}
                        for n in chunk]
                system, user = load_prompt(
                    cfg, "aideal/intended_review",
                    records=_json.dumps(recs, ensure_ascii=False, indent=2))
                prompt_sha = _hashlib.sha256(
                    (system + "\0" + user).encode("utf-8")).hexdigest()
                resp = invoke_text(model, system, user)
                parsed = []
                try:
                    parsed = _json.loads(resp[resp.index("["):resp.rindex("]") + 1])
                except Exception:
                    parsed = []
                bydec = {d.get("name"): d for d in parsed if isinstance(d, dict)}
                for n in chunk:
                    d = bydec.get(n, {})
                    ratings = d.get("ratings", {}) if isinstance(d.get("ratings"), dict) else {}
                    clean_ratings = {
                        key: max(0, min(3, int(ratings.get(key, 0) or 0)))
                        for key in ("user_facing", "fixture_runnable",
                                    "oracle_strength", "domain_relevance")
                    }
                    family = str(d.get("capability_family", "")).strip().lower()
                    family = re.sub(r"[^a-z0-9_.:/+-]+", "-", family).strip("-")
                    if not family:
                        # Deterministic fallback: a missing model label cannot
                        # erase the symbol from family-coverage accounting.
                        family = (details[n].get("module", "unknown") + "/" +
                                  details[n].get("name", n)).lower()
                    cache[n] = {"decision": d.get("decision", "uncertain"),
                                "reason": d.get("reason", ""), "by": "llm",
                                "score": candidate_scores[n]["score"], "model": model.model,
                                "provider": model.provider, "identity": identity,
                                "ratings": clean_ratings,
                                "capability_family": family,
                                "rubric_version": rubric_version,
                                "prompt_sha256": prompt_sha,
                                "source": f"{details[n]['file']}:{details[n]['line']}"}
                # Crash-safe intent progress: each paid batch is durable.
                cache_path.parent.mkdir(parents=True, exist_ok=True)
                cache_path.write_text(
                    _json.dumps(cache, indent=2, ensure_ascii=False), encoding="utf-8")
        except Exception:
            if ia.get("require_llm", False):
                raise
            pass  # LLM unavailable -> fall back to the static threshold below

    thr = candidate_scores and next(iter(candidate_scores.values())).get("threshold", 5)
    for n in ambiguous:
        d = cache.get(n)
        if d is None:                       # LLM unavailable: fall back to intent threshold
            inc = candidate_scores[n]["score"] >= (thr or 5)
            decisions[n] = {"decision": "include" if inc else "exclude",
                            "by": "static_fallback", "score": candidate_scores[n]["score"]}
        else:
            decisions[n] = d
        if decisions[n]["decision"] == "include":
            selected.add(n)

    # Optional fixed-budget selection.  The LLM supplies auditable semantic
    # ratings; the tool performs the final ranking deterministically.  Static
    # evidence is deliberately a small tie-breaker rather than the main score,
    # because large libraries often give hundreds of symbols the same static
    # score.  Soft owner/module caps improve breadth; if they prevent filling
    # the requested budget, the remaining highest-ranked symbols fill it.
    if selection_limit and len(selected) > selection_limit:
        weights = {"user_facing": 4, "fixture_runnable": 4,
                   "oracle_strength": 3, "domain_relevance": 2,
                   "static_score": 1}
        weights.update(ia.get("ranking_weights", {}) or {})

        def _rank_score(name: str) -> int:
            ratings = decisions[name].get("ratings", {}) or {}
            value = sum(int(weights[k]) * int(ratings.get(k, 0) or 0)
                        for k in ("user_facing", "fixture_runnable",
                                  "oracle_strength", "domain_relevance"))
            # Bound the legacy score so it cannot dominate semantic quality.
            static = max(-5, min(10, int(candidate_scores[name]["score"])))
            return value + int(weights["static_score"]) * static

        ranked = sorted(selected, key=lambda n: (
            -_rank_score(n), details[n].get("module", ""),
            details[n].get("owner", ""), n))
        max_owner = int(ia.get("max_per_owner", 0) or 0)
        max_module = int(ia.get("max_per_module", 0) or 0)
        owner_counts: dict[str, int] = {}
        module_counts: dict[str, int] = {}
        chosen: list[str] = []
        deferred: list[str] = []
        # First take the strongest representative of every capability family.
        # If there are more families than budget, their strongest members
        # compete on the same global score. Remaining slots then return to the
        # ordinary global ranking. This prevents a dense family of near-aliases
        # from crowding an entire operation family out of the experiment.
        family_heads: list[str] = []
        seen_families: set[str] = set()
        for n in ranked:
            family = decisions[n].get("capability_family", "unknown")
            if family not in seen_families:
                family_heads.append(n)
                seen_families.add(family)
        family_head_set = set(family_heads[:selection_limit])
        ordered = family_heads[:selection_limit] + [n for n in ranked if n not in family_head_set]
        for n in ordered:
            owner = details[n].get("owner", "") or "<module>"
            module = details[n].get("module", "") or "<unknown>"
            if ((max_owner and owner_counts.get(owner, 0) >= max_owner) or
                    (max_module and module_counts.get(module, 0) >= max_module)):
                deferred.append(n)
                continue
            chosen.append(n)
            owner_counts[owner] = owner_counts.get(owner, 0) + 1
            module_counts[module] = module_counts.get(module, 0) + 1
            if len(chosen) == selection_limit:
                break
        if len(chosen) < selection_limit:
            chosen.extend(deferred[:selection_limit - len(chosen)])
        selected = set(chosen)
        rank_by_name = {n: i + 1 for i, n in enumerate(ranked)}
        for n in ranked:
            decisions[n]["ranking_score"] = _rank_score(n)
            decisions[n]["rank"] = rank_by_name[n]
            decisions[n]["selected_in_budget"] = n in selected
            if n not in selected:
                decisions[n]["adjudication"] = decisions[n]["decision"]
                decisions[n]["decision"] = "exclude"
                decisions[n]["reason"] = "outside fixed selection budget; " + decisions[n].get("reason", "")
        represented = {decisions[n].get("capability_family", "unknown") for n in selected}
        eligible_families = {decisions[n].get("capability_family", "unknown") for n in ranked}
        for n in ranked:
            decisions[n]["selection_summary"] = {
                "budget": selection_limit,
                "eligible_apis": len(ranked),
                "eligible_families": len(eligible_families),
                "represented_families": len(represented),
            }
    return selected, decisions

def _rank_score(name: str) -> int:
    ratings = decisions[name].get("ratings", {}) or {}
    value = sum(int(weights[k]) * int(ratings.get(k, 0) or 0)
                for k in ("user_facing", "fixture_runnable",
                          "oracle_strength", "domain_relevance"))
    # Bound the legacy score so it cannot dominate semantic quality.
    static = max(-5, min(10, int(candidate_scores[name]["score"])))
    return value + int(weights["static_score"]) * static

def intent_scores(cfg: AidealConfig, force_llm: bool | None = None) -> dict[str, dict]:
    """Score each public API by GENERIC evidence of user-facing intent and select
    those at/above a threshold. Codebase-agnostic: signals are documentation,
    tests, original-doc mentions, visibility/override, internal-path and
    boilerplate-name penalties. Weights/threshold/manual overrides come from
    `codebase.intent` in aideal.yaml. Returns {name: {score, reasons, selected}}
    — auditable, with per-API reasons."""
    intent = (cfg.raw.get("codebase", {}) or {}).get("intent", {}) or {}
    W = dict(_DEFAULT_INTENT_WEIGHTS); W.update(intent.get("weights", {}) or {})
    threshold = int(intent.get("threshold", 5))
    manual_inc = set(intent.get("manual_include", []) or [])
    manual_exc = set(intent.get("manual_exclude", []) or [])
    excl_pats = [re.compile(p) for p in (intent.get("exclude_name_patterns", []) or [])]
    boiler = _BOILERPLATE_NAMES | set(intent.get("boilerplate_names", []) or [])
    # interface-method detector: a name with many definition sites is (almost
    # always) a trait/interface method implemented per class, not one operation
    # (RDPro: run×29, write×27, close×27, read×24). Penalty is evidence-based
    # and auditable; strong real APIs (documented+tested+code-mentioned)
    # survive it. Tune via codebase.intent.{weights.many_impls, many_impls_threshold}.
    many_thr = int(intent.get("many_impls_threshold", 5))
    # docs_mention_mode: "code" (default) counts a doc mention only in code
    # context (fenced block / backticks / call form); "any" is the legacy
    # plain word match — kept for A/B comparison.
    mention_mode = intent.get("docs_mention_mode", "code")

    model = visibility_model(cfg)
    # Python's regex scanner sees nested local functions as well as importable
    # module/class APIs. Keep the intent denominator aligned with
    # public_api_details(), which uses AST-derived identities to reject locals.
    py_identities = _python_qualified_identities(cfg) if cfg.language.lower() == "python" else None
    file_cache: dict[str, list[str]] = {}
    recs: dict[str, dict] = {}
    for name, prefix, path, i, _line in _iter_defs(cfg):
        if name in cfg.exclude_names or not _is_public(name, prefix, model):
            continue
        if py_identities is not None:
            rel = str(Path(path).relative_to(cfg.root)).replace("\\", "/")
            if (rel, i + 1, name) not in py_identities:
                continue
        r = recs.setdefault(name, {"documented": False, "non_override": False,
                                   "internal": False, "sites": 0})
        r["sites"] += 1
        if not re.search(r"\boverride\b", prefix):
            r["non_override"] = True
        norm = "/" + path.replace("\\", "/").lower() + "/"
        if any(seg in norm for seg in _INTERNAL_PATH_SEGMENTS):
            r["internal"] = True
        lines = file_cache.setdefault(path, Path(path).read_text(encoding="utf-8", errors="ignore").splitlines())
        if _doc_at(cfg, lines, i).strip():
            r["documented"] = True

    names = set(recs)
    # evidence from tests and the original docs (computed once over the corpus)
    tested = set()
    for g in cfg.test_globs:
        for p in globmod.glob(str(cfg.root / g), recursive=True):
            tested |= _names_called_in(Path(p).read_text(encoding="utf-8", errors="ignore"), names - tested)
    docs_text = cfg.original_readme_text() if cfg.original_readme_files else ""
    if mention_mode == "code":
        mentioned = _doc_code_mentions(docs_text, names)
    else:  # "any" — legacy plain word match (A/B baseline)
        mentioned = {n for n in names if docs_text and re.search(rf"\b{re.escape(n)}\b", docs_text)}
    # optional LLM "commonly-used" signal (opt-in, cached for reproducibility).
    # force_llm overrides config: True = run it (default weight 4 if unset),
    # False = skip it (static-only). None = honor codebase.intent.use_llm.
    use_llm = intent.get("use_llm") if force_llm is None else force_llm
    if force_llm and not W.get("llm_common", 0):
        W["llm_common"] = 4
    common: set[str] = set()
    if W.get("llm_common", 0) and use_llm:
        # opt-in signal: degrade to static on ANY failure (missing key, profile
        # gate's SystemExit, network) so the score never crashes.
        try:
            common = llm_common_apis(cfg, names, refresh=bool(intent.get("refresh_llm")))
        except (Exception, SystemExit):
            common = set()

    out: dict[str, dict] = {}
    for name, r in recs.items():
        score = 0; reasons = []
        if r["documented"]:           score += W["documented"];      reasons.append(f"documented(+{W['documented']})")
        if name in tested:            score += W["tested"];          reasons.append(f"tested(+{W['tested']})")
        if name in mentioned:         score += W["mentioned_in_docs"]; reasons.append(f"mentioned_in_docs(+{W['mentioned_in_docs']})")
        if r["non_override"]:         score += W["non_override"];    reasons.append(f"non_override(+{W['non_override']})")
        else:                         score += W["override"];        reasons.append(f"override({W['override']})")
        if r["internal"]:             score += W["internal_path"];   reasons.append(f"internal_path({W['internal_path']})")
        if name in boiler or any(p.search(name) for p in excl_pats):
            score += W["boilerplate_name"]; reasons.append(f"boilerplate_name({W['boilerplate_name']})")
        if W.get("many_impls", 0) and r["sites"] >= many_thr:
            score += W["many_impls"]; reasons.append(f"many_impls({r['sites']} sites,{W['many_impls']})")
        if name in common:
            score += W["llm_common"]; reasons.append(f"llm_common(+{W['llm_common']})")
        selected = score >= threshold
        if name in manual_inc: selected = True;  reasons.append("manual_include")
        if name in manual_exc: selected = False; reasons.append("manual_exclude")
        out[name] = {"score": score, "reasons": reasons, "selected": selected,
                     "threshold": threshold, "sites": r["sites"]}
    return dict(sorted(out.items(), key=lambda kv: (-kv[1]["score"], kv[0])))

def _dedup_deprioritize(cfg: AidealConfig) -> tuple:
    """Compiled `codebase.dedup.deprioritize_paths` patterns (adapter-level
    default for scala-spark: Java facade files `Java*.scala`)."""
    pats = ((cfg.raw.get("codebase", {}) or {}).get("dedup", {}) or {}).get(
        "deprioritize_paths", []) or []
    return tuple(re.compile(p) for p in pats)

def dedup_report(cfg: AidealConfig) -> dict:
    """Redundancy audit of the SELECTED surface. Deterministic (no LLM).

    Four redundancy classes, each auditable:
      1. overload collapse — one catalog entry per name; canonical site elected
         (documented > shallowest path > lowest line), others become variants;
      2. forwarder alias edges — `def a(...) = b(...)` one-liners where both
         names are selected: `a` should be catalogued as an alias of `b`, not
         documented twice;
      3. same-file same-signature twins — review list (often legitimate pairs
         like compress/decompress; never auto-dropped);
      4. alias-registry cross-check — registry aliases (aliases.json + any
         *.scala alias object using the ``(alias for `X`)`` doc convention)
         must point at a selected canonical and not shadow a surface name.
    """
    import json as _json
    det = [d for d in public_api_details(cfg) if d["visibility"] == "public"]
    scores = intent_scores(cfg)
    sel = {n for n, v in scores.items() if v["selected"]}
    by_name: dict[str, list[dict]] = {}
    for d in det:
        if d["name"] in sel:
            by_name.setdefault(d["name"], []).append(d)

    # 1. overload collapse — subsumption-aware: canonical = the maximal
    # telescoping overload ("needed longest parameters"); same-file
    # prefix-shorter forms are the SAME function with defaults, recorded under
    # subsumed_overloads, not as distinct variants.
    collapse: dict[str, dict] = {}
    subsumed_total = 0
    _depri_pats = _dedup_deprioritize(cfg)
    for n, recs in sorted(by_name.items()):
        maximals, subsumed = _subsume_overloads(recs, _depri_pats)
        canon = maximals[0]
        subsumed_total += len(subsumed)
        collapse[n] = {"sites": len(recs),
                       "canonical": f"{canon['file']}:{canon['line']}",
                       "signature": canon["signature"],
                       "subsumed_overloads": [
                           {"site": f"{a['file']}:{a['line']}",
                            "params": len(a["params"]),
                            "same_function_as": f"{b['file']}:{b['line']}"}
                           for a, b in subsumed],
                       "distinct_variants": len(maximals) - 1}

    # 2. forwarder alias edges (same-line `= callee(...)`). An edge only
    # COLLAPSES a catalog entry when EVERY def site of the name forwards to
    # the same canonical ("full"); otherwise it is "partial" — e.g. RDPro's
    # `shapefile` forwards to `spatialFile` in the Java context but is the
    # documented first-class entry point in the Scala mixin, so it stays.
    fcache: dict[str, list[str]] = {}
    forwarders: list[dict] = []
    for n, recs in sorted(by_name.items()):
        callees, sites = set(), []
        for d in recs:
            try:
                lines = fcache.setdefault(
                    d["file"], (cfg.root / d["file"]).read_text(encoding="utf-8", errors="ignore").splitlines())
                m = re.search(r"=\s*([A-Za-z_][\w.]*)\s*[\(\[]", lines[d["line"] - 1])
            except (OSError, IndexError):
                m = None
            callee = m.group(1).split(".")[-1] if m else None
            if callee in sel and callee != n:
                callees.add(callee); sites.append(f"{d['file']}:{d['line']}")
            else:
                callees.add(None)  # at least one non-forwarding site
        real = callees - {None}
        if real:
            full = None not in callees and len(real) == 1
            forwarders.append({"alias": n, "canonical": sorted(real)[0] if full else sorted(real),
                               "collapse": "full" if full else "partial",
                               "sites": sites})

    # 3. same-file same-signature twins
    twin_ix: dict[tuple, set[str]] = {}
    for n, recs in by_name.items():
        for d in recs:
            key = (d["file"], tuple((p.get("type") or "?") for p in d["params"]),
                   d["returns"] or "?")
            twin_ix.setdefault(key, set()).add(n)
    twins = [{"file": k[0], "params": list(k[1]), "returns": k[2], "names": sorted(v)}
             for k, v in sorted(twin_ix.items()) if len(v) > 1]

    # 4. alias-registry cross-check
    reg_aliases: list[dict] = []
    try:
        if cfg.aliases_file.exists():
            for r in _json.loads(cfg.aliases_file.read_text(encoding="utf-8")):
                reg_aliases.append({"alias": r["alias"], "canonical": r["canonical"],
                                    "status": r.get("status"), "source": cfg.aliases_file.name,
                                    "shadows_surface": r["alias"] in sel,
                                    "canonical_in_surface": r["canonical"] in sel})
    except Exception:
        pass
    for sf in sorted(cfg.aliases_file.parent.glob("*.scala")):
        text = sf.read_text(encoding="utf-8", errors="ignore")
        for m in re.finditer(r"\(alias for `([\w\[\]]+)`\).*?\bdef\s+(\w+)", text, re.S):
            reg_aliases.append({"alias": m.group(2), "canonical": m.group(1),
                                "status": "added", "source": sf.name,
                                "shadows_surface": m.group(2) in sel,
                                "canonical_in_surface": m.group(1) in sel})

    sites_total = sum(c["sites"] for c in collapse.values())
    full_fwd = {f["alias"] for f in forwarders if f["collapse"] == "full"}
    return {
        "selected_names": len(by_name),
        "selected_def_sites": sites_total,
        "collapsed_variants": sites_total - len(by_name),
        "subsumed_overload_sites": subsumed_total,
        "forwarder_alias_edges": forwarders,
        "catalog_entries_after_aliasing": len(by_name) - len(full_fwd),
        "same_signature_twins": twins,
        "registry_aliases": reg_aliases,
        "collapse": collapse,
    }

def _doc_above(lines: list[str], idx: int) -> str:
    """Capture a doc/comment block (/** */, ///, #) immediately above line idx."""
    out, j = [], idx - 1
    while j >= 0 and not lines[j].strip():
        j -= 1
    if j >= 0 and lines[j].strip().endswith("*/"):
        while j >= 0:
            out.append(lines[j].strip());
            if lines[j].strip().startswith("/*"):
                break
            j -= 1
        out.reverse()
        txt = " ".join(l.strip("/*").strip() for l in out if l.strip("/* ").strip())
        return txt.strip()
    block = []
    while j >= 0 and re.match(r"^\s*(///|//!|#)\s?", lines[j]):
        block.append(re.sub(r"^\s*(///|//!|#)\s?", "", lines[j]).strip()); j -= 1
    block.reverse()
    return " ".join(block).strip()

def _doc_at(cfg: AidealConfig, lines: list[str], idx: int) -> str:
    """Language-aware doc extraction for the def at line idx (see _DOC_POSITION)."""
    if _DOC_POSITION.get(cfg.language.lower(), "above") == "below":
        return _doc_below_py(lines, idx) or _doc_above(lines, idx)
    return _doc_above(lines, idx)

def _doc_below_py(lines: list[str], idx: int) -> str:
    """Python: the docstring sits BELOW the def line. Walk past the (possibly
    multi-line) signature to the line ending with `:`, then capture a
    triple-quoted docstring if it opens there. Returns '' when absent.

    (Before this existed, the `documented` intent signal fired 0x on Python
    codebases — Sedona audit 2026-07-06 — because _doc_above looks up.)"""
    j, n = idx, len(lines)
    # end of signature: first line at/after idx whose code part ends with ':'
    while j < n:
        code = lines[j].split("#", 1)[0].rstrip()
        if code.endswith(":"):
            break
        j += 1
        if j - idx > 20:                      # runaway guard: not a normal signature
            return ""
    j += 1
    while j < n and not lines[j].strip():
        j += 1
    if j >= n:
        return ""
    m = re.match(r'^\s*[rRbBuU]{0,2}("""|\'\'\')(.*)$', lines[j])
    if not m:
        return ""
    quote, rest = m.group(1), m.group(2)
    if quote in rest:                          # one-line docstring
        return rest.split(quote, 1)[0].strip()
    parts = [rest.strip()]
    for k in range(j + 1, min(n, j + 60)):
        if quote in lines[k]:
            parts.append(lines[k].split(quote, 1)[0].strip())
            break
        parts.append(lines[k].strip())
    return " ".join(p for p in parts if p).strip()

def _java_return_type(raw_signature: str, name: str) -> str:
    """Recover a Java method return type; constructors intentionally have none."""
    head = raw_signature.split("(", 1)[0].rstrip()
    if not head.endswith(name):
        return ""
    before = head[:-len(name)].strip()
    tokens = before.split()
    while tokens and tokens[0] in _JAVA_MEMBER_MODIFIERS:
        tokens.pop(0)
    if tokens and tokens[0].startswith("<"):
        # Generic method type parameters may contain spaces; consume through
        # the token whose angle brackets balance.
        depth = 0
        while tokens:
            token = tokens.pop(0)
            depth += token.count("<") - token.count(">")
            if depth <= 0:
                break
    return " ".join(tokens)

def _param_record(raw: str) -> dict:
    """Parse one parameter into {name, type, default}. Splits the default on a
    top-level `=` that is NOT the `=>` of a function type (e.g. `f: Int => Int`)."""
    parts = re.split(r"=(?!>)", raw, maxsplit=1)
    left = parts[0].strip()
    default = parts[1].strip() if len(parts) > 1 else ""
    if ":" in left:
        nm, typ = left.split(":", 1)
        return {"name": nm.strip(), "type": typ.strip(), "default": default}
    return {"name": left, "type": "", "default": default}

def _python_qualified_identities(cfg: AidealConfig) -> dict[tuple[str, int, str], dict]:
    """AST-derived identity for each importable Python API definition.

    Keys match the existing regex scanner by ``(relative file, line, bare
    name)``. Nested local functions are deliberately absent: they are not
    addressable public APIs. Nested classes remain addressable through their
    owner chain. No domain/package names are hard-coded.
    """
    out: dict[tuple[str, int, str], dict] = {}
    seen: set[Path] = set()
    for pattern in cfg.source_globs:
        for raw in globmod.glob(str(cfg.root / pattern), recursive=True):
            path = Path(raw)
            if path in seen or path.suffix != ".py" or not path.is_file():
                continue
            seen.add(path)
            try:
                tree = ast.parse(path.read_text(encoding="utf-8", errors="ignore"),
                                 filename=str(path))
            except (OSError, SyntaxError):
                continue
            rel = str(path.relative_to(cfg.root)).replace("\\", "/")
            module = _python_module_name(path)

            def function_signature(node) -> tuple[str, list[dict], str]:
                args_text = ast.unparse(node.args)
                parts = [p for p in _split_top_level(args_text)
                         if p.strip() not in ("/", "*")]
                params = [_param_record(p) for p in parts]
                returns = ast.unparse(node.returns) if node.returns is not None else ""
                prefix = "async def" if isinstance(node, ast.AsyncFunctionDef) else "def"
                suffix = f" -> {returns}" if returns else ""
                return f"{prefix} {node.name}({args_text}){suffix}", params, returns

            def class_signature(node: ast.ClassDef) -> str:
                bases = [ast.unparse(base) for base in node.bases]
                bases.extend(
                    f"{kw.arg}={ast.unparse(kw.value)}" if kw.arg else f"**{ast.unparse(kw.value)}"
                    for kw in node.keywords
                )
                return f"class {node.name}" + (f"({', '.join(bases)})" if bases else "")

            def visit(body, classes: tuple[str, ...] = (), inside_function: bool = False):
                for node in body:
                    if isinstance(node, ast.ClassDef) and not inside_function:
                        owners = classes + (node.name,)
                        qn = ".".join(filter(None, (module, *owners)))
                        out[(rel, node.lineno, node.name)] = {
                            "qualified_name": qn, "module": module,
                            "owner": ".".join(classes), "kind": "class",
                            "signature": class_signature(node),
                            "params": [], "returns": "",
                        }
                        visit(node.body, owners, False)
                    elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                        if not inside_function:
                            qn = ".".join(filter(None, (module, *classes, node.name)))
                            signature, params, returns = function_signature(node)
                            out[(rel, node.lineno, node.name)] = {
                                "qualified_name": qn, "module": module,
                                "owner": ".".join(classes),
                                "kind": "method" if classes else "function",
                                "signature": signature,
                                "params": params, "returns": returns,
                            }
                        # Do not expose definitions local to a function/method.
                    elif not inside_function:
                        # Definitions can appear under module/class conditionals.
                        nested = []
                        for attr in ("body", "orelse"):
                            value = getattr(node, attr, None)
                            if isinstance(value, list):
                                nested.extend(value)
                        if nested:
                            visit(nested, classes, False)

            visit(tree.body)
    return out

def class_signature(node: ast.ClassDef) -> str:
    bases = [ast.unparse(base) for base in node.bases]
    bases.extend(
        f"{kw.arg}={ast.unparse(kw.value)}" if kw.arg else f"**{ast.unparse(kw.value)}"
        for kw in node.keywords
    )
    return f"class {node.name}" + (f"({', '.join(bases)})" if bases else "")

def visit(body, classes: tuple[str, ...] = (), inside_function: bool = False):
    for node in body:
        if isinstance(node, ast.ClassDef) and not inside_function:
            owners = classes + (node.name,)
            qn = ".".join(filter(None, (module, *owners)))
            out[(rel, node.lineno, node.name)] = {
                "qualified_name": qn, "module": module,
                "owner": ".".join(classes), "kind": "class",
                "signature": class_signature(node),
                "params": [], "returns": "",
            }
            visit(node.body, owners, False)
        elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            if not inside_function:
                qn = ".".join(filter(None, (module, *classes, node.name)))
                signature, params, returns = function_signature(node)
                out[(rel, node.lineno, node.name)] = {
                    "qualified_name": qn, "module": module,
                    "owner": ".".join(classes),
                    "kind": "method" if classes else "function",
                    "signature": signature,
                    "params": params, "returns": returns,
                }
            # Do not expose definitions local to a function/method.
        elif not inside_function:
            # Definitions can appear under module/class conditionals.
            nested = []
            for attr in ("body", "orelse"):
                value = getattr(node, attr, None)
                if isinstance(value, list):
                    nested.extend(value)
            if nested:
                visit(nested, classes, False)

def _skip_balanced(c, open_ch, close_ch):
    depth = 0
    while c < n:
        if window[c] == open_ch:
            depth += 1
        elif window[c] == close_ch:
            depth -= 1
            if depth == 0:
                return c + 1
        c += 1
    return c

def _skip_ws(c):
    while c < n and window[c].isspace():
        c += 1
    return c

def _split_top_level(inner: str) -> list[str]:
    """Split a parameter list on top-level commas (ignoring nested []/<>/()/{})."""
    out, depth, cur = [], 0, ""
    for ch in inner:
        if ch in "([{<":
            depth += 1
        elif ch in ")]}>":
            depth -= 1
        if ch == "," and depth == 0:
            out.append(cur.strip()); cur = ""
        else:
            cur += ch
    if cur.strip():
        out.append(cur.strip())
    return out

def _is_public(name: str, prefix: str, model: dict) -> bool:
    """`prefix` is the text on the def line BEFORE the matched name (the modifiers),
    with any NON-PUBLIC enclosing-container modifiers prepended by `_iter_defs`
    (a def inside `private[pkg] object X` is not callable from outside either)."""
    if name.startswith("_"):          # universal convention rule (Python/JS internals)
        return False
    mode = model.get("mode", "convention")
    if mode == "deny":
        return not any(re.search(p, prefix) for p in model.get("private", []))
    if mode == "allow":
        return any(re.search(p, prefix) for p in model.get("public", []))
    if mode == "case":
        return name[:1].isupper()
    return True                       # convention: only the `_` rule applies

def visibility_model(cfg: AidealConfig) -> dict:
    """Resolve the visibility model: explicit config overrides the language default."""
    if cfg.visibility:
        return cfg.visibility
    return _VISIBILITY_DEFAULTS.get(cfg.language.lower(), {"mode": "convention"})

def load_compatibility(checkpoint: Path, current: dict) -> dict:
    path = checkpoint.with_name("checkpoint_compatibility.json")
    if not path.exists():
        return {}
    record = json.loads(path.read_text())
    if record.get("schema") != 1 or record.get("checkpoint") != str(checkpoint.resolve()):
        raise ValueError("Checkpoint compatibility scope mismatch")
    if record.get("current_components") != current:
        # Source/config/doc/input changes require new evidence, never an alias.
        return {}
    old = record["legacy_components"]
    if fingerprint(old) != record["legacy_fingerprint"]:
        raise ValueError("Invalid legacy fingerprint proof")
    if record["input_fixtures"] != current["fixtures"]:
        raise ValueError("Input fixture proof mismatch")
    allowed = {"schema", "engine", "fixtures"}
    if {k: v for k, v in old.items() if k not in allowed} != {
            k: v for k, v in current.items() if k not in allowed}:
        raise ValueError("Checkpoint migration changes experimental inputs")
    return {"legacy_fingerprint": record["legacy_fingerprint"],
            "current_fingerprint": fingerprint(current),
            "record": str(path), "record_sha256": hashlib.sha256(path.read_bytes()).hexdigest(),
            "selection_policy": record["selection_policy"],
            "reason": record["reason"]}

def main(argv: list[str] | None = None) -> int:
    """Entry point: exit cleanly when piped into `head`/`less` etc. (the reader
    closes the pipe early, raising BrokenPipeError)."""
    try:
        return _run(argv)
    except BrokenPipeError:
        try:
            sys.stdout.close()
        except Exception:
            pass
        return 0

def model_for_role(self, role: str) -> ModelSpec:
    key = self.roles.get(role)
    if key is None and role in self._ROLE_FALLBACKS:
        return self.model_for_role(self._ROLE_FALLBACKS[role])
    if key is None or key not in self.registry:
        raise KeyError(f"role '{role}' is not mapped to a registry model (have: {list(self.registry)})")
    return self.registry[key]

def original_readme_text(self, limit: int | None = None) -> str:
    """Concatenate all baseline docs (README + extra docs/dirs) with file
    headers. `limit` caps the total characters."""
    parts: list[str] = []
    for p in self.original_readme_files:
        try:
            t = p.read_text(encoding="utf-8", errors="ignore")
        except OSError:
            continue
        try:
            label = p.relative_to(self.root)
        except ValueError:
            # External codebases/docs are valid project inputs; retain an
            # auditable absolute label when the file is outside cfg.root.
            label = p
        parts.append(f"===== {label} =====\n{t}")
    text = "\n\n".join(parts)
    return text[:limit] if limit else text

@dataclass
class ModelSpec:
    provider: str
    model: str
    bridge: dict | None = None

def _deep_merge(base: dict, over: dict) -> dict:
    """Recursively merge `over` onto `base`. Dicts merge key-by-key; lists and
    scalars are replaced by the higher layer."""
    out = dict(base)
    for k, v in over.items():
        if k in out and isinstance(out[k], dict) and isinstance(v, dict):
            out[k] = _deep_merge(out[k], v)
        else:
            out[k] = v
    return out

def _load_layered(config_path: Path) -> dict:
    """Build the effective raw config: framework defaults, then each adapter in
    `extends:`, then the project file itself (highest precedence)."""
    project_raw = yaml.safe_load(config_path.read_text(encoding="utf-8")) or {}
    merged: dict = {}
    if DEFAULTS_PATH.exists():
        merged = yaml.safe_load(DEFAULTS_PATH.read_text(encoding="utf-8")) or {}
    for name in project_raw.get("extends", []) or []:
        adapter = _resolve_adapter(name, config_path.parent)
        if adapter is not None:
            merged = _deep_merge(merged, yaml.safe_load(adapter.read_text(encoding="utf-8")) or {})
    return _deep_merge(merged, project_raw)

def _resolve_readme_sources(root: Path, sources: list[str]) -> list[Path]:
    """Expand each baseline-doc source (a file, a directory, or a glob) into a
    DETERMINISTIC (per-source sorted), de-duplicated, TEXT-ONLY list of files.
    Directories recursively include every extension in ``_TEXT_DOC_EXTS``;
    globs and explicit files use the same filter."""
    import glob as _glob
    found: list[Path] = []
    seen: set[Path] = set()
    for src in sources:
        base = (root / src)
        if base.is_dir():
            matches = sorted(str(p) for p in base.rglob("*")
                             if p.is_file() and p.suffix.lower() in _TEXT_DOC_EXTS)
        elif any(ch in src for ch in "*?["):
            matches = sorted(_glob.glob(str(base), recursive=True))
        else:
            matches = [str(base)]
        for m in matches:
            p = Path(m).resolve()
            if (p.is_file() and p not in seen
                    and p.suffix.lower() in _TEXT_DOC_EXTS):
                seen.add(p); found.append(p)
    return found

def find_config(start: Path | None = None) -> Path | None:
    """Search cwd and up to 3 parents for configs/aideal.yaml."""
    cur = (start or Path.cwd()).resolve()
    for d in [cur, *cur.parents[:3]]:
        cand = d / "configs" / "aideal.yaml"
        if cand.exists():
            return cand
    return None

def load_tasks(cfg: AidealConfig) -> list[dict]:
    """Read integration_tasks.yaml -> list of {id, language, goal, apis}."""
    if not cfg.integration_tasks.exists():
        return []
    data = yaml.safe_load(cfg.integration_tasks.read_text(encoding="utf-8")) or {}
    return data.get("tasks", [])

def _call_sites(cfg: AidealConfig, name: str, limit: int = 6, ctx: int = 3) -> str:
    """Real usages of `name` across the repo (main + tests), with a few lines
    of context — how the codebase ITSELF calls this API."""
    pat = re.compile(rf"\.{re.escape(name)}\s*\(|\b{re.escape(name)}\s*\(")
    defpat = re.compile(rf"\bdef\s+{re.escape(name)}\b")
    hits: list[str] = []
    globs = (list(cfg.source_globs) + list(cfg.test_globs)
             + [g.replace(".scala", ".java") for g in cfg.source_globs])
    for g in globs:
        for p in _glob.glob(str(cfg.root / g), recursive=True):
            if len(hits) >= limit:
                break
            try:
                lines = Path(p).read_text(encoding="utf-8", errors="ignore").splitlines()
            except OSError:
                continue
            for i, ln in enumerate(lines):
                if pat.search(ln) and not defpat.search(ln):
                    lo, hi = max(0, i - ctx), min(len(lines), i + ctx + 1)
                    rel = str(Path(p).relative_to(cfg.root))
                    seg = "\n".join(f"{j+1:5d} | {lines[j]}" for j in range(lo, hi))
                    hits.append(f"// {rel}:{i+1}\n{seg}")
                    break   # one site per file keeps variety
    return "\n\n".join(hits) or "(no call sites found outside the definition)"

def _resolve(v):
    v = str(v)
    return str((cfg.root / v).resolve()) if (not v.startswith("/") and "/" in v) else v

def _consumed_type_counts(cfg: AidealConfig) -> dict:
    """How many public defs accept each base type as a PARAMETER — i.e. what the
    library's operations actually need loaded, weighted by demand. A reader whose
    return type has count 0 feeds nothing (a shadow reader, e.g. a Java* wrapper);
    a high count means many ops consume it. Codebase-agnostic: no hardcoded names."""
    from collections import Counter
    from .readme_agent import public_api_details
    c: Counter = Counter()
    for d in public_api_details(cfg):
        if d.get("visibility") == "public":
            for p in (d.get("params") or []):
                b = _base_type(p.get("type", ""))
                if b:
                    c[b] += 1
    return dict(c)

def _drop_unconsumed_lines(code: str, counts: dict) -> str:
    """Belt-and-suspenders: drop any generated `val x: T = ...` whose type T is
    consumed by no documented op (e.g. the model still reached for a Java wrapper)."""
    if not counts:
        return code
    kept = []
    for ln in code.splitlines():
        m = re.match(r"\s*val\s+\w+\s*:\s*([^=]+?)\s*=", ln)
        if m and _base_type(m.group(1)) and counts.get(_base_type(m.group(1)), 0) == 0:
            continue
        kept.append(ln)
    return "\n".join(kept).strip()

def _as_uri(p):
    p = str(p)
    if "://" in p:
        return p
    return f"file://{p}" if (use_uri and p.startswith("/")) else p

def _resolve(v):
    if isinstance(v, dict):
        package = v.get("package")
        resource = v.get("resource")
        if not package or not resource:
            raise ValueError("sample_data mapping requires both 'package' and 'resource'")
        from importlib.resources import files
        target = files(str(package)).joinpath(str(resource))
        if not target.is_file():
            raise FileNotFoundError(
                f"package resource not found: {package}:{resource}")
        return str(target)
    v = str(v)
    return str((cfg.root / v).resolve()) if (not v.startswith("/") and "/" in v) else v

def _strip_fences(text: str, *, strip_imports: bool = False) -> str:
    """Remove markdown code fences / language tags the model may emit despite
    instructions, so the snippet is pure code. When the scaffold owns imports,
    callers can also drop model-generated import lines to avoid stale/wrong
    imports shadowing curated scaffold imports."""
    t = text.strip()
    if "```" in t:
        # keep the content of the first fenced block if present, else strip fences
        import re as _re
        m = _re.search(r"```[a-zA-Z]*\n(.*?)```", t, _re.DOTALL)
        t = (m.group(1) if m else
             t.replace("```scala", "").replace("```python", "").replace("```", ""))
    if strip_imports:
        t = "\n".join(
            line for line in t.strip().splitlines()
            if not line.lstrip().startswith("import ")
        )
    return t.strip()

def _sha256_files(paths: list[Path], root: Path | None = None) -> dict:
    """Hash file names and contents deterministically for run provenance."""
    import hashlib

    digest = hashlib.sha256()
    files: list[Path] = []
    for path in paths:
        if path.is_file():
            files.append(path)
        elif path.is_dir():
            files.extend(p for p in path.rglob("*") if p.is_file())
    unique = sorted(set(p.resolve() for p in files), key=str)
    for path in unique:
        try:
            label = path.relative_to(root.resolve()) if root else path
        except ValueError:
            label = path
        digest.update(str(label).encode("utf-8"))
        digest.update(b"\0")
        try:
            with path.open("rb") as src:
                for chunk in iter(lambda: src.read(1024 * 1024), b""):
                    digest.update(chunk)
        except OSError as exc:
            digest.update(f"<unreadable:{type(exc).__name__}>".encode("utf-8"))
        digest.update(b"\0")
    return {"sha256": digest.hexdigest(), "file_count": len(unique)}

def _doc_path() -> Path:
    if api_doc:
        result = _path(api_doc)
        if not result.is_file():
            raise FileNotFoundError(f"puzzle documentation not found: {result}")
        return result
    if doc_source == "aideal":
        if not cfg.llm_readme.is_file():
            raise FileNotFoundError(f"generated documentation not found: {cfg.llm_readme}")
        return cfg.llm_readme
    parts: list[str] = []
    if doc_source in ("original", "original+aideal"):
        original = cfg.original_readme_text(limit=None)
        if not original.strip():
            raise FileNotFoundError("no configured original documentation for puzzle arm")
        parts.append(original)
    if doc_source == "original+aideal":
        parts.append("===== GENERATED AIDEAL DOCUMENTATION =====\n"
                     + cfg.llm_readme.read_text(encoding="utf-8", errors="ignore"))
    destination = cfg.root / ".aideal_exec" / "puzzle_docs" / f"{doc_source}.md"
    destination.parent.mkdir(parents=True, exist_ok=True)
    destination.write_text("\n\n".join(parts), encoding="utf-8")
    return destination

def _path(value: str) -> Path:
    p = Path(value)
    return p.resolve() if p.is_absolute() else (cfg.root / p).resolve()

def _build_catalogue_context(cfg: AidealConfig):
    """(model, name_to_gkey, by_name) for INDEX-FIRST comprehension, or None. Builds
    the SAME catalogue model `write_catalogue` renders, so the receiver line + the
    verified-sibling call pattern handed to the audience match the per-class files."""
    from .readme_agent import (_catalogue_model, _grounding_tiers, _exec_status_map,
                               parse_readme, public_api_details)
    entries = [e for e in parse_readme(cfg.llm_readme) if "TODO" not in e.body]
    if not entries:
        return None
    tiers, class_of, _ = _grounding_tiers(cfg)
    exec_status = _exec_status_map(cfg)
    owner = _owner_map(cfg)
    file_of = {d["name"]: d["file"] for d in public_api_details(cfg)}
    model = _catalogue_model(entries, tiers, exec_status, class_of, owner, file_of=file_of)
    name_to_gkey = {x["name"]: g for g, m in model.items() for x in m["members"]}
    return model, name_to_gkey, {e.name: e for e in entries}

def _comprehension_inventory(cfg: AidealConfig, doc_source: str,
                             manifest: list[str] | None = None,
                             full_doc: bool = False,
                             doc_scope: str | None = None):
    """Build (inventory, shared_doc, error_dict). shared_doc is None unless
    full_doc — then every entry's audience context = shared_doc + target line
    (built late in the execute loop; bodies stay empty to avoid duplicating a
    multi-MB document per entry)."""
    from .readme_agent import ApiEntry
    if doc_scope == "relevant":
        names = manifest or (sorted(public_api_surface(cfg)) if doc_source.startswith("original")
                             else [e.name for e in parse_readme(cfg.llm_readme)
                                   if "TODO" not in e.body])
        return _relevant_doc_inventory(cfg, doc_source, names), None, None
    if full_doc:
        # denominator: the frozen manifest if given, else the doc's own names
        if manifest:
            names = manifest
        elif doc_source in ("original", "original+aideal"):
            names = sorted(public_api_surface(cfg))
        else:
            names = [e.name for e in parse_readme(cfg.llm_readme)
                     if "TODO" not in e.body]
        try:
            shared = _shared_doc_text(cfg, doc_source)
        except FileNotFoundError as exc:
            return None, None, {"check": "comprehension", "passed": False, "score": 0.0,
                                "details": {"error": str(exc)}}
        if not shared.strip():
            return None, None, {"check": "comprehension", "passed": False, "score": 0.0,
                                "details": {"error": f"no documentation text for "
                                            f"doc_source={doc_source}"}}
        return [ApiEntry(name=n, goal="", snippet="", body="") for n in names], \
            shared, None
    if doc_source == "original":
        if not cfg.original_readme_files:
            return None, None, {"check": "comprehension", "passed": False, "score": 0.0,
                                "details": {"error": "files.original_readme not configured or missing"}}
        text = cfg.original_readme_text(limit=12000)   # legacy (non-full-doc) mode
        names = manifest or sorted(public_api_surface(cfg))
        return [ApiEntry(name=n, goal="", snippet="",
                         body=f"(Original project README — the only documentation available)\n"
                              f"{text}\n\nTarget function: `{n}`")
                for n in names], None, None
    if doc_source == "agents":
        # BASELINE ARM: the repo's holistic agent guide (AGENTS.md) as the ONLY
        # context — the industry-standard single-file "how to work in this repo"
        # doc. Path from files.agents_doc (default AGENTS.md at project root).
        from pathlib import Path
        rel = (cfg.raw.get("files", {}) or {}).get("agents_doc", "AGENTS.md")
        p = (cfg.root / rel)
        if not p.exists():
            return None, None, {"check": "comprehension", "passed": False, "score": 0.0,
                                "details": {"error": f"agents doc not found at {rel} "
                                            "(set files.agents_doc, or drop an AGENTS.md at project root)"}}
        text = p.read_text(encoding="utf-8", errors="ignore")[:12000]
        names = manifest or sorted(public_api_surface(cfg))
        return [ApiEntry(name=n, goal="", snippet="",
                         body=f"(Project AGENTS.md — the only agent guidance available)\n"
                              f"{text}\n\nTarget function: `{n}`")
                for n in names], None, None
    inventory = [e for e in parse_readme(cfg.llm_readme) if "TODO" not in e.body]
    if manifest:
        by = {e.name: e for e in inventory}
        inventory = [by[n] for n in manifest if n in by]
    if not inventory:
        return None, None, {"check": "comprehension", "doc_source": doc_source, "passed": False,
                            "score": 0.0,
                            "details": {"error": "LLM_readme has no filled entries (skeleton TODOs "
                                                 "don't count) - run `readme --generate` or fill them"}}
    return inventory, None, None

def _markdown_chunks(text: str) -> list[str]:
    """Stable file/heading chunks for deterministic, non-LLM retrieval."""
    chunks: list[str] = []
    file_header = ""
    current: list[str] = []
    fence: tuple[str, int] | None = None
    for line in text.splitlines():
        stripped = line.lstrip()
        # Synthetic file boundaries are authoritative and reset malformed or
        # unclosed Markdown state from the previous source file.
        if line.startswith("===== ") and line.endswith(" ====="):
            if current:
                chunks.append("\n".join(([file_header] if file_header else []) + current).strip())
            file_header, current, fence = line, [], None
            continue
        fm = re.match(r"^(`{3,}|~{3,})", stripped)
        if fm:
            token = fm.group(1)
            marker = (token[0], len(token))
            if fence is None:
                fence = marker
            elif marker[0] == fence[0] and marker[1] >= fence[1]:
                fence = None
        if fence is None and re.match(r"^#{1,6}\s+", line) and current:
            chunks.append("\n".join(([file_header] if file_header else []) + current).strip())
            current = [line]
        else:
            current.append(line)
    if current:
        chunks.append("\n".join(([file_header] if file_header else []) + current).strip())
    return [c for c in chunks if c]

def _relevant_doc_inventory(cfg: AidealConfig, doc_source: str, names: list[str]):
    """Per-API relevant documentation with one equal character ceiling per source."""
    from .readme_agent import ApiEntry
    limit = int((cfg.comprehension or {}).get("relevant_doc_chars", 12000) or 12000)
    generated = {e.name: e for e in parse_readme(cfg.llm_readme)} if cfg.llm_readme.exists() else {}
    part_limit = limit // 2 if doc_source == "original+aideal" else limit
    original = (_relevant_original_texts(cfg, names, part_limit)
                if doc_source in ("original", "original+aideal") else {})
    inventory = []
    for name in names:
        parts: list[str] = []
        if doc_source in ("original", "original+aideal"):
            parts.append(original[name])
        if doc_source in ("aideal", "original+aideal"):
            entry = generated.get(name)
            if entry:
                parts.append(entry.body[:part_limit])
        body = "\n\n===== RELATED DOCUMENTATION =====\n\n".join(parts)[:limit]
        inventory.append(ApiEntry(name=name, goal="", snippet="", body=body))
    return inventory

def _resolve_class_context(cfg: AidealConfig, override: bool | None) -> bool:
    """CLI override wins; else the `comprehension.class_context` config flag (default off)."""
    if override is not None:
        return override
    return bool((cfg.comprehension or {}).get("class_context", False))

def _shared_doc_text(cfg: AidealConfig, doc_source: str) -> str:
    """FULL-DOCUMENT audience context (no truncation — the experiment requires
    the audience to receive the ENTIRE selected documentation; the size is
    recorded in the run JSON so exposure is auditable).

      original         -> every configured baseline doc, whole
      aideal           -> the whole generated LLM_readme.md
      original+aideal  -> both (the B1 arm: original docs + entries the
                          doc-repair loop has created so far)
    """
    parts: list[str] = []
    if doc_source in ("original", "original+aideal"):
        parts.append(cfg.original_readme_text(limit=None))
    if doc_source in ("aideal", "original+aideal"):
        if cfg.llm_readme.exists():
            parts.append("===== GENERATED / REPAIRED API ENTRIES =====\n"
                         + cfg.llm_readme.read_text(encoding="utf-8", errors="ignore"))
        elif doc_source == "aideal":
            raise FileNotFoundError(f"{cfg.llm_readme} missing (doc_source=aideal)")
    return "\n\n".join(p for p in parts if p.strip())

def completeness_check(cfg: AidealConfig) -> dict:
    surface = public_api_surface(cfg)                       # intended-API set
    raw = public_api_surface(cfg, override_filter="all")    # raw discovered surface
    documented = {_normalize(e.name) for e in parse_readme(cfg.llm_readme)}
    undocumented = sorted(surface - documented)
    n = len(surface)
    return {
        "check": "completeness",
        "passed": not undocumented,
        "score": round((n - len(undocumented)) / n, 3) if n else 0.0,
        "details": {
            "raw_surface": len(raw),               # every visible public def
            "intended_surface": n,                 # surface_filter set = denominator
            "surface_filter": cfg.surface_filter,
            "public_functions": n,                 # (= intended_surface; kept for back-compat)
            "documented": len(documented),
            "undocumented": undocumented,
            "orphan_doc_entries": sorted(documented - surface),
        },
    }

def form_check(cfg: AidealConfig) -> dict:
    inventory = parse_readme(cfg.llm_readme)
    failures: dict[str, list[str]] = {}
    for entry in inventory:
        missing = [
            req for req in cfg.required_sections
            if not any(re.search(rf"^### {re.escape(a)}\s*$", entry.body, re.MULTILINE)
                       for a in req.split("|"))
        ]
        if "TODO" in entry.body:
            missing.append("unfilled TODOs")  # a skeleton is not documentation
        if missing:
            failures[entry.name] = missing
    n = len(inventory)
    return {
        "check": "form",
        "passed": bool(n) and not failures,
        "score": round((n - len(failures)) / n, 3) if n else 0.0,
        "details": {"apis": n, "complete": n - len(failures), "missing_sections": failures},
    }

class _Text(HTMLParser):
    def __init__(self):
        super().__init__()
        self.parts: list[str] = []
        self.skip = 0

    def handle_starttag(self, tag, attrs):
        if tag in {"script", "style"}:
            self.skip += 1
        elif not self.skip and tag in {"p", "div", "section", "article", "li",
                                       "h1", "h2", "h3", "h4", "pre", "br", "tr"}:
            self.parts.append("\n")

    def handle_endtag(self, tag):
        if tag in {"script", "style"} and self.skip:
            self.skip -= 1
        elif not self.skip and tag in {"p", "div", "section", "article", "li",
                                       "h1", "h2", "h3", "h4", "pre", "tr"}:
            self.parts.append("\n")

    def handle_data(self, data):
        if not self.skip:
            self.parts.append(data)

    def text(self) -> str:
        text = "".join(self.parts).replace("\r", "")
        text = re.sub(r"[ \t]+", " ", text)
        text = re.sub(r"\n{3,}", "\n\n", text)
        return text.strip()

def handle_data(self, data):
    if not self.skip:
        self.parts.append(data)

def handle_endtag(self, tag):
    if tag in {"script", "style"} and self.skip:
        self.skip -= 1
    elif not self.skip and tag in {"p", "div", "section", "article", "li",
                                   "h1", "h2", "h3", "h4", "pre", "tr"}:
        self.parts.append("\n")

def handle_starttag(self, tag, attrs):
    if tag in {"script", "style"}:
        self.skip += 1
    elif not self.skip and tag in {"p", "div", "section", "article", "li",
                                   "h1", "h2", "h3", "h4", "pre", "br", "tr"}:
        self.parts.append("\n")

def text(self) -> str:
    text = "".join(self.parts).replace("\r", "")
    text = re.sub(r"[ \t]+", " ", text)
    text = re.sub(r"\n{3,}", "\n\n", text)
    return text.strip()

def _err_sig(category: str, message: str) -> str:
    """Normalized error signature (shared with fixreport) for progress checks."""
    from .fixreport import error_signature
    return error_signature(category or "", message or "")

def _outcomes(results: dict[str, dict]) -> dict[str, int]:
    from collections import Counter
    return dict(Counter(v.get("status", "unknown").split(" ")[0]
                        for v in results.values()))

def _read_report(path: str | Path | None) -> dict | None:
    if not path:
        return None
    p = Path(path)
    if not p.exists() or p.stat().st_size == 0:
        return None
    try:
        return json.loads(p.read_text(encoding="utf-8"))
    except json.JSONDecodeError as exc:
        raise ValueError("Corrupt document-repair report; preserve and inspect it") from exc

def _remove_entry_text(text: str, name: str) -> str:
    """Delete an entry created by this run (all-rounds-fail in create-missing
    mode reverts to ABSENT, keeping the catalog exactly as found)."""
    pat = re.compile(rf"(?ms)^## API Test: `{re.escape(name)}`.*?(?=^## API Test: `|\Z)")
    return pat.sub("", text, count=1)

def _replace_entry_text(text: str, name: str, new_entry: str) -> str:
    """Replace the `## API Test: `name`` section (up to the next entry or EOF).
    Pure function so it is unit-testable. Raises KeyError if absent."""
    pat = re.compile(rf"(?ms)^## API Test: `{re.escape(name)}`.*?(?=^## API Test: `|\Z)")
    if not pat.search(text):
        raise KeyError(name)
    repl = new_entry.rstrip() + "\n\n"
    return pat.sub(lambda _m: repl, text, count=1)

def _type_context(cfg: AidealConfig, name: str, max_types: int = 4,
                  lines_per_type: int = 35) -> str:
    """Definitions of receiver/parameter/return types found in configured source.

    This intentionally follows ``source_globs`` rather than assuming a language
    pair.  The declaration pattern covers common class/type constructs; projects
    with unusual syntax still get an explicit "not found" instead of a fabricated
    definition.
    """
    import glob as _glob
    from .readme_agent import public_api_details, _subsume_overloads, _dedup_deprioritize
    recs = [d for d in public_api_details(cfg)
            if d["visibility"] == "public" and d["name"] == name]
    if not recs:
        return "(no public definition found)"
    canon = _subsume_overloads(recs, _dedup_deprioritize(cfg))[0][0]
    sig = " ".join([canon.get("signature") or "", canon.get("returns") or ""] +
                   [p.get("type") or "" for p in canon.get("params", [])])
    types = [t for t in dict.fromkeys(re.findall(r"\b([A-Z][A-Za-z0-9]{2,})\b", sig))
             if t not in _TYPE_SKIP][:max_types]
    if not types:
        return "(signature uses only primitive/collection types)"
    pats = {t: re.compile(rf"\b(?:case\s+class|abstract\s+class|class|trait|object|"
                              rf"interface|enum|struct|record|type)\s+{t}\b")
            for t in types}
    found: dict[str, str] = {}
    extra_globs = (((cfg.raw or {}).get("codebase") or {})
                   .get("type_context_globs") or [])
    for g in dict.fromkeys([*cfg.source_globs, *extra_globs]):
        if len(found) == len(types):
            break
        for p in _glob.glob(str(cfg.root / g), recursive=True):
            if len(found) == len(types):
                break
            try:
                text = Path(p).read_text(encoding="utf-8", errors="ignore")
            except OSError:
                continue
            for t, pat in pats.items():
                if t in found:
                    continue
                m = pat.search(text)
                if m:
                    lines = text.splitlines()
                    ln = text[:m.start()].count("\n")
                    seg = "\n".join(lines[ln:ln + lines_per_type])
                    rel = str(Path(p).relative_to(cfg.root))
                    suffix = Path(p).suffix.lstrip(".") or cfg.language
                    found[t] = f"// type {t} ({suffix} source) — {rel}:{ln + 1}\n{seg}"
    return "\n\n".join(found.get(t, f"// type {t}: definition NOT found in sources")
                       for t in types)

class ErrorLog:
    def __init__(self, path: Path):
        self.path = path

    def append(self, **record) -> dict:
        if not record.get("run_id"):
            record["run_id"] = new_run_id()
        if not record.get("status"):
            record["status"] = "fail"
        if not record.get("timestamp"):
            record["timestamp"] = time.strftime("%Y-%m-%dT%H:%M:%SZ", time.gmtime())
        entry = {k: record.get(k, "") for k in FIELDS}
        self.path.parent.mkdir(parents=True, exist_ok=True)
        with self.path.open("a", encoding="utf-8") as f:
            f.write(json.dumps(entry, ensure_ascii=False) + "\n")
        return entry

    def entries(self) -> list[dict]:
        if not self.path.exists():
            return []
        out = []
        for line in self.path.read_text(encoding="utf-8").splitlines():
            line = line.strip()
            if line:
                try:
                    out.append(json.loads(line))
                except json.JSONDecodeError:
                    continue
        return out

    def to_prompt(self, max_entries: int = 15, task: str | None = None) -> str:
        """Compact token-efficient render: `function: error -> fix (xN)`."""
        seen: Counter = Counter()
        fixes: dict[tuple, str] = {}
        for e in self.entries():
            if task and e.get("task") != task:
                continue
            key = (e.get("function", ""), e.get("error", ""))
            seen[key] += 1
            if e.get("suggested_fix_code"):
                fixes[key] = e["suggested_fix_code"]
        if not seen:
            return ""
        lines = ["Known failures to avoid (function: error -> fix):"]
        for (fn, err), n in seen.most_common(max_entries):
            fix = fixes.get((fn, err), "")
            lines.append(f"- {fn}: {err}" + (f" -> {fix}" if fix else "") + (f" (x{n})" if n > 1 else ""))
        return "\n".join(lines)

    def failures_for(self, function: str, max_items: int = 4) -> str:
        """Compact render of prior failures for ONE function, to feed back into
        the next generation/repair attempt. Pairs error -> fix when known."""
        rows = [e for e in self.entries()
                if e.get("function") == function and e.get("status") in ("fail", "fixed")]
        if not rows:
            return ""
        lines = [f"Prior failures for `{function}` — avoid repeating these:"]
        for e in rows[-max_items:]:
            cat = e.get("error_category", "") or "error"
            line = f"- [{cat}] {e.get('error','').strip()[:200]}"
            if e.get("root_cause"):
                line += f"  (at: {e['root_cause'].strip()[:120]})"
            if e.get("suggested_fix_code"):
                # `fixed` rows carry real working code; `fail` rows carry a
                # FIX_GUIDE hint (what kind of fix). Label accordingly so the model
                # isn't told a hint is proven code.
                label = "fix that worked" if e.get("status") == "fixed" else "suggested fix"
                line += f"\n  {label}: {e['suggested_fix_code'].strip()[:300]}"
            lines.append(line)
        return "\n".join(lines)

    def suggest_aliases(self) -> list[dict]:
        """Hallucinated names are evidence of what models EXPECT the API to be
        called — i.e., good alias candidates."""
        candidates: Counter = Counter()
        context: dict[str, str] = {}
        for e in self.entries():
            for text in (e.get("error", ""), e.get("root_cause", "")):
                m = HALLUCINATED_NAME_RE.search(text)
                if m:
                    name = next(g for g in m.groups() if g)
                    candidates[name] += 1
                    context[name] = e.get("function", "") or e.get("task", "")
        return [
            {"proposed_alias": name, "for": context[name], "evidence_count": n}
            for name, n in candidates.most_common()
        ]

