def run_command(command, *, cwd, env, timeout):
    if os.name != 'posix':
        raise RuntimeError('Process-group execution requires POSIX; configure a supported runner')
    blocked = Path(cwd) / '.aideal_unreconciled_process.json'
    if blocked.exists():
        raise CleanupError(f'Unreconciled process evidence at {blocked}; execution blocked')
    proc = subprocess.Popen(command, shell=True, cwd=cwd, env=env,
                            stdout=subprocess.PIPE, stderr=subprocess.PIPE,
                            text=True, start_new_session=True)
    try:
        stdout, stderr = proc.communicate(timeout=timeout)
        return subprocess.CompletedProcess(command, proc.returncode, stdout, stderr)
    except BaseException as exc:
        def uncertain(message, cause):
            temporary = blocked.with_suffix(f'.{os.getpid()}.tmp')
            temporary.write_text(json.dumps({'process_group': proc.pid, 'reason': message,
                                            'recorded_epoch': time.time()}) + '\n')
            temporary.replace(blocked)
            raise CleanupError(message) from cause
        # Kill the group even if its shell has already exited: children may remain.
        denied = None
        for sig in (signal.SIGTERM, signal.SIGKILL):
            try:
                os.killpg(proc.pid, sig)
            except ProcessLookupError:
                pass
            except PermissionError as error:
                denied = error
                break
            if sig == signal.SIGTERM:
                time.sleep(.1)
        try:
            stdout, stderr = proc.communicate(timeout=2)
        except subprocess.TimeoutExpired:
            # An escaped process may hold a pipe. Never wait without a bound.
            proc.stdout.close()
            proc.stderr.close()
            try:
                proc.wait(timeout=2)
            except subprocess.TimeoutExpired:
                uncertain(f'Process group {proc.pid} did not stop; manual reconciliation required', exc)
            stdout, stderr = '', 'Output pipe remained open outside the owned process group'
        if denied is not None:
            uncertain(f'Permission denied stopping process group {proc.pid}; '
                      'do not resume this output namespace until reconciled', denied)
        if isinstance(exc, subprocess.TimeoutExpired):
            exc.output, exc.stderr = stdout, stderr
            exc.cleanup = {'process_group': proc.pid, 'termination_requested': True,
                           'shell_reaped': proc.returncode is not None}
        raise

def digest(value):
    raw = value if isinstance(value, bytes) else json.dumps(value, sort_keys=True, default=str).encode()
    return hashlib.sha256(raw).hexdigest()

def digest_native(components):
    return hashlib.sha256(json.dumps(components, sort_keys=True, separators=(',', ':'),
                                     default=str).encode()).hexdigest()

def prompt_contract(cfg):
    result = {}
    for name in ('comprehension_write_exec',):
        path = prompts_dir(cfg) / f'aideal/{name}.md'
        if not path.exists():
            path = DEFAULT_PROMPTS / f'aideal/{name}.md'
        result[name] = digest(path.read_bytes())
    profile = profile_path(cfg)
    return {'templates': result,
            'profile_sha256': digest(profile.read_bytes()) if profile.exists() else None}

def transport_contract():
    timeout = float(os.environ.get('AIDEAL_GOOGLE_REQUEST_TIMEOUT_S', '300'))
    attempts = int(os.environ.get('AIDEAL_GOOGLE_MAX_RETRIES', '2'))
    if timeout <= 0 or attempts < 1:
        raise ValueError('Invalid provider deadline or SDK-attempt count')
    return {'temperature': 0.0, 'google_request_timeout_s': timeout,
            'google_sdk_attempts': attempts, 'google_outer_deadline_s': timeout * attempts + 30,
            'adapter_sha256': os.environ.get('AIDEAL_TRANSPORT_ADAPTER_SHA256'),
            'policy_sha256': os.environ.get('AIDEAL_TRANSPORT_POLICY_SHA256'),
            'setup_policy_sha256': os.environ.get('AIDEAL_SETUP_POLICY_SHA256')}

def classify(stderr: str) -> tuple[str, str]:
    """Return (category, fix_hint) for the first matching fix-guide rule."""
    for pat, cat, hint in FIX_GUIDE:
        if re.search(pat, stderr or ""):
            return cat, hint
    return "unknown", "Re-read the doc entry's Signature and Valid Call Patterns."

def _details_error(det) -> tuple[str, str]:
    """(category, message) from a comprehension `details[name]` value —
    a plain string, a show-code dict, or a {status, rounds} dict whose real
    error lives in the last failing round."""
    if isinstance(det, dict):
        cat = det.get("error_category", "") or ""
        msg = det.get("error", "") or ""
        if not msg:
            for r in reversed(det.get("rounds") or []):
                if r.get("status") == "fail" and r.get("error"):
                    cat, msg = cat or r.get("category", ""), r.get("error", "")
                    break
        if not msg:
            m = re.match(r"fail \[([^\]]+)\]:\s*(.*)", str(det.get("status") or ""))
            if m:
                cat, msg = cat or m.group(1), m.group(2)
        return cat, msg
    if isinstance(det, str):
        m = re.match(r"fail \[([^\]]+)\]:\s*(.*)", det)
        if m:
            return m.group(1), m.group(2)
    return "", str(det or "")

def _last_sig(api: dict, *, mask_names: bool = False) -> str:
    return error_signature(api.get("error_category", ""), api.get("error", ""),
                           mask_names=mask_names)

def _rounds_of(det) -> list[dict]:
    if isinstance(det, dict) and isinstance(det.get("rounds"), list):
        return det["rounds"]
    return []

def _short(text: str, width: int = 220) -> str:
    """Readability: collapse absolute file paths to basenames in error heads."""
    return _ABS_SRC.sub(r"\1:", text or "")[:width]

def _stuckness(rounds: list[dict]) -> str:
    """Human verdict on the loop's trajectory for one API."""
    fails = [r for r in rounds if r.get("status") == "fail"]
    if not fails:
        return ""
    sigs = [error_signature(r.get("category", ""), r.get("error", "")) for r in fails]
    if any(r.get("status") == "stuck-stop" for r in rounds):
        return f"STUCK (stopped: same error repeated; {len(fails)} failing rounds)"
    if len(set(sigs)) == 1 and len(sigs) > 1:
        return f"STUCK (same error x{len(sigs)}, never changed)"
    if len(set(sigs)) < len(sigs):
        return f"CHURNING ({len(set(sigs))} distinct errors over {len(sigs)} rounds)"
    return f"PROGRESSING (error changed every round, {len(sigs)} rounds)"

def cluster_failures(run: dict, top: int = 12) -> list[dict]:
    """Cross-API clustering of the run's failures by masked signature —
    'which ONE issue is costing the most APIs'."""
    groups: dict[str, list[str]] = {}
    for n, v in run["apis"].items():
        if v["status"] == "pass":
            continue
        groups.setdefault(_last_sig(v, mask_names=True), []).append(n)
    out = [{"signature": sig, "count": len(names), "apis": sorted(names)}
           for sig, names in groups.items()]
    out.sort(key=lambda g: -g["count"])
    return out[:top]

def compare_runs(run: dict, baseline: dict) -> dict:
    """fail->pass / pass->fail / still-failing split into same-signature
    (the issue is NOT being solved) vs changed-signature (churn/progress)."""
    a, b = baseline["apis"], run["apis"]
    both = sorted(set(a) & set(b))
    only_run = sorted(set(b) - set(a))
    only_base = sorted(set(a) - set(b))
    fixed = [n for n in both if a[n]["status"] != "pass" and b[n]["status"] == "pass"]
    regressed = [n for n in both if a[n]["status"] == "pass" and b[n]["status"] != "pass"]
    still = [n for n in both if a[n]["status"] != "pass" and b[n]["status"] != "pass"]
    same_issue, changed_issue = [], []
    for n in still:
        if _last_sig(a[n]) == _last_sig(b[n]):
            same_issue.append(n)
        else:
            changed_issue.append((n, _last_sig(a[n]), _last_sig(b[n])))
    def _cats(apis):
        from collections import Counter
        return dict(Counter(v.get("error_category") or "?" for v in apis.values()
                            if v["status"] != "pass"))
    return {"fixed": fixed, "regressed": regressed,
            "still_same_issue": same_issue, "still_changed_issue": changed_issue,
            "only_in_run": only_run, "only_in_baseline": only_base,
            "pass_run": sum(1 for v in b.values() if v["status"] == "pass"),
            "pass_base": sum(1 for v in a.values() if v["status"] == "pass"),
            "n_run": len(b), "n_base": len(a),
            "cats_run": _cats(b), "cats_base": _cats(a)}

def _cats(apis):
    from collections import Counter
    return dict(Counter(v.get("error_category") or "?" for v in apis.values()
                        if v["status"] != "pass"))

def load_run(path: str | Path) -> dict:
    """Normalize a result JSON (comprehension or fix-docs) into
    {kind, run_id, models, apis: {name: {...}}, meta}."""
    obj = json.loads(Path(path).read_text(encoding="utf-8"))
    kind = obj.get("check", "comprehension")
    apis: dict[str, dict] = {}
    if kind == "fix-docs":
        for name, r in (obj.get("apis") or {}).items():
            retry = r.get("retry") or {}
            status = (r.get("status") or "").split(" ")[0]
            # iterative mode: map the doc_rounds trail (deep-dive -> rewrite ->
            # run per round, with understanding flags) onto the generic rounds
            # shape so the per-API timeline renders like any fix loop.
            rounds = []
            last_cat, last_err = retry.get("error_category") or "", ""
            for dr in (r.get("doc_rounds") or []):
                flags = []
                if "diagnosis_changed" in dr:
                    flags.append("new diagnosis" if dr["diagnosis_changed"]
                                 else "diagnosis UNCHANGED")
                if "error_progressed" in dr:
                    flags.append("error moved" if dr["error_progressed"]
                                 else "error SAME")
                note = f"[{'; '.join(flags)}] " if flags else ""
                if dr.get("outcome"):          # rejected / not-testable rounds
                    rounds.append({"round": dr.get("round"), "status": "fail",
                                   "category": "doc-repair",
                                   "error": note + dr["outcome"]})
                    continue
                ok = dr.get("retry_status") == "pass"
                rounds.append({"round": dr.get("round"),
                               "status": "pass" if ok else "fail",
                               "category": dr.get("error_category") or "",
                               "error": note + (dr.get("error_head") or "")})
                if not ok:
                    last_cat = dr.get("error_category") or last_cat
                    last_err = dr.get("error_head") or last_err
            apis[name] = {
                "status": "pass" if status in ("doc-fixed", "doc-created") else "fail",
                "outcome": r.get("status", ""),
                "attempts": r.get("rounds_used") or retry.get("attempts"),
                "pass_round": retry.get("pass_round"),
                "error_category": last_cat,
                "error": last_err,
                "source": retry.get("source"),
                "frames": retry.get("codebase_frames") or [],
                "rounds": rounds,
                "diagnosis_head": r.get("diagnosis_head", ""),
                "tokens": r.get("tokens"),
                "wall_s": r.get("wall_s"),
            }
        meta = {k: obj.get(k) for k in ("model", "target_source", "attempted",
                                        "doc_fixed", "fix_rate", "outcomes",
                                        "deep_dive_first", "doc_rounds",
                                        "retry_rounds")}
        return {"kind": kind, "run_id": None, "models": {"fixer": obj.get("model")},
                "apis": apis, "meta": meta, "raw": obj}
    metrics = obj.get("metrics") or {}
    details = obj.get("details") or {}
    for name, m in metrics.items():
        if not isinstance(m, dict):
            continue
        det = details.get(name)
        cat, msg = _details_error(det)
        apis[name] = {
            "status": m.get("status", ""),
            "outcome": m.get("status", ""),
            "attempts": m.get("attempts"),
            "pass_round": m.get("pass_round"),
            "error_category": m.get("error_category") or cat,
            "error": msg,
            "source": m.get("source"),
            "frames": m.get("codebase_frames") or [],
            "rounds": _rounds_of(det),
            "tokens": {"in": m.get("input_tokens"), "out": m.get("output_tokens")},
            "wall_s": m.get("wall_s"),
        }
    run = obj.get("run") or {}
    meta = {"score": obj.get("score"), "score_with_infra": obj.get("score_with_infra"),
            "infra_excluded": obj.get("infra_excluded"),
            "wall_s": run.get("wall_s"), "usage": run.get("usage"),
            "max_fix_rounds": run.get("max_fix_rounds"),
            "class_context": run.get("class_context")}
    return {"kind": kind, "run_id": run.get("run_id"), "models": run.get("models") or {},
            "apis": apis, "meta": meta, "raw": obj}

def recurrence(log_entries: list[dict], names: list[str]) -> dict[str, dict]:
    """Cross-RUN persistence per failing API: how many distinct runs recorded a
    failure, whether the LAST error signature is identical across those runs
    (same issue never solved), and when it was first seen."""
    out: dict[str, dict] = {}
    for n in names:
        rows = [e for e in log_entries if e.get("function") == n
                and e.get("status") == "fail"]
        if not rows:
            continue
        by_run: dict[str, dict] = {}
        for e in rows:
            by_run[e.get("run_id") or "?"] = e          # keep last row per run
        sigs = [error_signature(e.get("error_category", ""), e.get("error", ""))
                for e in by_run.values()]
        out[n] = {"runs_failed": len(by_run),
                  "same_sig_runs": max((sigs.count(s) for s in set(sigs)), default=0),
                  "distinct_sigs": len(set(sigs)),
                  "first_seen": min((e.get("timestamp") or "" for e in rows),
                                    default="")[:10]}
    return out

def get_chat_model(spec: ModelSpec, temperature: float = 0.0):
    """Return a LangChain chat model for the given provider/model."""
    provider = spec.provider.lower()
    if provider == "openai":
        from langchain_openai import ChatOpenAI
        return ChatOpenAI(model=spec.model, temperature=temperature)
    if provider in ("openai-responses", "codex"):
        # OpenAI Responses API — the Codex-style endpoint, the "codex api" arm
        # of the backend micro-benchmark (vs plain chat-completions "openai").
        # Codex/reasoning models reject non-default temperature, so none is set.
        from langchain_openai import ChatOpenAI
        return ChatOpenAI(model=spec.model, use_responses_api=True)
    if provider == "anthropic":
        from langchain_anthropic import ChatAnthropic
        return ChatAnthropic(model=spec.model, temperature=temperature)
    if provider == "google":
        from langchain_google_genai import ChatGoogleGenerativeAI
        # A socket waiting for response headers previously blocked an experiment
        # for >80 minutes. Bound each provider request while retaining retries;
        # both knobs are environment-overridable and do not change prompts,
        # scoring, or the logical fix-round treatment.
        timeout = float(os.environ.get("AIDEAL_GOOGLE_REQUEST_TIMEOUT_S", "300"))
        retries = int(os.environ.get("AIDEAL_GOOGLE_MAX_RETRIES", "2"))
        return ChatGoogleGenerativeAI(
            model=spec.model,
            temperature=temperature,
            request_timeout=timeout,
            retries=retries,
        )
    if provider == "ollama":
        import os as _os
        from langchain_ollama import ChatOllama
        # Ollama's DEFAULT context (~4K) silently truncates AIDEAL's prompts
        # (entry + source window + type context ≈ 6-10K tokens) — the local
        # arm would fail for truncation, not model quality. 16K default;
        # override with AIDEAL_OLLAMA_NUM_CTX (raise for 32B models w/ RAM).
        return ChatOllama(model=spec.model, temperature=temperature,
                          num_ctx=int(_os.environ.get("AIDEAL_OLLAMA_NUM_CTX", 16384)))
    raise ValueError(f"Unknown provider: {spec.provider}")

def invoke_text(spec: ModelSpec, system: str, user: str) -> str:
    """One-shot text completion; returns the model's text content and adds the
    provider-reported token usage to the module accumulator."""
    if spec.provider.lower() == "aideal-codex-audited":
        from workflow.native_provider_bridge import invoke_native
        record = invoke_native(spec, system, user)
        _record_usage(spec, record.get("usage", {}))
        return record["code"]
    if getattr(spec, "bridge", None) is not None:
        raise ValueError("Audited bridge configuration cannot use a direct provider")
    llm = get_chat_model(spec)
    _wait_for_provider_slot(spec)
    from .provider_deadline import provider_deadline
    import sys
    budget = 0.0
    if spec.provider.lower() == "google":
        budget = (float(os.environ.get("AIDEAL_GOOGLE_REQUEST_TIMEOUT_S", "300"))
                  * max(1, int(os.environ.get("AIDEAL_GOOGLE_MAX_RETRIES", "2"))) + 30)
    started = time.monotonic()
    print(f"[provider] start model={spec.provider}:{spec.model} wall_limit_s={budget:g}",
          file=sys.stderr, flush=True)
    try:
        with provider_deadline(budget):
            resp = llm.invoke([("system", system), ("user", user)])
    except Exception as exc:
        print(f"[provider] failed type={type(exc).__name__} wall_s={time.monotonic()-started:.1f}",
              file=sys.stderr, flush=True)
        raise
    print(f"[provider] complete wall_s={time.monotonic()-started:.1f}", file=sys.stderr, flush=True)
    u = getattr(resp, "usage_metadata", None) or {}
    _record_usage(spec, u)
    c = resp.content
    if isinstance(c, str):
        return c
    if isinstance(c, list):
        # Responses API text blocks preserve their text, without Python reprs.
        parts = []
        for b in c:
            if isinstance(b, dict):
                parts.append(b.get("text") or b.get("content") or "")
            elif isinstance(b, str):
                parts.append(b)
        return "".join(parts)
    return str(c)

def usage_delta(before: dict) -> dict:
    """Usage accumulated since `before` (a usage_snapshot()), incl. per-model
    split — in a mixed-role run (writer=openai, fixer=gemini) the split shows
    who spent what."""
    now = usage_snapshot()
    by_model = {}
    for k, v in now["by_model"].items():
        b = before.get("by_model", {}).get(k, {})
        d = {kk: v[kk] - b.get(kk, 0) for kk in ("calls", "input_tokens", "output_tokens")}
        if any(d.values()):
            by_model[k] = d
    return {"calls": now["calls"] - before["calls"],
            "input_tokens": now["input_tokens"] - before["input_tokens"],
            "output_tokens": now["output_tokens"] - before["output_tokens"],
            "by_model": by_model}

def usage_snapshot() -> dict:
    """Copy of the running usage totals (safe to keep across further calls)."""
    return {"calls": _USAGE["calls"], "input_tokens": _USAGE["input_tokens"],
            "output_tokens": _USAGE["output_tokens"],
            "by_model": {k: dict(v) for k, v in _USAGE["by_model"].items()}}

