def _kind_for_signature(signature: str, params, returns: str) -> str | None:
    blob = " ".join([signature or "", returns or "",
                     " ".join((p.get("type", "") or "") for p in (params or []))])
    for rx, kind in _TYPE_HINTS:
        if rx.search(blob):
            return kind
    return None

def _pick_input(sample_data: dict, signature: str, params, returns: str) -> str:
    """Return the sample_data KEY whose kind best matches the signature, else the
    first non-output input. `raster_tif` -> kind `raster`, etc."""
    kind = _kind_for_signature(signature, params, returns)
    if kind:
        for key in sample_data:
            if key == "output_dir":
                continue
            if key.split("_")[0] == kind:
                return key
    for key in sample_data:               # fallback: first real input
        if key != "output_dir":
            return key
    return ""

def init_agents_md(cfg: AidealConfig) -> dict:
    """Write AGENTS.md with the AIDEAL section if absent (never clobbers)."""
    path = cfg.root / "AGENTS.md"
    if path.exists():
        if "AIDEAL" in path.read_text(encoding="utf-8"):
            return {"agents_md": "already present"}
        with path.open("a", encoding="utf-8") as f:
            f.write("\n" + AGENTS_SNIPPET)
        return {"agents_md": "appended AIDEAL section"}
    path.write_text("# Agent instructions\n\n" + AGENTS_SNIPPET, encoding="utf-8")
    return {"agents_md": f"created {path}"}

