@contextmanager
def provider_deadline(seconds):
    supported = hasattr(signal, "setitimer") and threading.current_thread() is threading.main_thread()
    if not supported or seconds <= 0:
        yield
        return
    previous_handler = signal.getsignal(signal.SIGALRM)
    previous_timer = signal.getitimer(signal.ITIMER_REAL)
    # Do not steal an existing caller's alarm; its deadline already bounds us.
    if previous_timer[0] > 0:
        yield
        return

    def expire(signum, frame):
        raise _DeadlineExpired()

    signal.signal(signal.SIGALRM, expire)
    signal.setitimer(signal.ITIMER_REAL, seconds)
    try:
        yield
    except _DeadlineExpired:
        raise TimeoutError(f"Provider invocation exceeded total wall deadline {seconds:g}s") from None
    finally:
        signal.setitimer(signal.ITIMER_REAL, 0)
        signal.signal(signal.SIGALRM, previous_handler)

def _datasets(manifest: dict[str, Any]) -> dict[str, dict[str, Any]]:
    raw = manifest.get("datasets") or {}
    if isinstance(raw, dict):
        return {
            str(name): ({**value, "id": str(name)} if isinstance(value, dict) else {})
            for name, value in raw.items()
        }
    if isinstance(raw, list):
        return {
            str(item.get("id", "")): dict(item)
            for item in raw
            if isinstance(item, dict) and item.get("id")
        }
    return {}

def _resolve(root: Path, value: str) -> Path:
    path = Path(value)
    return path.resolve() if path.is_absolute() else (root / path).resolve()

def _resolved_dataset(root: Path, dataset: dict[str, Any]) -> dict[str, Any]:
    dataset_id = str(dataset["id"])
    value = str(dataset.get("path", "")).strip()
    if not value:
        raise ValueError(f"dataset {dataset_id} is missing path")
    path = _resolve(root, value)
    if not path.is_file():
        raise FileNotFoundError(f"dataset {dataset_id} does not exist: {path}")
    companions: list[dict[str, Any]] = []
    for item in dataset.get("companions") or []:
        companion = _resolve(root, str(item))
        if not companion.is_file():
            raise FileNotFoundError(
                f"dataset {dataset_id} companion does not exist: {companion}"
            )
        companions.append({
            "path": str(companion),
            "sha256": sha256_file(companion),
            "bytes": companion.stat().st_size,
        })
    return {
        **dataset,
        "id": dataset_id,
        "path": str(path),
        "uri": path.as_uri(),
        "sha256": sha256_file(path),
        "bytes": path.stat().st_size,
        "companions": companions,
    }

def _resolved_oracle(root: Path, value: str) -> dict[str, Any] | None:
    if not value:
        return None
    path = _resolve(root, value)
    if not path.exists():
        raise FileNotFoundError(f"puzzle oracle does not exist: {path}")
    if path.is_dir():
        raise ValueError(f"puzzle oracle must be one normalized file, not a directory: {path}")
    return {
        "path": str(path),
        "sha256": sha256_file(path),
        "bytes": path.stat().st_size,
    }

def normalize_apis(case: dict[str, Any]) -> list[dict[str, str]]:
    raw = case.get("candidate_apis") or case.get("apis") or []
    result: list[dict[str, str]] = []
    for item in raw:
        if isinstance(item, str):
            result.append({"name": item, "stage": ""})
        elif isinstance(item, dict):
            result.append({
                "name": str(item.get("name", "")).strip(),
                "stage": str(item.get("stage", "")).strip(),
                "receiver": str(item.get("receiver", "")).strip(),
            })
    return result

def sha256_file(path: Path) -> str:
    digest = hashlib.sha256()
    with path.open("rb") as stream:
        for block in iter(lambda: stream.read(1024 * 1024), b""):
            digest.update(block)
    return digest.hexdigest()

def validate_bank(
    bank: dict[str, Any],
    sample_manifest: dict[str, Any],
    *,
    documented_apis: set[str] | None = None,
) -> list[str]:
    """Validate portable structure and cross-links without invoking an LLM."""
    errors: list[str] = []
    cases = bank.get("cases") or bank.get("puzzles") or []
    datasets = _datasets(sample_manifest)
    if not isinstance(cases, list) or not cases:
        return ["test bank has no cases"]
    seen: set[str] = set()
    for case in cases:
        if not isinstance(case, dict):
            errors.append("test bank contains a non-mapping case")
            continue
        case_id = str(case.get("id", "")).strip()
        if not case_id:
            errors.append("case is missing id")
            continue
        if case_id in seen:
            errors.append(f"duplicate case id: {case_id}")
        seen.add(case_id)
        if not str(case.get("goal") or case.get("user_prompt") or "").strip():
            errors.append(f"{case_id}: goal or user_prompt is required")
        modes = set(case.get("modes") or ["composition"])
        unknown_modes = modes - VALID_MODES
        if unknown_modes:
            errors.append(f"{case_id}: invalid modes: {sorted(unknown_modes)}")
        apis = normalize_apis(case)
        if not apis:
            errors.append(f"{case_id}: no APIs configured")
        for api in apis:
            name = api["name"]
            if not name:
                errors.append(f"{case_id}: API is missing name")
            elif documented_apis is not None and name not in documented_apis:
                errors.append(f"{case_id}: API is not documented: {name}")
            stage = api.get("stage", "")
            if stage and stage not in VALID_STAGES:
                errors.append(f"{case_id}: invalid stage for {name}: {stage}")
        for dataset_id in case.get("datasets") or []:
            if dataset_id not in datasets:
                errors.append(f"{case_id}: unknown dataset: {dataset_id}")
        output = case.get("output") or case.get("output_contract") or {}
        if output and not str(output.get("file", "")).strip():
            errors.append(f"{case_id}: output contract requires file")
    return errors

def verify_plan_inputs(plan: dict[str, Any]) -> list[str]:
    """Detect fixture drift before an expensive LLM/Spark run."""
    errors: list[str] = []
    for case in plan.get("cases") or []:
        for dataset in case.get("datasets") or []:
            path = Path(str(dataset.get("path", "")))
            if not path.is_file():
                errors.append(f"{case.get('id')}: missing dataset {path}")
                continue
            expected = str(dataset.get("sha256", ""))
            if expected and sha256_file(path) != expected:
                errors.append(f"{case.get('id')}: dataset hash changed: {path}")
            for companion in dataset.get("companions") or []:
                cpath = Path(str(companion.get("path", "")))
                if not cpath.is_file():
                    errors.append(f"{case.get('id')}: missing companion {cpath}")
                elif companion.get("sha256") and sha256_file(cpath) != companion["sha256"]:
                    errors.append(f"{case.get('id')}: companion hash changed: {cpath}")
        oracle = case.get("oracle")
        if isinstance(oracle, dict) and oracle.get("path"):
            opath = Path(str(oracle["path"]))
            if not opath.is_file():
                errors.append(f"{case.get('id')}: missing oracle {opath}")
            elif oracle.get("sha256") and sha256_file(opath) != oracle["sha256"]:
                errors.append(f"{case.get('id')}: oracle hash changed: {opath}")
    return errors

def _receiver_line(cls: str, kind: str) -> str:
    return (f"static object — call `{cls}.<method>(...)`" if kind == "static"
            else f"instance — obtain a `{cls}` value, then `<value>.<method>(...)`")

def _exec_status_map(cfg: AidealConfig) -> dict:
    """function -> MOST RECENT execution outcome (pass/fail) from error_log.jsonl.

    error_log.jsonl is append-only, so file order IS chronological. Scan in that
    order and ALWAYS overwrite, so a later failure correctly downgrades an earlier
    pass.

    Fixes the sticky-pass bug: the old `setdefault` branch meant that once a
    function was marked pass, no subsequent fail could downgrade it — e.g.
    `zonalStatsLocal` stayed badged "verified" in readme_index.md while failing
    every recent run. `fixed` (a retry that produced working code) counts as pass;
    any other status does not overwrite a real pass/fail outcome."""
    from .error_log import ErrorLog
    st: dict[str, str] = {}
    for e in ErrorLog(cfg.error_log).entries():
        fn = e.get("function", "")
        if not fn:
            continue
        s = e.get("status", "")
        if s in ("pass", "fixed"):
            st[fn] = "pass"
        elif s == "fail":
            st[fn] = "fail"
    return st

def _grounding_tiers(cfg: AidealConfig):
    """Per readme entry, most to least trustworthy:
      verified (doc-derived code compiled AND ran) > grounded (direct test) >
      sibling (a tested method on the same class shows the pattern) > guessed.
    Returns (tiers{name->tier}, class_of{name->class}, test_index)."""
    import os as _os
    details = {d["name"]: d for d in public_api_details(cfg)}
    class_of = {n: (_os.path.basename(details[n].get("file", ""))[:-6]
                    if details[n].get("file", "").endswith(".scala") else "")
                for n in details}
    names = [e.name for e in parse_readme(cfg.llm_readme)]
    test_index = api_test_examples(cfg)
    exec_status = _exec_status_map(cfg)
    tested_classes = {class_of.get(n) for n, ex in test_index.items() if ex and class_of.get(n)}
    tiers = {}
    for n in names:
        if exec_status.get(n) == "pass":              # proven end-to-end in this harness
            tiers[n] = "verified"
        elif test_index.get(n):
            tiers[n] = "grounded"
        elif class_of.get(n) and class_of.get(n) in tested_classes:
            tiers[n] = "sibling"
        else:
            tiers[n] = "guessed"
    return tiers, class_of, test_index

def grounding_report(cfg: AidealConfig, annotate: bool = False) -> dict:
    """Which readme entries are TRUSTWORTHY vs SIBLING-backed vs GUESSED."""
    tiers, class_of, test_index = _grounding_tiers(cfg)
    if not tiers:
        return {"error": "no LLM_readme entries — run `aideal readme --generate`"}
    exec_status = _exec_status_map(cfg)
    counts = {"verified": 0, "grounded": 0, "sibling": 0, "guessed": 0}
    for t in tiers.values():
        counts[t] += 1
    total = len(tiers)
    guessed_fail = sorted(n for n, t in tiers.items() if t == "guessed" and exec_status.get(n) == "fail")
    out = {
        "total": total,
        "verified": counts["verified"], "grounded": counts["grounded"],
        "sibling_grounded": counts["sibling"], "guessed": counts["guessed"],
        "trusted_pct": round(100 * (counts["verified"] + counts["grounded"]) / total, 1),
        "guessed_that_failed_execution": guessed_fail[:40],
        "note": "verified = doc-derived code compiled AND ran (strongest); grounded = direct test; "
                "sibling = tested method on same class; guessed = signature-only (verify by execution).",
    }
    if annotate:
        badge = {"verified": "VERIFIED — doc-derived code compiled and ran via comprehension --execute.",
                 "grounded": "test-backed — usage mined from a real, passing test.",
                 "sibling": "sibling-grounded — a tested method on the same class shows the pattern.",
                 "guessed": "GUESSED — no test; generated from the signature only. Verify by execution."}
        text = cfg.llm_readme.read_text(encoding="utf-8")
        matches = list(API_HEADER_RE.finditer(text))
        parts = [text[:matches[0].start()]] if matches else [text]
        for i, m in enumerate(matches):
            end = matches[i + 1].start() if i + 1 < len(matches) else len(text)
            block = text[m.start():end]
            if "_Grounding:" not in block:
                marker = f"_Grounding: {badge.get(tiers.get(m.group(1), 'guessed'))}_"
                hdr, _, rest = block.partition("\n")
                block = f"{hdr}\n{marker}\n{rest}"
            parts.append(block)
        cfg.llm_readme.write_text("".join(parts), encoding="utf-8")
        out["annotated"] = True
    return out

def organize_report(cfg: AidealConfig, write_index: bool = False) -> dict:
    """Axis 1+2 curation: group intended APIs by defining class, rank each by
    robustness (grounded > sibling > guessed, tie-broken by execution outcome),
    and mark the most robust `primary` per group so the agent reaches for it.
    Optionally writes a categorized, robust-first `docs/readme_index.md`."""
    from collections import defaultdict
    tiers, class_of, _ = _grounding_tiers(cfg)
    if not tiers:
        return {"error": "no LLM_readme entries — run `aideal readme --generate`"}
    exec_status = _exec_status_map(cfg)
    cats = defaultdict(list)
    for n, t in tiers.items():
        cats[class_of.get(n) or "(unknown)"].append((n, t, exec_status.get(n, "")))
    result = {}
    for cls, items in cats.items():
        items.sort(key=lambda it: (_TIER_RANK[it[1]], _EXEC_RANK.get(it[2], 1), it[0]))
        result[cls] = {"primary": items[0][0], "count": len(items),
                       "apis": [{"name": n, "tier": t, "exec": ex or "not-run"} for n, t, ex in items]}
    counts = {"verified": 0, "grounded": 0, "sibling": 0, "guessed": 0}
    for t in tiers.values():
        counts[t] += 1
    summary = {"total": len(tiers), "categories": len(result), **counts}
    if write_index:
        L = [f"# {cfg.project_name} — organized API index", "",
             f"{counts['verified']} verified · {counts['grounded']} grounded · "
             f"{counts['sibling']} sibling · {counts['guessed']} guessed · {len(result)} categories", "",
             "Legend: ★ verified (compiled + ran) · ✅ grounded (direct test) · 🟡 sibling-grounded · "
             "⚠️ guessed (verify by execution). **primary** = most robust in its group.", ""]
        for cls in sorted(result):
            L.append(f"## {cls}")
            for a in result[cls]["apis"]:
                star = " **(primary)**" if a["name"] == result[cls]["primary"] else ""
                ex = f" · exec {a['exec']}" if a["exec"] != "not-run" else ""
                L.append(f"- {_TIER_BADGE[a['tier']]} `{a['name']}` — {a['tier']}{ex}{star}")
            L.append("")
        idx = cfg.llm_readme.parent / "readme_index.md"
        idx.write_text("\n".join(L), encoding="utf-8")
        summary["index"] = str(idx)
    return {"summary": summary,
            "categories_sample": {k: {"primary": v["primary"], "count": v["count"]}
                                  for k, v in sorted(result.items())[:12]}}

@dataclass
class ApiEntry:
    name: str
    goal: str
    snippet: str
    body: str

def _params_block(params: list[dict]) -> str:
    """Pre-fill a Parameters list from the structured signature (names/types/
    defaults are facts; meanings are TODO for the author model)."""
    if not params:
        return "_None._"
    out = []
    for p in params:
        t = f" (`{p['type']}`)" if p.get("type") else ""
        d = f", default `{p['default']}`" if p.get("default") else ""
        out.append(f"- `{p['name']}`{t}{d}: TODO — what this argument means / expected values.")
    return "\n".join(out)

def _replace_section(block: str, header: str, content: str) -> str:
    """Replace the content under `### {header}` (up to the next ### or block end).
    Appends the section if it isn't present."""
    pat = re.compile(rf"(###\s+{re.escape(header)}\s*
)(.*?)(?=
###\s|\Z)", re.DOTALL)
    if pat.search(block):
        return pat.sub(lambda m: m.group(1) + content.rstrip() + "
", block, count=1)
    return block.rstrip() + f"

### {header}
{content}
"

def _section_between(body: str, header: str) -> str:
    m = re.search(rf"^### {re.escape(header)}\s*$(.*?)(?=^###? |\Z)", body, re.MULTILINE | re.DOTALL)
    return m.group(1).strip() if m else ""

def _section_has_code(block: str, header: str) -> bool:
    """True if the `### {header}` section already holds a REAL fenced code example —
    a ``` block whose content isn't just the skeleton `TODO` placeholder. Drives
    augment's `only_missing` gap-fill: backfill ONLY entries lacking example/fix code,
    leaving curated or already-generated code untouched."""
    body = _section_between(block, header)
    if not body:
        return False
    for m in re.finditer(r"```[^\n]*\n(.*?)```", body, re.DOTALL):
        inner = m.group(1).strip()
        if inner and not inner.upper().startswith("TODO"):
            return True
    return False

def _original_readme_snippets(cfg: AidealConfig, names, max_per_api: int = 2,
                              max_chars: int = 1400) -> dict[str, list[str]]:
    """Index VERBATIM code blocks from the ORIGINAL readme by the API name(s) they
    call. `distilled_readme_context` summarizes the docs ONCE and drops per-API
    snippets, so an entry never sees the project's REAL call form — e.g. the docs'
    instance-style `raster.mapPixels(f)` gets paraphrased into a non-compiling
    free-function `mapPixels(raster, f)`. Feeding the exact block back lets the
    author reproduce the true receiver/qualifier. Returns {name: [code blocks]}."""
    if not cfg.original_readme_files:
        return {}
    from collections import defaultdict
    raw = cfg.original_readme_text(limit=200000)
    # tolerant fence match: any info-string after ``` and REQUIRE the closing ```
    # to start its own line (\n```), so inline `code` / stray backticks in prose
    # don't desync the open/close pairing across the concatenated docs.
    blocks = re.findall(r"```[^\n]*\n(.*?)\n```", raw, re.DOTALL)
    idx: dict[str, list[str]] = defaultdict(list)
    for b in blocks:
        b = b.strip()
        if not b:
            continue
        for name in names:
            if len(idx[name]) >= max_per_api:
                continue
            # a real call/use of the name: `name(`, `.name(`, `name[`
            if re.search(rf"(?:\b|\.){re.escape(name)}\s*[\(\[]", b):
                idx[name].append(b[:max_chars])
    return dict(idx)

def _generation_files_hash(paths: list[Path], root: Path) -> dict:
    digest = _hashlib.sha256()
    files = sorted(set(p.resolve() for p in paths if p.is_file()), key=str)
    for path in files:
        try:
            label = path.relative_to(root.resolve())
        except ValueError:
            label = path
        digest.update(str(label).encode("utf-8"))
        digest.update(b"\0")
        digest.update(path.read_bytes())
        digest.update(b"\0")
    return {"sha256": digest.hexdigest(), "file_count": len(files)}

class RepairJournal:
    def __init__(self, path, identity, initial):
        self.path = Path(path)
        if self.path.exists():
            self.state = json.loads(self.path.read_text())
            if self.state.get('identity') != identity or self.state.get('schema') != 4:
                raise ValueError('Document repair inputs changed; use a new namespace')
        else:
            self.state = {'schema': 4, 'identity': identity, 'initial': initial,
                          'rounds': [], 'context': {}, 'phases': {}}
            self.save()

    def save(self):
        atomic(self.path, self.state)

    def phase(self, number, name, action):
        key = f'{number}:{name}'
        row = self.state['phases'].get(key, {})
        if row.get('status') == 'complete':
            return row['result']
        if row.get('status') in ('started', 'uncertain'):
            raise UncertainPhase(f'{key} has an unacknowledged invocation; inspect before retrying')
        attempts = list(row.get('attempts', []))
        started = time.time()
        previous_end = attempts[-1].get('ended_epoch') if attempts else None
        attempts.append({'status': 'started', 'started_epoch': started,
                         'since_previous_end_s': started - previous_end if previous_end else None})
        row = {'status': 'started', 'attempts': attempts}
        self.state['phases'][key] = row
        self.save()
        try:
            value = action()
        except Exception as exc:
            row.update(status='uncertain' if isinstance(exc, CleanupError) else 'retryable_error',
                       error_type=type(exc).__name__, error=str(exc))
            attempts[-1].update(status='error', error_type=type(exc).__name__,
                                ended_epoch=time.time(), wall_s=time.time()-started)
            self.save()
            raise
        row.update(status='complete', result=value)
        attempts[-1].update(status='complete', ended_epoch=time.time(), wall_s=time.time()-started)
        self.save()
        return value

    def checkpoint(self, rounds, context):
        self.state['rounds'], self.state['context'] = list(rounds), dict(context)
        self.save()

def __init__(self, path, identity, initial):
    self.path = Path(path)
    if self.path.exists():
        self.state = json.loads(self.path.read_text())
        if self.state.get('identity') != identity or self.state.get('schema') != 4:
            raise ValueError('Document repair inputs changed; use a new namespace')
    else:
        self.state = {'schema': 4, 'identity': identity, 'initial': initial,
                      'rounds': [], 'context': {}, 'phases': {}}
        self.save()

def checkpoint(self, rounds, context):
    self.state['rounds'], self.state['context'] = list(rounds), dict(context)
    self.save()

def identity(cfg, policy):
    context = prompt_contract(cfg)
    for name in ('deep_dive', 'docfix_diagnose', 'docfix_rewrite'):
        path = prompts_dir(cfg) / f'aideal/{name}.md'
        if not path.exists():
            path = DEFAULT_PROMPTS / f'aideal/{name}.md'
        context['templates'][name] = digest(path.read_bytes())
    source = {}
    for pattern in [*cfg.source_globs, *cfg.test_globs]:
        for value in glob.glob(str(cfg.root / pattern), recursive=True):
            path = Path(value)
            if path.is_file():
                source[str(path.relative_to(cfg.root))] = digest(path.read_bytes())
    baseline = policy.get('target_source')
    return digest({'schema': 4, 'policy': policy, 'configuration': cfg.raw,
                   'context': context, 'transport': transport_contract(), 'source': source,
                   'baseline': digest(Path(baseline).read_bytes()) if baseline and Path(baseline).is_file() else None,
                   'engine': {name: digest(Path(__file__).with_name(name).read_bytes()) for name in
                              ('docfix.py', 'doc_repair.py', 'repair_journal.py', 'deepdive.py')}})

def _available_packages(cfg: AidealConfig) -> set[str]:
    """Packages actually present in the jars the scaffold compiles against
    (comprehension.execute.jars + uberjar). Used to drop wildcard imports for
    packages not on the classpath (e.g. internal `jhdf`) that break compilation."""
    import zipfile
    ex = (cfg.comprehension or {}).get("execute", {}) if cfg.comprehension else {}
    jar_globs = []
    if ex.get("jars"):
        jar_globs.append(str(ex["jars"]))
    if ex.get("uberjar"):
        bc = cfg.root / ex.get("build_cwd", ".")
        jar_globs.append(str(bc / ex["uberjar"]))
    jars = []
    for jg in jar_globs:
        jars += globmod.glob(jg if jg.startswith("/") else str(cfg.root / jg))
    # also the Spark jars (on the compile classpath) so org.apache.spark.* survives
    try:
        import os as _os
        import pyspark as _pyspark
        jars += globmod.glob(_os.path.join(_os.path.dirname(_pyspark.__file__), "jars", "*.jar"))
    except Exception:
        pass
    pkgs: set[str] = set()
    for jar in jars:
        try:
            for n in zipfile.ZipFile(jar).namelist():
                if n.endswith(".class") and "/" in n:
                    pkgs.add(n.rsplit("/", 1)[0].replace("/", "."))
        except Exception:
            continue
    return pkgs

def _imports_from_tests(cfg: AidealConfig) -> list[str]:
    """Robust import block: the SPECIFIC imports the test suite already uses to
    exercise the APIs — real, compiling, and made COLLISION-FREE. Braced imports
    are expanded to one-per-name; any simple name that resolves to two different
    paths (e.g. two `ByteArrayOutputStream`s) is DROPPED, since including both
    would make scalac ambiguous. Test-framework imports are filtered out."""
    from collections import defaultdict
    imp_re = re.compile(r"^\s*import\s+(\S.*?)\s*$", re.MULTILINE)
    raw: set[str] = set()
    for g in cfg.test_globs:
        for p in globmod.glob(str(cfg.root / g), recursive=True):
            txt = Path(p).read_text(encoding="utf-8", errors="ignore")
            for m in imp_re.finditer(txt):
                t = m.group(1).strip()
                if t and not _TEST_FRAMEWORK_IMPORT.search(t):
                    raw.add(t)
    wildcards: list[str] = []
    by_name: dict[str, set[str]] = defaultdict(set)   # simple name -> {full import}
    for t in raw:
        if t.endswith("._"):                          # package/object wildcard
            wildcards.append(f"import {t}")
        elif "{" in t and t.endswith("}"):            # expand braces to one-per-name
            pkg = t[:t.index("{")]
            for nm in t[t.index("{") + 1:t.rindex("}")].split(","):
                nm = nm.strip()
                if not nm:
                    continue
                simple = nm.split("=>")[-1].strip()   # renamed import: keep the alias
                by_name[simple].add(f"import {pkg}{nm}")
        else:
            by_name[t.rsplit('.', 1)[-1]].add(f"import {t}")
    out = list(dict.fromkeys(wildcards))
    for simple, imps in by_name.items():
        if len(imps) == 1:                            # unambiguous -> keep
            out.append(next(iter(imps)))
        # else: same simple name from >1 path -> drop (would be ambiguous)
    # drop imports whose package isn't on the compile classpath (a test-only dep
    # would fail scalac). Skipped when jars aren't configured/resolvable.
    avail = _available_packages(cfg)
    if avail:
        out = [i for i in out if _on_classpath(i, avail)]
    return sorted(set(out))

def _wildcard_of(target: str) -> str:
    s = target.strip()
    if s.endswith("._"):
        return s[:-2]
    if s.endswith("}"):
        return s[:s.rfind(".{")]
    return s.rsplit(".", 1)[0]            # drop the single class/member

def generate_tasks(cfg: AidealConfig, n: int = 5) -> dict:
    require_profile(cfg)
    inventory = parse_readme(cfg.llm_readme)
    api_list = "\n".join(f"- `{e.name}`: {e.goal}" for e in inventory)

    raw = invoke_text(
        cfg.model_for_role("author"),
        *load_prompt(cfg, "aideal/tasks_generate", api_list=api_list, n=n),
    )
    m = re.search(r"tasks:.*", raw, re.DOTALL)
    if not m:
        return {"generated": 0, "error": "author model returned no tasks YAML", "raw_tail": raw[-300:]}
    parsed = yaml.safe_load(m.group(0)) or {}
    new_tasks = parsed.get("tasks", [])

    valid_names = {re.sub(r"\[.*\]$", "", e.name) for e in inventory}
    accepted, rejected = [], []
    existing_ids = {t.get("id") for t in load_tasks(cfg)}
    for t in new_tasks:
        apis = [re.sub(r"\[.*\]$", "", a) for a in t.get("apis", [])]
        if not t.get("id") or t["id"] in existing_ids:
            rejected.append({"task": t, "reason": "missing or duplicate id"})
        elif not apis or any(a not in valid_names for a in apis):
            rejected.append({"task": t, "reason": "uses APIs not in LLM_readme"})
        else:
            t["source"] = "generated"
            t.setdefault("language", cfg.language)
            accepted.append(t)
            existing_ids.add(t["id"])

    if accepted:
        data = {"tasks": load_tasks(cfg) + accepted}
        cfg.integration_tasks.write_text(
            "# Benchmark tasks. source: human = curated; generated = author-model from profile.\n"
            + yaml.safe_dump(data, sort_keys=False, allow_unicode=True),
            encoding="utf-8",
        )
    return {
        "generated": len(accepted),
        "rejected": rejected,
        "ids": [t["id"] for t in accepted],
        "tasks_file": str(cfg.integration_tasks),
    }

def _native_counts(path):
    """Count archived native passes; do not reinterpret them as semantic checks."""
    data = load(path)
    metrics = data["metrics"]
    rounds = Counter(str(row.get("pass_round")) for row in metrics.values() if row.get("status") == "pass")
    return {"selected": len(metrics), "native_passes": sum(rounds.values()),
            "initial_native_passes": rounds.get("0", 0), "first_pass_rounds": dict(sorted(rounds.items())),
            "source_sha256": file_hash(path), "independent_semantic_validation": False}

def reproduce(root):
    """Recount archived outcomes, without generating or executing new solutions."""
    root = Path(root)
    native_root = root / "evidence/historical/native"
    cells = {p.name: _native_counts(p) for p in sorted(native_root.glob("*.json"))}
    old = load(root / "evidence/historical/RESULTS.json")
    sedona = {}
    for variant in ("default", "setup_variant_v2", "configured"):
        path = root / "studies/sedonadb/evidence" / (variant + "_results.jsonl")
        rows = [json.loads(line) for line in path.read_text().splitlines()]
        if len({row['case_id'] for row in rows}) != len(rows):
            raise ValueError('Duplicate archived case IDs: ' + variant)
        sedona[variant] = {"example_blocks": len(rows),
                           "statuses": dict(sorted(Counter(row['status'] for row in rows).items())),
                           "semantic_correctness_verified": False, "llm_calls": 0,
                           "journal_sha256": file_hash(path)}
    return {"kind": "recomputed_archived_evidence_not_new_ablation_results",
            "native_cells": cells,
            "sedonadb_rust_documentation_sweeps": sedona,
            "historical_external_summary": old["historical_verified"],
            "rdpro_v5": old["RDPro_v5"],
            "new_five_arm_results": None,
            "notes": ["Recomputes native cells from archived per-API result rows.",
                      "External summary uses the separately hash-verified historical results memo.",
                      "Same output across Git branches demonstrates report reproducibility, not equal treatment performance.",
                      "Fresh LLM samples are not guaranteed to reproduce exact historical counts."]}

def relocated_catalog(root, destination):
    root, destination = Path(root).resolve(), Path(destination).resolve()
    catalog = load(root / 'studies/sedonadb/evidence/sql_reference_local_paths.json')
    for entry in catalog:
        examples = {}
        for binding in entry.get('fixture_bindings', []):
            fixture = root / 'studies/sedonadb/evidence' / Path(binding['local_fixture']['path']).name
            if file_hash(fixture) != binding['local_fixture']['sha256']:
                raise ValueError('Pinned fixture changed: ' + str(fixture))
            # Quotes in directory names must remain a single SQL string literal.
            quoted = str(fixture).replace("'", "''")
            index = binding['example_index'] - 1
            # Several fixtures can belong to one SQL block. Start from the
            # original SQL once, then retain every replacement in that block.
            sql = examples.get(index, binding['original_sql'])
            examples[index] = sql.replace(binding['original_locator'], quoted)
            binding['local_fixture'] = bind(fixture)
        for index, sql in examples.items():
            entry['examples'][index] = sql
    if destination.exists():
        if load(destination) != catalog:
            raise ValueError('Existing relocated catalog differs; use a new output directory')
    else:
        save(destination, catalog)
    return destination

def _execute(binary, attempt, timeout, environment):
    """Run one Rust process and retain complete stdout/stderr on every outcome."""
    proc = subprocess.Popen(
        [str(binary), str(attempt / "input.json")], cwd=attempt,
        stdout=subprocess.PIPE, stderr=subprocess.PIPE,
        env={**os.environ, **environment}, text=True, start_new_session=True,
    )
    timed_out = False
    try:
        stdout, stderr = proc.communicate(timeout=timeout)
    except subprocess.TimeoutExpired:
        try:
            os.killpg(proc.pid, signal.SIGKILL)
        except ProcessLookupError:
            pass  # The process exited between the deadline and the kill.
        stdout, stderr = proc.communicate()
        timed_out = True
    (attempt / "stdout.txt").write_text(stdout)
    (attempt / "stderr.txt").write_text(stderr)
    row = {"returncode": proc.returncode, "stdout": bind(attempt / "stdout.txt"),
           "stderr": bind(attempt / "stderr.txt")}
    if timed_out:
        row.update(status="outer_timeout", error="Complete Rust process group killed at outer deadline")
    elif proc.returncode:
        row.update(status="runner_error", error=stderr)
    else:
        try:
            payload = json.loads(stdout)
            result = payload.get("result") if isinstance(payload, dict) else None
            if not isinstance(result, dict) or result.get("status") not in ("executed", "error", "timeout"):
                raise ValueError("Expected result object with executed, error or timeout status")
            row.update(status=result["status"], rust_result=result)
        except ValueError as exc:
            row.update(status="invalid_runner_output", error=str(exc))
    return row

def _resume_records(journal, fingerprint, expected_cases):
    """Reject incompatible or damaged evidence before skipping any execution."""
    if not journal.exists():
        return {}
    done = {}
    for line_number, line in enumerate(journal.read_text().splitlines(), 1):
        if not line.strip():
            continue
        try:
            row = json.loads(line)
        except json.JSONDecodeError as exc:
            raise ValueError(f"Invalid journal JSON at line {line_number}; retain it for recovery") from exc
        if not isinstance(row, dict):
            raise ValueError(f"Invalid journal record at line {line_number}")
        case_id = row.get("case_id")
        if not isinstance(case_id, str) or case_id not in expected_cases:
            raise ValueError(f"Unknown journal case at line {line_number}: {case_id}")
        if case_id in done:
            raise ValueError(f"Duplicate journal case: {case_id}")
        if row.get("fingerprint") != fingerprint:
            raise ValueError(f"Incompatible journal fingerprint: {case_id}")
        if (row.get("api"), row.get("example_index")) != expected_cases[case_id]:
            raise ValueError(f"Journal case metadata differs from catalog: {case_id}")
        if row.get("status") not in (
            "external_fixture_pending", "statement_review_required", "outer_timeout",
            "runner_error", "invalid_runner_output", "executed", "error", "timeout",
        ):
            raise ValueError(f"Unknown journal status: {case_id}")
        done[case_id] = row
    return done

def automatic_hint(stderr):
    """Conservative triage, not a source-verified diagnosis or fix."""
    rules = [
        (r"ambiguous|overloaded method", "ambiguous-overload",
         "Inspect the available overloads. Supply a value or explicit type matching the documented constructor; avoid an untyped null."),
        (r"cannot find symbol|not a member|has no attribute|no method named", "name-or-receiver",
         "Check the method spelling, declaring class, and static type of the receiver against the supplied documentation. A missing name can also indicate a dependency/version mismatch."),
        (r"type mismatch|mismatched types|incompatible types|ClassCastException", "type-contract",
         "Compare required and actual argument/receiver types. Verify input data types before selecting a generic type parameter; a cast is not a data conversion."),
        (r"NoClassDefFoundError|ClassNotFoundException|ModuleNotFoundError", "import-or-dependency",
         "Check both the requested import and the installed version/classpath. A generated invalid import and a missing dependency require different fixes; do not remove the API from the denominator."),
        (r"FileNotFound|No such file|Input path does not exist", "file-input",
         "Check the supplied fixture path, file-versus-directory contract, and required sidecars. Create output directories only within the assigned workspace."),
        (r"AssertionError|assertion failed", "assertion-or-behavior",
         "Compare the observed value with the independent oracle and documented contract. Do not weaken or remove the assertion merely to obtain a pass."),
        (r"504|DEADLINE_EXCEEDED|ReadTimeout", "provider-or-service-timeout",
         "Inspect which process timed out. If this is provider transport, record it separately and retry within the provider budget; it is not evidence that the target API failed."),
    ]
    for pattern, category, hint in rules:
        if re.search(pattern, stderr, re.I):
            return {"category": category, "text": hint, "status": "unverified", "method": "deterministic pattern rule"}
    return {"category": "unknown", "text": "Inspect the complete diagnostic and the exact previous test before proposing a change.",
            "status": "unverified", "method": "fallback"}

def bank_errors(bank, api_names):
    errors, ids, micro = [], set(), set()
    expected_apis = set(api_names)
    cases = bank.get("cases", [])
    if not cases:
        return ["Bank is empty"]
    for c in cases:
        cid = c.get("id")
        if not isinstance(cid, str) or not re.fullmatch(r"[A-Za-z0-9_.-]+", cid):
            errors.append(f"Unsafe/missing case ID: {cid}")
        if cid in ids:
            errors.append(f"Duplicate case: {cid}")
        ids.add(cid)
        if c.get("split") != "held_out":
            errors.append(f"{cid}: evaluation case must be held_out")
        if c.get("kind") not in {"micro", "puzzle"}:
            errors.append(f"{cid}: invalid case kind")
        targets = c.get("target_apis", [])
        if not targets or set(targets) - expected_apis:
            errors.append(f"{cid}: missing or unknown original target APIs")
        if c.get("kind") == "micro":
            if len(targets) != 1:
                errors.append(f"{cid}: micro case must have exactly one target")
            micro.update(targets)
        if not c.get("prompt"):
            errors.append(f"{cid}: task prompt missing")
        oracle = c.get("oracle") or {}
        if oracle.get("status") != "validated" or not oracle.get("reference") or not oracle.get("validation"):
            errors.append(f"{cid}: independently validated oracle missing")
        else:
            for ref in (oracle["reference"], oracle["validation"]):
                if not verify_artifact(ref):
                    errors.append(f"{cid}: oracle artifact changed/missing")
        for ref in c.get("fixtures", []):
            if not verify_artifact(ref):
                errors.append(f"{cid}: fixture changed/missing")
    if micro != expected_apis:
        errors.append("Micro bank does not cover exactly the original API manifest")
    if not any(c.get("kind") == "puzzle" for c in cases):
        errors.append("No puzzle cases")
    return errors

def bind(path):
    path = Path(path).resolve()
    if not path.is_file():
        raise ValueError(f"Missing artifact: {path}")
    return {"path": str(path), "sha256": file_hash(path), "bytes": path.stat().st_size}

def digest(value):
    return hashlib.sha256(json.dumps(value, sort_keys=True, separators=(",", ":"),
                                     allow_nan=False).encode()).hexdigest()

def file_hash(path):
    h = hashlib.sha256()
    with Path(path).open("rb") as f:
        for chunk in iter(lambda: f.read(1024 * 1024), b""):
            h.update(chunk)
    return h.hexdigest()

def freeze(plan, bank, output, proposal=None, decision=None):
    errors = preflight(plan, bank, proposal, decision)
    if errors:
        raise ValueError("Preflight failed:\n" + "\n".join(errors))
    payload = {"plan": plan, "bank": bank, "proposal": proposal, "decision": decision}
    frozen = {"study_sha256": digest(payload), **payload}
    # Never overwrite a frozen study, including an identical one.
    with Path(output).open("x") as f:
        json.dump(frozen, f, indent=2, allow_nan=False)
    return frozen

def load(path):
    """Read a UTF-8 JSON artifact."""
    return json.loads(Path(path).read_text(encoding="utf-8"))

def preflight(plan, bank, proposal=None, decision=None):
    errors = bank_errors(bank, plan["api_names"])
    if len(set(plan["api_names"])) != len(plan["api_names"]):
        errors.append("Duplicate API names")
    if set(plan["arms"]) != set(ARMS):
        errors.append("The five-arm matrix changed")
    for name, flags in ARMS.items():
        a = plan["arms"].get(name, {})
        if tuple(a.get(x) for x in ("readme", "aliases", "error_hints")) != flags:
            errors.append(f"{name}: treatment factors changed")
    for ref in plan.get("shared_artifacts", []):
        if not verify_artifact(ref):
            errors.append(f"Shared artifact changed/missing: {ref['path']}")
    if not plan.get("shared_artifacts"):
        errors.append("No shared source/runtime/prompt/fixture identity")
    common = plan.get("common", {})
    for key in ("model", "temperature", "max_output_tokens", "max_snippet_fixes",
                "provider_attempt_limit", "execution_timeout_s", "trial_ids", "prompt_sha256"):
        if common.get(key) is None:
            errors.append(f"Shared setting missing: {key}")
    development = set(plan.get("development_case_ids", []))
    if development & {c["id"] for c in bank["cases"]}:
        errors.append("Development and held-out case IDs overlap")
    for key in ("original_readme", "improved_readme", "alias_interface", "error_hints"):
        ref = plan.get("treatments", {}).get(key)
        if not ref or not verify_artifact(ref):
            errors.append(f"Treatment artifact missing/changed: {key}")
    if not approval_valid(proposal or {}, decision):
        errors.append("Alias patch requires an actual human decision bound to the reviewed artifacts")
    if not plan.get("adapter_validation") or not verify_artifact(plan["adapter_validation"]):
        errors.append("Measured runner/prompt exposure adapter has not been validated")
    return errors

def score(bank, trial_ids, rows, *, study_sha256, max_snippet_fixes=5,
          arms=None, baseline="original"):
    """One latest adjudicated row per case/trial/arm, not raw attempt history.

    Provider-pending, incomplete/refused/empty generations, not-run, and missing-oracle
    results remain unresolved, retaining the selected denominator.
    Do not accept an exit marker as semantic correctness.
    """
    arms = tuple(ARMS if arms is None else arms)
    if not arms or len(set(arms)) != len(arms) or baseline not in arms:
        raise ValueError("Invalid condition matrix/baseline")
    case_by_id = {c["id"]: c for c in bank["cases"]}
    if len(case_by_id) != len(bank["cases"]) or not trial_ids or len(set(trial_ids)) != len(trial_ids):
        raise ValueError("Duplicate cases/trials or empty trial list")
    by_key = {}
    for r in rows:
        key = (r["arm"], r["case_id"], r["trial_id"])
        if r["study_sha256"] != study_sha256 or r["arm"] not in arms:
            raise ValueError("Unmatched study/arm")
        if r["case_id"] not in case_by_id or r["trial_id"] not in trial_ids or key in by_key:
            raise ValueError("Unknown/duplicate case or trial")
        if r["status"] not in {"pass", "fail", "provider_pending", "not_run", "unverified",
                                "generation_incomplete", "generation_refusal", "generation_empty",
                                "generation_provider_failure"}:
            raise ValueError("Unknown result status")
        if r.get("first_attempt_pass") is True and r["status"] != "pass":
            raise ValueError("An initial semantic pass must be a verified pass outcome")
        if r["status"] == "pass":
            if not (r.get("execution_pass") is True and r.get("oracle_pass") is True
                    and r.get("target_reached") is True):
                raise ValueError("A pass needs execution, target reachability, and independent oracle")
            if not isinstance(r.get("first_pass_round"), int) or isinstance(r["first_pass_round"], bool) or not 0 <= r["first_pass_round"] <= max_snippet_fixes:
                raise ValueError("Pass is outside the common repair budget")
        if r["status"] == "pass" and r.get("first_attempt_pass") is not (r["first_pass_round"] == 0):
            raise ValueError("Inconsistent first-attempt and recovery outcome")
        by_key[key] = r
    reports = {}
    for arm in arms:
        reports[arm] = {}
        for kind in ("micro", "puzzle"):
            keys = [(arm, cid, tid) for cid, c in case_by_id.items() if c["kind"] == kind for tid in trial_ids]
            selected = [by_key.get(k, {"status": "not_run"}) for k in keys]
            counts = Counter(r["status"] for r in selected)
            n = len(keys)
            terminal = counts["pass"] + counts["fail"]
            initial = sum(r.get("first_attempt_pass") is True for r in selected)
            value = {"selected": n, "completed": terminal, "unresolved": n - terminal,
                     "first_attempt_correct": initial, "correct_within_budget": counts["pass"],
                     "status_counts": dict(counts),
                     "first_attempt_lower_bound_pct": 100 * initial / n if n else None,
                     "within_budget_lower_bound_pct": 100 * counts["pass"] / n if n else None,
                     "final_within_budget_pct": 100 * counts["pass"] / n if n and terminal == n else None}
            baseline_rows = [by_key.get((baseline, k[1], k[2]), {}) for k in keys]
            paired = [(a, b) for a, b in zip(selected, baseline_rows)
                      if a["status"] in {"pass", "fail"} and b.get("status") in {"pass", "fail"}]
            value["paired_completed"] = len(paired)
            value["recoveries_vs_original"] = sum(a["status"] == "pass" and b["status"] == "fail" for a, b in paired)
            value["regressions_vs_original"] = sum(a["status"] == "fail" and b["status"] == "pass" for a, b in paired)
            reports[arm][kind] = value
    return reports

def treatment_inputs(plan, arm):
    """Explicit prompt/artifact routing; a future runner must use this route."""
    readme, aliases, hints = ARMS[arm]
    t = plan["treatments"]
    return {"readme": t["improved_readme" if readme else "original_readme"],
            "alias_interface": t["alias_interface"] if aliases else None,
            "error_hints": t["error_hints"] if hints else None,
            "compile_approved_alias_module": aliases,
            "save_full_logs": True}

def _candidate_body(code):
    if code.strip().startswith('```'):
        match = re.fullmatch(r'\s*```[^\n]*\n(.*?)\n```\s*', code, re.S)
        if match:
            return match[1]
    return code

def _model_request(frozen, prompt, number=0):
    common = frozen['config']['common']
    return {'system': frozen['system_prompt'], 'prompt': prompt, 'model': frozen['config']['model']['name'],
            'temperature': common['temperature'], 'max_output_tokens': output_limit(common, number)}

def _verify_saved_row(frozen, row, directory):
    """Rebuild every saved outcome, including unresolved generation stops."""
    if row.get('round_evidence') != _round_evidence(directory):
        raise ValueError('Saved condition attempt evidence changed')
    if row.get('resources') != _collect_resources(directory):
        raise ValueError('Saved condition resource totals differ from attempt evidence')
    evidence = row['round_evidence']
    if not evidence or [r['round'] for r in evidence] != list(range(len(evidence))):
        raise ValueError('Saved condition evidence has missing or unexpected rounds')
    common = frozen['config']['common']
    if len(evidence) > common['max_snippet_fixes'] + 1:
        raise ValueError('Saved result exceeds the common repair budget')
    if row.get('context_exposures') != [item['exposure'] for item in evidence]:
        raise ValueError('Saved public-context exposure changed')
    case = next(c for c in frozen['bank']['cases'] if c['id'] == row['case_id'])
    backend = frozen['backends'][row['arm']]['sha256']
    previous = None
    expected = {'status': 'not_run', 'first_attempt_pass': False}
    for item in evidence:
        number = item['round']
        prompt, exposure = public_context(frozen, row['arm'], case, previous)
        if load(item['exposure']['path']) != exposure:
            raise ValueError('Saved public-context exposure differs from the frozen prompt')
        selected = selected_response(item['providers'], _model_request(frozen, prompt, number))
        if selected is None:
            if item['executions'] or item.get('generation'):
                raise ValueError('Execution/generation evidence lacks a provider response')
            expected['status'] = 'provider_pending'
        else:
            response, files = selected
            executable = mark_generation(expected, response, number)
            if not executable:
                if item['executions']:
                    raise ValueError('Nonexecutable generation has execution evidence')
                verify_generation(item, response, files)
            else:
                code = _candidate_body(response['code'])
                checker = checker_request(frozen, row['arm'], case, code)
                checked = None
                for attempt in item['executions']:
                    records = attempt['files']
                    if 'request.json' in records and load(records['request.json']['path']) != checker:
                        raise ValueError('Saved checker candidate differs from the provider response')
                    if 'process.json' in records:
                        if 'request.json' not in records:
                            raise ValueError('Saved checker process lacks its request')
                        process = load(records['process.json']['path'])
                        outcome = checked_outcome(process, backend)
                        if checked is not None:
                            raise ValueError('Saved execution follows an already checked outcome')
                        if outcome is not None:
                            checked = (outcome, process, records)
                verify_generation(item, response, files)
                if checked is None:
                    expected['status'] = 'unverified'
                else:
                    outcome, process, records = checked
                    expected.update({k: process['payload'][k] for k in ('execution_pass', 'oracle_pass', 'target_reached')})
                    expected.update(status='pass' if outcome else 'fail', last_checked_round=number,
                                    code_sha256=digest(code), adjudication={k: records[v] for k, v in
                                                                         [('process', 'process.json'), ('request', 'request.json')]})
                    if outcome:
                        expected.update(first_attempt_pass=number == 0, first_pass_round=number)
                    previous = previous_result(code, process['payload'])
        if number < len(evidence) - 1 and expected['status'] != 'fail':
            raise ValueError('Saved repair follows a stopped or already passing round')
    if expected['status'] == 'fail' and len(evidence) != common['max_snippet_fixes'] + 1:
        raise ValueError('Saved failure has not exhausted the common repair budget')
    verify_result_fields(row, expected)

def _hint_content(condition, function_ids):
    index = index_source_hints(condition['source']['worktree'], condition['source_hints'], function_ids)
    fields = ('function_id', 'requirement_id', 'requirement', 'signature', 'action', 'validation', 'diagnostic', 'status')
    return sorted((tuple(str(row.get(k)) for k in fields) for row in index['records']))

def _matching_implementation(cfg, backends, baseline, treatment):
    """Allow only removal of validated annotation comment blocks in hint arms.

    Git still binds the actual source bytes. This comparison does not certify
    runtime equivalence; reference and negative controls run for every backend.
    """
    left, right = backends[baseline]['code_files'], backends[treatment]['code_files']
    if left == right:
        return True
    condition = cfg['conditions'][treatment]
    if cfg['schema_version'] != 2 or treatment not in HINT_ARMS or set(left) != set(right):
        return False
    base = Path(cfg['conditions'][baseline]['source']['worktree'])
    root = Path(condition['source']['worktree'])
    permitted = {str(Path(p)) for p in condition['source_hints']}
    for path in left:
        if left[path] == right[path]:
            continue
        if path not in permitted or left[path][0] != right[path][0]:
            return False
        if strip_source_hints((root / path).read_bytes().decode('utf-8')) != (base / path).read_bytes().decode('utf-8'):
            return False
    return True

def hint_bundle(path, function_ids):
    value = _mapping(load(path), 'Hint bundle')
    if type(value.get('schema_version')) is not int or value['schema_version'] != 1:
        raise ValueError('Hint bundle needs schema_version 1')
    hints = value.get('hints')
    if not isinstance(hints, list) or not hints:
        raise ValueError('Hint treatment needs nonempty hints')
    known = False
    for h in hints:
        _mapping(h, 'Hint')
        for key in ('function_id', 'error_contains', 'likely_cause', 'validation'):
            _text(h.get(key), 'Hint ' + key)
        _string_list(h.get('fix_steps'), 'Hint fix_steps')
        _text(h.get('suggested_fix_code', ''), 'Hint code', allow_empty=True)
        known |= h['function_id'] in function_ids
    if not known:
        raise ValueError('Hints do not cover selected function IDs; supply api_function_ids')
    return value

def match_treatments(cfg, backends):
    """Reject treatment contamination before any model or checker command."""
    conditions = cfg['conditions']
    signatures = {arm: [bind(p)['sha256'] for p in c['documents']] for arm, c in conditions.items()}
    original = signatures['original']
    for arm, c in conditions.items():
        if arm not in README_ARMS and signatures[arm] != original:
            raise ValueError(f'{arm} must receive the original documentation bytes')
        hint_field = 'source_hints' if cfg['schema_version'] == 2 else 'error_hints'
        obsolete = 'error_hints' if cfg['schema_version'] == 2 else 'source_hints'
        if obsolete in c:
            raise ValueError(f'{arm}: {obsolete} is not part of this protocol')
        for field, allowed in (('alias_interface', ALIAS_ARMS), (hint_field, HINT_ARMS)):
            if (field in c) != (arm in allowed):
                raise ValueError(f'{arm}: unexpected or missing {field}')
        if arm in ('readme_only', 'error_hints_only'):
            if not _matching_implementation(cfg, backends, 'original', arm):
                raise ValueError(f'{arm} must retain the original backend code tree')
    if 'combined' in conditions:
        if signatures['readme_only'] != signatures['combined']:
            raise ValueError('Combined must reuse the README-only documentation bytes')
        for field, arm in (('alias_interface', 'alias_only'),):
            if bind(conditions[arm][field])['sha256'] != bind(conditions['combined'][field])['sha256']:
                raise ValueError('Combined must reuse the individual ' + field + ' bytes')
        if cfg['schema_version'] == 2:
            left = _hint_content(conditions['error_hints_only'], source_api_function_ids(cfg))
            right = _hint_content(conditions['combined'], source_api_function_ids(cfg))
            if left != right:
                raise ValueError('Combined must reuse the individual source guidance')
        elif bind(conditions['error_hints_only']['error_hints'])['sha256'] != bind(conditions['combined']['error_hints'])['sha256']:
            raise ValueError('Combined must reuse the individual error_hints bytes')
        if not _matching_implementation(cfg, backends, 'alias_only', 'combined'):
            raise ValueError('Combined must reuse the alias-only backend code tree')
        if backends['alias_only']['code_tree_sha256'] == backends['original']['code_tree_sha256']:
            raise ValueError('Alias treatment requires a changed backend code tree')
        baseline, aliases = backends['original']['code_files'], backends['alias_only']['code_files']
        if any(aliases.get(path) != entry for path, entry in baseline.items()):
            raise ValueError('Alias-only must add wrappers without modifying baseline tracked files')
    if 'refactor_only' in conditions and backends['refactor_only']['code_tree_sha256'] == backends['original']['code_tree_sha256']:
        raise ValueError('Refactor-only requires a changed backend with the original target IDs')

def measured_conditions(cfg):
    """Audience scope; every declared backend still participates in validation."""
    return tuple(cfg.get('measured_conditions', cfg['conditions']))

def read_bank(path, cfg, refs):
    """The v1 protocol keeps canonical target IDs and requires all three controls."""
    bank = _mapping(load(path), 'Bank')
    _text(bank.get('scope_note', ''), 'Scope note', allow_empty=True)
    api_names = _string_list(bank.get('api_names'), 'API names')
    if len(set(api_names)) != len(api_names):
        raise ValueError('Duplicate API scope')
    cases = bank.get('cases')
    if not isinstance(cases, list) or not cases:
        raise ValueError('Bank needs nonempty cases')
    ids, micro = set(), set()
    development = _string_list(cfg.get('development_case_ids', []), 'Development IDs', allow_empty=True)
    for c in cases:
        _mapping(c, 'Case')
        if not _valid_identifier(c.get('id')) or c['id'] in ids:
            raise ValueError('Unsafe or duplicate case ID')
        ids.add(c['id'])
        if c.get('kind') not in ('micro', 'puzzle') or c.get('split') != 'held_out':
            raise ValueError('Cases need micro/puzzle kind and held_out split')
        _text(c.get('prompt'), 'Case prompt')
        _text(c.get('public_context', ''), 'Public context', allow_empty=True)
        targets = _string_list(c.get('target_apis'), 'Canonical target APIs')
        if set(targets) - set(api_names) or len(set(targets)) != len(targets):
            raise ValueError('Targets must be unique members of the canonical API scope')
        if c['kind'] == 'micro':
            if len(targets) != 1:
                raise ValueError('Microtasks require one canonical target')
            micro.update(targets)
        for field in ('oracle', 'reference'):
            c[field] = str(_path(path.parent, c.get(field)))
            refs.append(bind(c[field]))
        for field in ('negative_controls', 'target_negative_controls'):
            _string_list(c.get(field), field)
            c[field] = [str(_path(path.parent, p)) for p in c[field]]
            refs.extend(bind(p) for p in c[field])
    if ids & set(development):
        raise ValueError('Development/evaluation IDs overlap')
    if micro != set(api_names) or not any(c['kind'] == 'puzzle' for c in cases):
        raise ValueError('Bank needs complete declared micro API coverage and puzzles')
    mapping = cfg.get('api_function_ids', {name: name for name in api_names})
    _mapping(mapping, 'api_function_ids')
    if set(mapping) != set(api_names):
        raise ValueError('api_function_ids must map every canonical API exactly once')
    for value in mapping.values():
        _text(value, 'Qualified function ID')
    if len(set(mapping.values())) != len(mapping):
        raise ValueError('Qualified function IDs must be distinct')
    cfg['api_function_ids'] = mapping
    if 'source_api_function_ids' in cfg:
        if cfg['schema_version'] != 2:
            raise ValueError('source_api_function_ids requires schema_version 2')
        catalog = _mapping(cfg['source_api_function_ids'], 'source_api_function_ids')
        for name, value in catalog.items():
            _text(name, 'Source API name')
            _text(value, 'Source function ID')
        if any(catalog.get(name) != identity for name, identity in mapping.items()):
            raise ValueError('Source API catalog must preserve every task-bank API identity')
        if len(set(catalog.values())) != len(catalog):
            raise ValueError('Source API catalog function IDs must be distinct')
    return bank

def source_api_function_ids(cfg):
    """The attribution catalog may include helpers outside the scored task bank."""
    return cfg.get('source_api_function_ids', cfg['api_function_ids'])

def _adjudication_artifacts_valid(refs):
    """Optional adapter evidence must be a nonempty list of canonical file bindings."""
    if not isinstance(refs, list) or not refs:
        return False
    seen = set()
    for ref in refs:
        if (not isinstance(ref, dict) or set(ref) != {'path', 'sha256', 'bytes'}
                or not isinstance(ref['path'], str) or not Path(ref['path']).is_absolute()
                or not isinstance(ref['sha256'], str) or re.fullmatch(r'[0-9a-f]{64}', ref['sha256']) is None
                or type(ref['bytes']) is not int or ref['bytes'] < 0 or ref['path'] in seen):
            return False
        seen.add(ref['path'])
        try:
            if bind(ref['path']) != ref:
                return False
        except (OSError, ValueError, RuntimeError):
            return False
    return True

def _controller(cfg=None):
    optional = ('documentation_selection.py',) if cfg and 'documentation_selection' in cfg['common'] else ()
    return {name: file_hash(Path(__file__).with_name(name)) for name in MODULES + optional}

def checked_outcome(process, backend_sha256):
    value = process.get('payload')
    if not isinstance(value, dict) or value.get('backend_sha256') != backend_sha256:
        return None
    if not isinstance(value.get('public_feedback', ''), str):
        return None
    if 'adjudication_artifacts' in value and not _adjudication_artifacts_valid(value['adjudication_artifacts']):
        return None
    return verified_outcome(process)

def checker_request(payload, arm, case, code):
    """Private routing contract; never insert backend/config/oracle into model text."""
    return {'protocol': payload.get('protocol', PROTOCOL), 'condition': arm, 'backend': payload['backends'][arm],
            'code': code, 'case_id': case['id'], 'oracle_path': case['oracle'],
            'target_apis': case['target_apis']}

def freeze_conditions(config, output):
    output = Path(output).resolve()
    assert_review_released(output)
    payload = read_condition_config(config)
    validation = validate_conditions(payload, output / 'validation')
    if not validation['validated']:
        raise ValueError('Condition controls failed; inspect validation evidence')
    verify_inputs(payload)
    frozen = {**payload, 'validation': validation}
    frozen['study_sha256'] = digest(frozen)
    verify_validation(frozen)
    with ownership(output):
        path = output / 'frozen.json'
        if path.exists() and load(path) != frozen:
            raise ValueError('Existing condition freeze differs')
        if not path.exists():
            atomic_json(path, frozen)
    return {'frozen': str(path), 'study_sha256': frozen['study_sha256'], 'protocol': payload['protocol'],
            'conditions': list(payload['config']['conditions']), 'cases': len(payload['bank']['cases']),
            'measured_conditions': list(measured_conditions(payload['config'])),
            'validated': True}

def open_conditions(path):
    assert_review_released(Path(path).resolve().parent)
    frozen = load(path)
    if frozen.get('protocol') not in (PROTOCOL, SOURCE_PROTOCOL):
        raise ValueError('This command requires a supported condition evaluation freeze')
    if frozen.get('study_sha256') != digest({k: v for k, v in frozen.items() if k != 'study_sha256'}):
        raise ValueError('Frozen condition study was edited')
    verify_inputs(frozen)
    verify_validation(frozen)
    return frozen

def read_condition_config(path):
    path = Path(path).resolve()
    raw = _mapping(yaml.safe_load(path.read_text()), 'Configuration')
    cfg = _mapping(raw.get('condition_evaluation'), 'condition_evaluation')
    if type(cfg.get('schema_version')) is not int or cfg['schema_version'] not in (1, 2):
        raise ValueError('condition_evaluation needs schema_version 1 or 2')
    if not isinstance(cfg.get('design'), str) or cfg['design'] not in DESIGNS:
        raise ValueError('Choose five_arm, refactor_pair, or six_arm')
    arms = DESIGNS[cfg['design']]
    conditions = _mapping(cfg.get('conditions'), 'conditions')
    if set(conditions) != set(arms):
        raise ValueError('Conditions do not match the declared design')
    cfg['conditions'] = {arm: conditions[arm] for arm in arms}
    if 'measured_conditions' in cfg:
        if cfg['schema_version'] != 2:
            raise ValueError('measured_conditions requires schema_version 2')
        measured = _string_list(cfg['measured_conditions'], 'measured_conditions')
        if len(set(measured)) != len(measured) or set(measured) - set(arms):
            raise ValueError('measured_conditions must be unique declared conditions')
        cfg['measured_conditions'] = [arm for arm in arms if arm in measured]
    refs = [bind(path)]
    cfg['bank'] = str(_path(path.parent, cfg.get('bank')))
    refs.append(bind(cfg['bank']))
    bind_command(cfg.get('model'), 'model', path.parent, refs)
    _validate_common(_mapping(cfg.get('common'), 'common'), cfg['model'])
    for field in ('alias_max_characters', 'hint_max_characters'):
        value = cfg['common'].setdefault(field, 4000)
        if type(value) is not int or value < 1:
            raise ValueError(field + ' must be a positive integer')
    if cfg['schema_version'] == 2:
        cfg['common'].setdefault('repair_context', 'distilled')
        minimum = cfg['common'].setdefault('minimum_hint_coverage', 0.0)
        if type(minimum) not in (int, float) or not math.isfinite(minimum) or not 0 <= minimum <= 1:
            raise ValueError('minimum_hint_coverage must be between zero and one')
    _text(cfg.get('holdout_review'), 'Holdout review')
    bank = read_bank(Path(cfg['bank']), cfg, refs)
    if 'documentation_selection' in cfg['common']:
        from .documentation_selection import validate_documentation_selection
        validate_documentation_selection(cfg['common']['documentation_selection'], bank['api_names'])
    backends, source_indexes = {}, {}
    for arm, condition in cfg['conditions'].items():
        _mapping(condition, arm)
        _string_list(condition.get('documents'), arm + ' documents')
        condition['documents'] = [str(_path(path.parent, p)) for p in condition['documents']]
        refs.extend(bind(p) for p in condition['documents'])
        for field in ('alias_interface', 'error_hints'):
            if field in condition:
                condition[field] = str(_path(path.parent, condition[field]))
                refs.append(bind(condition[field]))
                if field == 'alias_interface' and not Path(condition[field]).read_text().strip():
                    raise ValueError('Alias interface must not be empty')
        if 'error_hints' in condition:
            hint_bundle(condition['error_hints'], set(cfg['api_function_ids'].values()))
        bind_command(condition.get('adapter'), arm + ' adapter', path.parent, refs)
        source = _mapping(condition.get('source'), arm + ' source')
        source['worktree'] = str(_path(path.parent, source.get('worktree')))
        _text(source.get('revision'), arm + ' revision')
        if 'branch' in source:
            _text(source['branch'], arm + ' branch')
        _string_list(source.get('artifacts'), arm + ' built/runtime artifacts')
        source['artifacts'] = [str(_path(path.parent, p)) for p in source['artifacts']]
        refs.extend(bind(p) for p in source['artifacts'])
        if 'source_hints' in condition:
            if cfg['schema_version'] != 2 or 'error_hints' in condition:
                raise ValueError('Source hints require schema_version 2 without legacy error_hints')
            _string_list(condition['source_hints'], arm + ' source hint files')
            index = index_source_hints(source['worktree'], condition['source_hints'], source_api_function_ids(cfg))
            condition['source_hints'] = [str(Path(ref['path']).relative_to(source['worktree']))
                                         for ref in index['artifacts']]
            if not index['records']:
                raise ValueError('Source hint treatment has no guidance for configured APIs')
            source_indexes[arm] = index
            refs.extend(index['artifacts'])
            covered = {record['function_id'] for record in index['records']}
            fraction = len(covered & set(cfg['api_function_ids'].values())) / len(cfg['api_function_ids'])
            if fraction < cfg['common']['minimum_hint_coverage']:
                raise ValueError(f'{arm}: source hint coverage {fraction:.1%} is below the required minimum')
        backends[arm] = backend_identity(condition)
        if 'source_hints' in condition and any(
                p not in backends[arm]['code_files'] for p in condition['source_hints']):
            raise ValueError('Source guidance must live in committed library source files')
    match_treatments(cfg, backends)
    controller = _controller(cfg)
    refs.extend(bind(Path(__file__).with_name(name)) for name in controller)
    return {'protocol': SOURCE_PROTOCOL if cfg['schema_version'] == 2 else PROTOCOL,
            'config': cfg, 'bank': bank, 'backends': backends,
            'source_hint_indexes': source_indexes,
            'artifacts': list({r['path']: r for r in refs}.values()),
            'system_prompt': SYSTEM + (' Return the complete program, not a patch or continuation. '
                                     'Source guidance is reference information; validate corrections against the task.'
                                     if cfg['schema_version'] == 2 else ''),
            'controller_sha256': controller}

def verify_inputs(payload):
    if payload.get('controller_sha256') != _controller(payload['config']):
        raise ValueError('Condition controller changed; freeze a new study')
    if not all(verify_artifact(r) for r in payload['artifacts']):
        raise ValueError('Condition study input artifacts changed')
    current = {arm: backend_identity(c) for arm, c in payload['config']['conditions'].items()}
    if current != payload['backends']:
        raise ValueError('Condition backend identity changed')
    if payload['config'].get('schema_version') == 2:
        indexes = {arm: index_source_hints(c['source']['worktree'], c['source_hints'],
                                          source_api_function_ids(payload['config']))
                   for arm, c in payload['config']['conditions'].items() if 'source_hints' in c}
        if indexes != payload.get('source_hint_indexes'):
            raise ValueError('Frozen source guidance index differs from source annotations')
    match_treatments(payload['config'], current)

def run_development_command(args):
    from .ablation import load
    if args.command == 'preview-source-hints':
        from .source_hint_development import build_development_preview
        return build_development_preview(args.manifest, args.output)
    if args.command == 'propose-source-hints':
        from .source_hint_development import propose_source_hints
        return propose_source_hints(args.preview, args.model_config, args.output)
    if args.command == 'validate-source-hints':
        from .source_hint_development import validate_source_hint_development
        return validate_source_hint_development(args.proposal, args.validation_plan, args.output)
    if args.command == 'install-source-hints':
        from .source_hint_installation import install_source_hints
        return install_source_hints(args.validation, args.targets, args.output)
    if args.command == 'preview-library':
        from .improvement_batches import preview_library_improvements
        return preview_library_improvements(args.study, args.output,
            alias_path_template=args.alias_path_template, apis=args.apis,
            development_errors=args.development_errors, batch_size=args.batch_size,
            max_context_characters=args.max_context_characters, max_batches=args.max_batches,
            max_catalog_characters=args.max_catalog_characters, max_error_characters=args.max_error_characters)
    if args.command == 'propose-library':
        from .improvement_batches import propose_library_improvements
        return propose_library_improvements(args.preview, args.model_config, args.output,
                                            max_batches=args.max_batches)
    if args.command == 'bundle-proposals':
        from .treatment_bundles import bundle_proposals
        return bundle_proposals(args.proposals, args.output, readme=args.readme)
    if args.command in ('install-refactor', 'versions'):
        from .source_refactors import install_refactor, study_versions
        return (install_refactor(args.study, args.proposal) if args.command == 'install-refactor'
                else study_versions(args.study))
    if args.command == 'preview-improvements':
        from .improvement_context import preview_improvements
        return preview_improvements(args.study, args.output, alias_path=args.alias_path,
            apis=args.apis, development_errors=args.development_errors, max_apis=args.max_apis,
            max_context_characters=args.max_context_characters)
    if args.command == 'propose-improvements':
        from .improvement_suggestions import propose_improvements
        return propose_improvements(args.preview, args.model_config, args.output, readme=args.readme)
    if args.command == 'install-treatments':
        from .treatment_versions import apply_treatments
        return apply_treatments(args.study, args.proposal)
    if args.command == 'show-fix-hints':
        from .improvement_suggestions import matching_fix_hints
        return {'status': 'unverified', 'hints': matching_fix_hints(
            load(args.hints), args.function, Path(args.error_file).read_text())}
    from .source_duplicates import scan_duplicates, compare_duplicate_reports
    if args.command == 'scan-duplicates':
        result = scan_duplicates(args.repo, source_globs=args.source_globs)
    else:
        result = compare_duplicate_reports(load(args.before), load(args.after))
    path = Path(args.output).resolve()
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open('x') as stream:
        json.dump(result, stream, indent=2, ensure_ascii=False, allow_nan=False)
        stream.write('\n')
    return result

def _fallback_score(section, api):
    # Specific spelling wins over any number of incidental bare-name mentions.
    terms = (api, '.'.join(api.split('.')[-2:]), api.split('.')[-1])
    return tuple(_mentions(section['text'], term) for term in terms)

def _identity(heading):
    if heading is None:
        return None
    value = re.sub(r'^API Test:\s*', '', heading).strip()
    if value.startswith('`') and value.endswith('`'):
        value = value[1:-1]
    return value

def _section_receipt(section, length):
    return {'index': section['index'], 'file_index': section['file_index'], 'path': section['path'],
            'heading': section['heading'], 'source_start_character': section['start'],
            'source_end_character': section['end'], 'delivered_end_character': section['start'] + length,
            'source_characters': len(section['text']), 'delivered_characters': length,
            'full_section': length == len(section['text']), 'clipped': length < len(section['text']),
            'delivered_sha256': digest(section['text'][:length])}

def markdown_sections(text):
    """Split real Markdown H2 sections, ignoring headings inside fenced blocks.

    Character ranges refer to decoded text, not raw byte offsets. Backtick
    and tilde fences follow the same-character/at-least-opening-length rule.
    """
    starts, offset, fence = [(0, None)], 0, None
    for line in text.splitlines(keepends=True):
        stripped = line.rstrip('\r\n')
        marker = re.match(r'^ {0,3}(`{3,}|~{3,})(.*)$', stripped)
        if fence:
            if marker and marker[1][0] == fence[0] and len(marker[1]) >= fence[1] and not marker[2].strip():
                fence = None
        elif marker:
            # A backtick fence's info string cannot itself contain a backtick.
            if marker[1][0] != '`' or '`' not in marker[2]:
                fence = (marker[1][0], len(marker[1]))
        else:
            heading = re.match(r'^ {0,3}##[ \t]+(.+?)[ \t]*$', stripped)
            if heading:
                title = re.sub(r'[ \t]+#+[ \t]*$', '', heading[1]).strip()
                if offset == 0:
                    starts[0] = (0, title)
                else:
                    starts.append((offset, title))
        offset += len(line)
    sections = []
    for index, (start, heading) in enumerate(starts):
        end = starts[index + 1][0] if index + 1 < len(starts) else len(text)
        if start != end:
            sections.append({'start': start, 'end': end, 'heading': heading, 'text': text[start:end]})
    return sections

def select_qualified_sections(paths, targets, max_characters, selection):
    """Select one exact section per target, then receiver/name fallback if absent.

    Other explicitly qualified API sections never substitute for a missing exact
    identity. Unstructured Original documentation may fall back lexically; if no
    target has a match, its original ordered prefix is delivered. Relevant
    sections that fit are not padded with unrelated API entries. Quotas are fair
    across distinct required sections. A clipped section may end mid-code; the
    receipt records the exact range and does not claim full-section coverage.
    """
    validate_documentation_selection(selection)
    if type(max_characters) is not int or max_characters < 1:
        raise ValueError('documentation_max_characters must be a positive integer')
    if not targets or len(set(targets)) != len(targets) or set(targets) - set(selection['api_headings']):
        raise ValueError('Every requested API must have one reviewed heading')
    texts, sections = [], []
    for file_index, path in enumerate(paths):
        text = Path(path).read_text()
        texts.append(text)
        for section in markdown_sections(text):
            sections.append({**section, 'index': len(sections), 'file_index': file_index, 'path': str(path),
                             'joined_start': sum(len(t) for t in texts[:-1]) + 2 * file_index + section['start']})
    source = '\n\n'.join(texts)
    choices, primary = {}, []
    for api in sorted(targets):
        expected = selection['api_headings'][api]
        matches = [s for s in sections if _identity(s['heading']) == expected]
        if len(matches) > 1:
            raise ValueError('Duplicate exact qualified heading: ' + expected)
        section, mode = (matches[0], 'exact_heading') if matches else (None, 'absent')
        if section is None:
            candidates = [s for s in sections if not _structured(s)]
            candidates.sort(key=lambda s: tuple(-n for n in _fallback_score(s, api)) + (s['index'],))
            if candidates and any(_fallback_score(candidates[0], api)):
                section, mode = candidates[0], 'lexical_fallback'
        choices[api] = (section, mode)
        if section is not None and section['index'] not in primary:
            primary.append(section['index'])
    records = []
    if primary:
        chosen = [sections[i] for i in primary]
        budget = max(0, max_characters - 2 * (len(chosen) - 1))
        lengths = _fair_lengths([len(s['text']) for s in chosen], budget)
        pieces = []
        for section, length in zip(chosen, lengths):
            if length:
                if pieces:
                    pieces.append('\n\n')
                pieces.append(section['text'][:length])
                records.append(_section_receipt(section, length))
        delivered = ''.join(pieces)
        mode = 'target_sections'
    else:
        delivered = source[:max_characters]
        mode = 'ordered_prefix_no_match'
        for section in sections:
            length = max(0, min(len(section['text']), len(delivered) - section['joined_start']))
            if length:
                records.append(_section_receipt(section, length))
    selected = {r['index']: r for r in records}
    coverage = {}
    for api, (section, match) in choices.items():
        record = selected.get(section['index']) if section is not None else None
        coverage[api] = {'expected_heading': selection['api_headings'][api], 'match': match,
                         'selected_heading': section['heading'] if section else None,
                         'section_index': section['index'] if section else None,
                         'coverage': ('full' if record and record['full_section'] else 'clipped' if record else 'absent'),
                         'delivered_characters': record['delivered_characters'] if record else 0}
    return delivered, {'policy': POLICY, 'mode': mode, 'source_characters': len(source),
                       'delivered_characters': len(delivered), 'selected_section_indices': [r['index'] for r in records],
                       'selected_sections': records, 'targets': coverage,
                       'truncated': len(delivered) < len(source), 'delivered_sha256': digest(delivered)}

def validate_documentation_selection(value, api_names=None):
    """Reject malformed/misdirected maps before controls or provider execution."""
    if not isinstance(value, dict) or set(value) != {'policy', 'api_headings'}:
        raise ValueError('documentation_selection needs policy and api_headings only')
    if value['policy'] != POLICY:
        raise ValueError('Unknown documentation_selection policy')
    mapping = value['api_headings']
    if not isinstance(mapping, dict) or not mapping:
        raise ValueError('api_headings must be a nonempty mapping')
    for api, heading in mapping.items():
        if (not isinstance(api, str) or not api.strip() or '\n' in api or '\r' in api
                or not isinstance(heading, str)
                or re.fullmatch(re.escape(api) + r' \[(?:class|object)\]', heading) is None):
            raise ValueError('api_headings values must match the canonical API plus [class] or [object]')
    if len(set(mapping.values())) != len(mapping):
        raise ValueError('api_headings must be distinct')
    if api_names is not None and set(mapping) != set(api_names):
        raise ValueError('api_headings must map every bank API exactly once, with no extra APIs')
    return value

def _candidate_body(code):
    if code.strip().startswith('```'):
        match = re.fullmatch(r'\s*```[^\n]*\n(.*?)\n```\s*', code, re.S)
        if match:
            return match[1]
    return code

def _collect_resources(directory):
    """Count all attempts, including interrupted calls with unknown token usage."""
    resources = {'provider_calls': 0, 'provider_seconds': 0, 'execution_seconds': 0,
                 'reported_input_tokens': 0, 'reported_output_tokens': 0, 'calls_without_usage': 0}
    for p in directory.glob('round_*/provider_*'):
        resources['provider_calls'] += 1
        proc = load(p / 'process.json') if (p / 'process.json').exists() else {}
        resources['provider_seconds'] += proc.get('seconds', 0)
        payload = proc.get('payload')
        usage = payload.get('usage') if isinstance(payload, dict) else None
        usage = usage if isinstance(usage, dict) else {}
        if not all(type(usage.get(k)) is int and usage[k] >= 0 for k in ('input_tokens', 'output_tokens')):
            resources['calls_without_usage'] += 1
        else:
            resources['reported_input_tokens'] += usage['input_tokens']
            resources['reported_output_tokens'] += usage['output_tokens']
    for p in directory.glob('round_*/execution_*/process.json'):
        resources['execution_seconds'] += load(p)['seconds']
    return resources

def _load_completed_rows(output):
    """Read only unit checkpoints and reject duplicates before another model call."""
    rows = {}
    for path in output.glob('*/*/result.json'):
        row = load(path)
        key = (row['arm'], row['case_id'], row['trial_id'])
        if key in rows:
            raise ValueError(f'Duplicate saved result: {key}')
        expected = output / key[0] / f'{key[1]}--{key[2]}' / 'result.json'
        if path != expected:
            raise ValueError(f'Saved result does not match its directory: {path}')
        rows[key] = row
    return rows

def _model_response(result):
    """Compatibility entry point shared by cached and new provider responses."""
    return model_response(result)

def _readme_request(frozen, case, documentation, previous, round_number):
    cfg, common = frozen['config'], frozen['config']['common']
    receipt = None
    if previous and common.get('repair_context') == 'distilled':
        previous, receipt = compact_previous(previous)
    return {'system': frozen['system_prompt'], 'prompt': audience_prompt(case, documentation, previous),
            'model': cfg['model']['name'], 'temperature': common['temperature'],
            'max_output_tokens': output_limit(common, round_number)}, receipt

def _verify_readme_row(frozen, row, directory):
    """Rebuild requests and outcomes from raw attempts before any resume."""
    cfg, common = frozen['config'], frozen['config']['common']
    if row.get('round_evidence') != rounds(directory):
        raise ValueError('Saved condition attempt evidence changed')
    if row.get('resources') != _collect_resources(directory):
        raise ValueError('Saved condition resource totals differ from attempt evidence')
    evidence = row['round_evidence']
    if not evidence or [r['round'] for r in evidence] != list(range(len(evidence))):
        raise ValueError('Saved evidence has missing or unexpected rounds')
    if len(evidence) > common['max_snippet_fixes'] + 1:
        raise ValueError('Saved result exceeds the common repair budget')
    case = next(c for c in frozen['bank']['cases'] if c['id'] == row['case_id'])
    docs, exposure = select_documentation(cfg['documents'][row['arm']], case['target_apis'],
                                          common.get('documentation_max_characters', 32000),
                                          common.get('documentation_selection'))
    if load(directory / 'documentation_exposure.json') != exposure:
        raise ValueError('Saved documentation exposure differs from the frozen prompt')
    expected = {'status': 'not_run', 'first_attempt_pass': False}
    previous = None
    for item in evidence:
        number = item['round']
        request, repair_receipt = _readme_request(frozen, case, docs, previous, number)
        if repair_receipt is not None:
            if 'repair_context' not in item or load(item['repair_context']['path']) != repair_receipt:
                raise ValueError('Saved repair context differs from the frozen prompt')
        elif 'repair_context' in item:
            raise ValueError('Unexpected saved repair context')
        selected = selected_response(item['providers'], request)
        if selected is None:
            if item['executions'] or item.get('generation'):
                raise ValueError('Execution/generation evidence lacks a provider response')
            expected['status'] = 'provider_pending'
        else:
            response, files = selected
            executable = mark_generation(expected, response, number)
            if not executable:
                if item['executions']:
                    raise ValueError('Nonexecutable generation has execution evidence')
                verify_generation(item, response, files)
            else:
                code = _candidate_body(response['code'])
                checker = adapter_request(case, code)
                checked = None
                for attempt in item['executions']:
                    records = attempt['files']
                    if 'request.json' in records and load(records['request.json']['path']) != checker:
                        raise ValueError('Saved checker candidate differs from the provider response')
                    if 'process.json' in records:
                        if 'request.json' not in records:
                            raise ValueError('Saved checker process lacks its request')
                        process = load(records['process.json']['path'])
                        outcome = verified_outcome(process)
                        if checked is not None:
                            raise ValueError('Saved execution follows an already checked outcome')
                        if outcome is not None:
                            checked = (outcome, process, records)
                verify_generation(item, response, files)
                if checked is None:
                    expected['status'] = 'unverified'
                else:
                    outcome, process, records = checked
                    expected.update({k: process['payload'][k] for k in ('execution_pass', 'oracle_pass', 'target_reached')})
                    expected.update(status='pass' if outcome else 'fail', last_checked_round=number,
                                    code_sha256=digest(code), adjudication={k: records[v] for k, v in
                                                                         [('process', 'process.json'), ('request', 'request.json')]})
                    if outcome:
                        expected.update(first_attempt_pass=number == 0, first_pass_round=number)
                    previous = previous_result(code, process['payload'], 'Independent checks did not pass.')
        if number < len(evidence) - 1 and expected['status'] != 'fail':
            raise ValueError('Saved repair follows a stopped or already passing round')
    if expected['status'] == 'fail' and len(evidence) != common['max_snippet_fixes'] + 1:
        raise ValueError('Saved failure has not exhausted the common repair budget')
    verify_result_fields(row, expected)

def audience_prompt(case, documentation, previous=None):
    """Build public model context; exclude oracle paths and reference answers."""
    sections = ['TASK\n' + case['prompt'], 'SHARED CONTRACT\n' + case.get('public_context', ''),
                'DOCUMENTATION\n' + documentation]
    if previous:
        sections += ['COMPLETE PREVIOUS SOLUTION\n' + previous['code'],
                     'EXECUTION FEEDBACK\n' + previous['feedback']]
    return '\n\n'.join(sections)

def previous_result(code, payload, fallback='Independent checks failed.'):
    previous = {'code': code, 'feedback': payload.get('public_feedback', fallback)}
    failure = public_failure(payload)
    if failure is not None:
        previous['public_failure'] = failure
    return previous

def select_documentation(paths, targets, max_characters, selection=None):
    """Select bounded public documentation using a default or explicit policy.

    Without an explicit policy, short documents are delivered in full and long
    documents rank H2 sections by API-name occurrence count, with stable source
    order breaking ties. The opt-in qualified_sections policy logs target-level
    coverage. No LLM selects text and no private answer enters retrieval.
    """
    if selection is not None:
        from .documentation_selection import select_qualified_sections
        return select_qualified_sections(paths, targets, max_characters, selection)
    text = '\n\n'.join(Path(p).read_text() for p in paths)
    chunks = re.split(r'(?m)(?=^## )', text)
    selected = []
    if len(text) <= max_characters:
        delivered = text
        selected = list(range(len(chunks)))
    else:
        def relevance(index):
            return sum(len(re.findall(r'(?<!\w)' + re.escape(t) + r'(?!\w)', chunks[index])) for t in targets)
        order = sorted(range(len(chunks)), key=lambda i: (-relevance(i), i))
        delivered = ''
        for i in order:
            remaining = max_characters - len(delivered)
            if remaining <= 2:
                break
            delivered += ('\n\n' if delivered else '') + chunks[i][:remaining - 2]
            selected.append(i)
    return delivered, {'source_characters': len(text), 'delivered_characters': len(delivered),
                       'selected_section_indices': selected, 'truncated': len(delivered) < len(text),
                       'delivered_sha256': digest(delivered)}

def verify_result_fields(row, expected):
    for key in _RESULT_FIELDS:
        if (key in row) != (key in expected) or row.get(key) != expected.get(key):
            raise ValueError('Saved result differs from the replayed generation/checker verdict: ' + key)

def _controller_hashes(common=None):
    """Identify this controller installation, independent of its location."""
    return {name: file_hash(Path(__file__).with_name(name)) for name in _controller_modules(common)}

def _controller_modules(common=None):
    optional = ('documentation_selection.py',) if common and 'documentation_selection' in common else ()
    return CONTROLLER_MODULES + optional

def _mapping(value, name):
    if not isinstance(value, dict):
        raise ValueError(f'{name}: expected a mapping')
    return value

def _path(base, value):
    _text(value, 'Artifact path')
    p = Path(value).expanduser()
    return (base / p).resolve() if not p.is_absolute() else p.resolve()

def _string_list(value, name, allow_empty=False):
    if (not isinstance(value, list) or (not allow_empty and not value)
            or any(not isinstance(v, str) or not v.strip() for v in value)):
        raise ValueError(f'{name}: expected a list of nonempty strings')
    return value

def _text(value, name, allow_empty=False):
    if not isinstance(value, str) or (not allow_empty and not value.strip()):
        raise ValueError(f'{name}: expected {"a string" if allow_empty else "a nonempty string"}')
    return value

def _validate_common(common, model):
    """Reject ambiguous budgets before creating files or launching commands."""
    if 'documentation_selection' in common:
        from .documentation_selection import validate_documentation_selection
        validate_documentation_selection(common['documentation_selection'])
    source_access = common.get('source_access', False)
    if type(source_access) is not bool:
        raise ValueError('source_access must be a boolean')
    if source_access:
        raise ValueError('This audience adapter is documentation-only; source-browsing agents need a separate protocol')
    if type(common.get('ordering_seed', 42)) is not int:
        raise ValueError('ordering_seed must be an integer')
    integers = {'documentation_max_characters': common.get('documentation_max_characters', 32000),
                'provider_attempt_limit': common.get('provider_attempt_limit'),
                'max_output_tokens': common.get('max_output_tokens')}
    for name, value in integers.items():
        if type(value) is not int or value < 1:
            raise ValueError(f'Positive integer required: {name}')
    if 'repair_max_output_tokens' in common:
        cap = common['repair_max_output_tokens']
        if type(cap) is not int or cap < 1:
            raise ValueError('repair_max_output_tokens must be a positive integer')
    if common.get('repair_context', 'full') not in ('full', 'distilled'):
        raise ValueError('repair_context must be full or distilled')
    repairs = common.get('max_snippet_fixes')
    if type(repairs) is not int or repairs < 0:
        raise ValueError('Declare a nonnegative integer repair budget')
    for name in ('execution_timeout_s', 'provider_timeout_s', 'temperature'):
        value = common.get(name)
        if type(value) not in (int, float) or not math.isfinite(value):
            raise ValueError(f'Finite numeric setting required: {name}')
        if value < 0 or (name != 'temperature' and value == 0):
            raise ValueError(f'Invalid setting: {name}')
    _text(model.get('name'), 'Model name')
    trials = common.get('trial_ids')
    if not isinstance(trials, list) or not trials or not all(_valid_identifier(t) for t in trials):
        raise ValueError('Supply nonempty, safe trial IDs')
    if len(set(trials)) != len(trials):
        raise ValueError('Duplicate trials')

def adapter_request(case, code):
    """Private request to the trusted checker; never forward it to the model."""
    return {'code': code, 'case_id': case['id'], 'oracle_path': case['oracle'],
            'target_apis': case['target_apis']}

def assert_review_released(directory):
    """Honor an explicit review hold before executing any study work."""
    directory = Path(directory).resolve()
    for parent in (directory, directory.parent):
        hold = parent / 'REVIEW_HOLD.json'
        if hold.exists():
            raise ValueError(f'Evaluation paused for user code review: {hold}')

def control_passes(role, result):
    """A wrong-output control must run; a compiler error cannot validate an oracle."""
    outcome = verified_outcome(result)
    if role == 'reference':
        return outcome is True
    if outcome is not False or not result['payload']['execution_pass']:
        return False
    checked = result['payload']
    if role == 'wrong_output':
        return checked['oracle_pass'] is False
    if role == 'no_target_call':
        return checked['oracle_pass'] is True and checked['target_reached'] is False
    raise ValueError(f'Unknown control role: {role}')

def freeze_evaluation(config, output):
    """Validate actual controls, then save a new immutable study description."""
    output = Path(output).resolve()
    assert_review_released(output)
    payload = read_config(config)
    validation = validate_bank(payload, output / 'validation')
    if not validation['validated']:
        raise ValueError(f'Oracle controls failed; inspect {output / "validation"}')
    # Validate bytes again after potentially long-running controls.
    if not all(verify_artifact(r) for r in payload['artifacts']):
        raise ValueError('Inputs changed during validation')
    frozen = {**payload, 'validation': validation}
    frozen['study_sha256'] = digest(frozen)
    with ownership(output):
        destination = output / 'frozen.json'
        if destination.exists():
            if load(destination) != frozen:
                raise ValueError('Existing frozen study differs')
        else:
            atomic_json(destination, frozen)
    return {'frozen': str(destination), 'study_sha256': frozen['study_sha256'],
            'cases': len(payload['bank']['cases']), 'conditions': list(conditions_for(payload['config'])), 'validated': True}

def open_frozen(path):
    """Reject changed inputs; never silently rebind an old run to edited code."""
    frozen = load(path)
    if frozen['study_sha256'] != digest({k: v for k, v in frozen.items() if k != 'study_sha256'}):
        raise ValueError('Frozen study was edited')
    conditions_for(frozen['config'])
    if 'controller_sha256' not in frozen:
        raise ValueError('Frozen study lacks controller identity; validate and freeze a new study')
    if frozen['controller_sha256'] != _controller_hashes(frozen['config']['common']):
        raise ValueError('Running controller changed; validate and freeze a new study')
    refs = frozen['artifacts'] + [r['evidence'] for r in frozen['validation']['controls']]
    if not frozen['validation']['validated'] or not all(verify_artifact(r) for r in refs):
        raise ValueError('Frozen inputs/controls changed; validate and freeze a new study')
    return frozen

def verified_outcome(process):
    """Return True/False for a checked solution, or None for a checker failure."""
    p = process.get('payload')
    keys = ('execution_pass', 'oracle_pass', 'target_reached')
    if process['status'] != 'ok' or not isinstance(p, dict) or any(type(p.get(k)) is not bool for k in keys):
        return None
    if p['oracle_pass'] and not p['execution_pass']:
        return None
    return all(p[k] for k in keys)

def _stop_process_group(process):
    """Stop descendants in this invocation's private group, returning cleanup errors."""
    try:
        os.killpg(process.pid, signal.SIGKILL)
    except ProcessLookupError:
        return None  # The group has already exited.
    except PermissionError as exc:
        # Some host sandboxes deny group signals. Still stop our direct child,
        # and record that descendant cleanup could not be confirmed.
        if process.poll() is None:
            process.kill()
        return str(exc)
    return None

@contextmanager
def ownership(directory):
    """Hold one OS lock for the writer; process exit releases a stale lock."""
    directory = Path(directory)
    directory.mkdir(parents=True, exist_ok=True)
    with (directory / '.lock').open('a+') as lock:
        try:
            fcntl.flock(lock, fcntl.LOCK_EX | fcntl.LOCK_NB)
        except BlockingIOError as exc:
            raise ValueError('Another worker owns this output directory') from exc
        try:
            yield
        finally:
            fcntl.flock(lock, fcntl.LOCK_UN)

def _calls_at(index, code, line_number, column):
    code = _code_only(code)
    lines = code.splitlines()
    if line_number < 1 or line_number > len(lines):
        return set()
    line = lines[line_number - 1]
    # Do not interpret error locations inside comments as executable calls.
    if line.lstrip().startswith(('#', '//')):
        return set()
    calls = []
    for match in re.finditer(r'\b([A-Za-z_]\w*(?:(?:\.|::)[A-Za-z_]\w*)*)\s*\(', line):
        open_paren = match.end() - 1
        depth, closing = 0, None
        for at in range(open_paren, len(line)):
            if line[at] == '(':
                depth += 1
            elif line[at] == ')':
                depth -= 1
                if depth == 0:
                    closing = at
                    break
        if closing is None:
            continue  # Multiline call inference is deliberately unsupported.
        if column is not None and not match.start() <= column <= closing:
            continue
        name = match[1].replace('::', '.')
        if '.' in name:
            receiver, method = name.rsplit('.', 1)
            ids = _receiver_ids(index, code, receiver, method)
        else:
            # A short function call needs an explicit import, not a task target.
            aliases = re.findall(r'\bfrom\s+([\w.]+)\s+import\s+' + re.escape(name) + r'\b', code)
            ids = {index['api_function_ids'][module + '.' + name] for module in aliases
                   if module + '.' + name in index['api_function_ids']}
        if ids:
            calls.append((closing - match.start(), ids))
    if not calls:
        return set()
    # A caret inside a nested call identifies the innermost known API call.
    if column is not None:
        shortest = min(size for size, _ in calls)
        calls = [item for item in calls if item[0] == shortest]
    return set().union(*(ids for _, ids in calls))

def _import_call_ids(index, masked, class_name, canonical_owner):
    """Require actual calls through the imported owner or an explicit new receiver."""
    receivers = set()
    cls = re.escape(class_name)
    if re.search(r'\b(?:class|object|trait|interface|enum)\s+' + cls + r'\b', masked):
        return set()
    declaration = re.compile(r'\b(?:val|var|' + cls + r')\s+(\w+)\s*(?::[^=\n]+)?=\s*new\s+' + cls + r'\s*\(')
    for match in declaration.finditer(masked):
        receiver = match[1]
        assignments = re.findall(r'\b' + re.escape(receiver) + r'\s*(?::[^=\n]+)?=(?!=)', masked)
        if len(assignments) == 1:
            receivers.add(receiver)
    # A shadowed owner name is not a static/object receiver.
    if not re.search(r'\b(?:class|object|val|var)\s+' + cls + r'\b', masked):
        receivers.add(class_name)
    ids = set()
    for receiver in receivers:
        calls = re.finditer(r'\b' + re.escape(receiver) + r'\.([A-Za-z_]\w*)\s*\(', masked)
        for call in calls:
            api = canonical_owner + '.' + call[1]
            if api in index['api_function_ids']:
                ids.add(index['api_function_ids'][api])
    return ids

def _owners(index, receiver, method):
    """Require an exact qualified owner, or an unambiguous short owner."""
    mapping = index['api_function_ids']
    full = receiver.replace('::', '.').replace('$', '') + '.' + method
    if full in mapping:
        return {mapping[full]}
    if '.' in receiver or '::' in receiver:
        return set()
    return {identity for api, identity in mapping.items()
            if api == full or api.endswith('.' + full)}

def _receiver_ids(index, code, receiver, method):
    # A literal owner call is acceptable only if its owner is unique.
    direct = _owners(index, receiver, method)
    if direct:
        return direct
    escaped = re.escape(receiver)
    types = set()
    # Scala/Python/Rust explicit type annotations and Java declarations.
    for pattern in (rf'\b{escaped}\s*:\s*([\w.]+)',
                    rf'\b([\w.]+)\s+{escaped}\s*=',
                    rf'\b{escaped}\s*=\s*(?:new\s+)?([\w.]+)\s*\('):
        types.update(re.findall(pattern, code))
    types.difference_update({'val', 'var', 'let', 'return'})
    # Multiple writes may shadow a prior declaration even when the second
    # value's type cannot be inferred. Fail closed rather than borrow its type.
    writes = re.findall(rf'\b{escaped}\s*(?::[^=\n]+)?=(?!=)', code)
    if len(types) != 1 or len(writes) > 1:
        return set()
    return _owners(index, types.pop(), method)

def _stack_evidence(index, feedback):
    found = []
    for line in feedback.splitlines():
        match = re.search(r'\bat\s+([\w.$]+)\.([\w$]+)\([^()]+:\d+\)', line)
        if match:
            identities = _owners(index, match[1], match[2])
            if identities:
                # Only the innermost recognized frame is the failure location;
                # later callers are not independently failing functions.
                found.append((identities, feedback, {'kind': 'qualified_stack_frame', 'frame': line.strip()}))
                break
    return found

def diagnose_failure(index, previous):
    """Return one identified function or a public, auditable no-match reason.

    An adapter can supply ``public_failure`` with function_id, requirement_id
    and diagnostic. Its diagnostic must also occur in public_feedback. No
    private checker fields, expected outputs or oracle data enter this API.
    """
    if not previous:
        return _result('no_previous_failure')
    if (previous.get('incomplete') is True
            or previous.get('response_status') == 'incomplete'
            or previous.get('output_status') == 'incomplete'
            or (isinstance(previous.get('response_state'), dict)
                and previous['response_state'].get('complete') is False)):
        return _result('incomplete_model_output')
    code, feedback = previous.get('code', ''), previous.get('feedback', '')
    if not isinstance(code, str) or not isinstance(feedback, str):
        return _result('invalid_public_failure')
    if not code.strip():
        return _result('empty_candidate')
    public = previous.get('public_failure')
    explicit = None
    if public is not None:
        if (not isinstance(public, dict)
                or public.get('function_id') not in set(index['api_function_ids'].values())
                or not isinstance(public.get('requirement_id'), str)
                or not re.fullmatch(r'[A-Za-z0-9_.:-]+', public['requirement_id'])
                or not isinstance(public.get('diagnostic'), str)
                or not public['diagnostic'] or public['diagnostic'] not in feedback):
            return _result('invalid_public_failure')
        explicit = ({public['function_id']}, public['diagnostic'], {'kind': 'public_adapter_failure'})
    evidence = (_compiler_evidence(index, code, feedback) + _import_evidence(index, code, feedback)
                + _stack_evidence(index, feedback))
    if explicit:
        evidence.append(explicit)
    if not evidence:
        return _result('unresolved_function')
    identities = set().union(*(entry[0] for entry in evidence))
    if len(identities) != 1:
        return _result('ambiguous_function', candidate_function_ids=sorted(identities))
    function_id = identities.pop()
    diagnostic = '\n'.join(dict.fromkeys(entry[1] for entry in evidence))
    result = _result('identified', function_id=function_id, diagnostic=diagnostic,
                     evidence=[entry[2] for entry in evidence])
    if explicit:
        result['requirement_id'] = public['requirement_id']
    return result

def response_record(response):
    """Retain evaluator-compatible totals and distinguish visible/reasoning usage."""
    record = base_response_record(response)
    usage = response.usage_metadata
    if usage is not None:
        record['usage'].update({
            'visible_output_tokens': usage.candidates_token_count,
            'thinking_tokens': usage.thoughts_token_count,
            'cached_input_tokens': usage.cached_content_token_count,
            'tool_use_prompt_tokens': usage.tool_use_prompt_token_count,
            'total_tokens': usage.total_token_count,
        })
    return record

def attempts(root, prefix):
    records = []
    for directory in sorted(root.glob(prefix + '*')):
        if not directory.is_dir() or re.fullmatch(re.escape(prefix) + r'\d{3,}', directory.name) is None:
            raise ValueError('Unexpected condition attempt directory')
        records.append({'directory': str(directory), 'files': {
            name: bind(directory / name) for name in (
                'request.json', 'process.json', 'stdout.txt', 'stderr.txt', 'invocation.json',
                *(p.relative_to(directory).as_posix()
                  for p in sorted((directory / 'provider_audit').glob('*.json'))))
            if (directory / name).exists()}})
    return records

def generation_counts(rows, arms):
    return {arm: {status: sum(row.get('status') == status for row in rows if row['arm'] == arm)
                  for status in sorted(GENERATION_STATUSES)} for arm in arms}

def generation_record(response, files):
    return {'schema_version': 1, **solution_state(response),
            'response_sha256': digest(response),
            'provider': {name: files[name] for name in ('request.json', 'process.json')}}

def mark_generation(row, response, number):
    state = solution_state(response)
    row.update(generation_status=state['status'], generation_reason=state['reason'], last_generation_round=number)
    if not state['executable']:
        row['status'] = 'generation_' + state['status']
    return state['executable']

def model_response(result):
    payload = result.get('payload')
    if result.get('status') == 'ok' and isinstance(payload, dict) and isinstance(payload.get('code'), str):
        return payload
    return None

def rounds(directory, exposure=False):
    records = []
    for root in sorted(directory.glob('round_*')):
        if not root.is_dir() or re.fullmatch(r'round_\d{2,}', root.name) is None:
            raise ValueError('Unexpected condition round directory')
        record = {'round': int(root.name.removeprefix('round_')),
                  'providers': attempts(root, 'provider_'), 'executions': attempts(root, 'execution_')}
        if exposure:
            record['exposure'] = bind(root / 'context_exposure.json')
        if (root / 'repair_context.json').exists():
            record['repair_context'] = bind(root / 'repair_context.json')
        if (root / 'generation.json').exists():
            record['generation'] = bind(root / 'generation.json')
        records.append(record)
    return sorted(records, key=lambda record: record['round'])

def selected_response(providers, request):
    """Validate every request, including interrupted attempts; select once only."""
    selected = None
    for attempt in providers:
        files = attempt['files']
        if 'request.json' in files and load(files['request.json']['path']) != request:
            raise ValueError('Saved provider request differs from the frozen public prompt')
        if 'process.json' in files:
            if 'request.json' not in files:
                raise ValueError('Saved provider process lacks its request')
            response = model_response(load(files['process.json']['path']))
            if selected is not None:
                raise ValueError('Saved provider attempt follows an already returned response')
            if response is not None:
                selected = (response, files)
        elif selected is not None:
            raise ValueError('Saved provider attempt follows an already returned response')
    return selected

def verify_generation(item, response, files):
    expected = generation_record(response, files)
    receipt = item.get('generation')
    if not receipt or load(receipt['path']) != expected:
        raise ValueError('Saved generation evidence differs from the selected provider response')
    return expected

def _alias_destination(template, number):
    if template is None:
        return None
    if not isinstance(template, str) or template.count('{batch}') != 1:
        raise ValueError('alias_path_template must contain exactly one {batch} placeholder')
    value = template.replace('{batch}', f'{number:04d}')
    if '{' in value or '}' in value:
        raise ValueError('Only the {batch} placeholder is supported')
    return alias_target(value)

def _integer(value, name, low, high):
    if type(value) is not int or not low <= value <= high:
        raise ValueError(f'{name} must be between {low} and {high}')

def _library_overview(public, max_characters):
    """Bound the cross-batch orientation, while retaining the full catalogue on disk."""
    counts = Counter(row.get('module') or row['file'] for row in public)
    overview = {'module_count': len(counts), 'modules': [], 'omitted_modules': len(counts),
                'api_catalog': [], 'omitted_catalog_entries': len(public),
                'scope': 'Compact cross-batch orientation only; source evidence remains batch-local.'}
    module_budget = max_characters // 3
    for module, count in sorted(counts.items()):
        candidate = overview['modules'] + [{'module': module, 'public_definitions': count}]
        if len(json.dumps(candidate, ensure_ascii=False, indent=2)) > module_budget:
            break
        overview['modules'] = candidate
        overview['omitted_modules'] -= 1
    for row in public:
        entry = {key: row[key] for key in ('id', 'name', 'signature')}
        candidate = {**overview, 'api_catalog': overview['api_catalog'] + [entry],
                     'omitted_catalog_entries': overview['omitted_catalog_entries'] - 1}
        if len(json.dumps(candidate, ensure_ascii=False, indent=2)) <= max_characters:
            overview = candidate
    return overview

def context(rows, number):
    ids = {row['id'] for row in rows}
    selected_errors, used, omitted = [], 0, 0
    for error in errors:
        if error['function_id'] not in ids:
            continue
        size = len(json.dumps(error, ensure_ascii=False))
        if used + size > max_error_characters:
            omitted += 1
        else:
            selected_errors.append(error)
            used += size
    return {**common, 'batch_id': f'batch-{number:04d}',
            'alias_destination': _alias_destination(alias_path_template, number),
            'apis': rows, 'development_errors': selected_errors,
            'coverage': {'matching_definitions': len(definitions), 'selected_definitions': len(rows),
                         'omitted_definitions': len(definitions) - len(rows),
                         'omitted_error_rows': omitted,
                         'source_window_policy': 'Three preceding and up to sixty following lines; not complete function bodies.'}}

def _development_errors(path, definitions, max_characters=12000):
    """Only explicit development logs; never read a held-out bank or its oracles."""
    if path is None:
        return [], None, 0
    path = Path(path).resolve()
    rows, omitted, used = [], 0, 0
    by_name = {}
    for definition in definitions:
        for name in (definition['name'], definition['qualified_name'], definition['id']):
            by_name.setdefault(name, set()).add(definition['id'])
    for number, line in enumerate(path.read_text().splitlines(), 1):
        if not line.strip():
            continue
        record = json.loads(line)
        if not isinstance(record, dict):
            raise ValueError(f'Development log line {number} must be an object')
        metadata = record.get('metadata') or {}
        if not isinstance(metadata, dict):
            raise ValueError('Development log metadata must be an object')
        if any(str(obj.get(key, '')).lower() in ('held_out', 'held-out', 'evaluation', 'test')
               for obj in (record, metadata) for key in ('split', 'phase', 'scope')):
            raise ValueError('Held-out/evaluation failures cannot train development hints')
        if record.get('status') not in ('fail', 'fixed'):
            omitted += 1
            continue
        if not isinstance(record.get('function'), str):
            raise ValueError('Development log function must be text')
        candidates = by_name.get(record['function'], set())
        if len(candidates) != 1:
            omitted += 1  # Ambiguous overloads need a qualified location ID.
            continue
        item = {'id': f'error-{number}', 'function_id': next(iter(candidates)),
                'status': record['status']}
        for key in ('error', 'root_cause', 'code', 'suggested_fix_code'):
            value = record.get(key, '')
            if not isinstance(value, str):
                raise ValueError(f'Development log {key} must be text')
            item[key] = value[:2500]
        size = len(json.dumps(item, ensure_ascii=False))
        if used + size > max_characters:
            omitted += 1
            continue
        used += size
        rows.append(item)
    return rows, bind(path), omitted

def _library_inputs(study, apis=None):
    """Discover the full pinned public surface without importing target code."""
    study, root, attachment = original_checkout(study)
    source = load(study / 'source.json')
    refs = source['configuration_layers']
    if not all(verify_artifact(ref) for ref in refs):
        raise ValueError('Configuration changed since attachment')
    cfg = _engine_config_module().load_config(source['configuration']['path'])
    repository = Path(attachment['repository']).resolve()
    patterns = []
    for pattern in cfg.source_globs:
        absolute = (cfg.root / pattern).resolve()
        if not absolute.is_relative_to(repository):
            raise ValueError('Configured source pattern escapes the pinned repository')
        patterns.append(str(root / absolute.relative_to(repository)))
    tracked = set(_git(root, 'ls-files', '-z').split('\x00'))
    files = sorted({Path(p) for pattern in patterns for p in glob.glob(pattern, recursive=True)
                    if Path(p).is_file()})
    for path in files:
        if path.is_symlink() or not path.resolve().is_relative_to(root):
            raise ValueError('Source symlinks are not allowed in development context')
    files = [p for p in files if p.relative_to(root).as_posix() in tracked
             and '.aideal' not in p.relative_to(root).parts]
    if not files:
        raise ValueError('No tracked source files match the configured patterns')
    engine_path = str(Path(__file__).resolve().parents[1] / 'vendor/aideal_engine/src')
    if engine_path not in sys.path:
        sys.path.insert(0, engine_path)
    from aideal.api_discovery import public_api_details
    # Resolve discovery inside the pinned checkout, not the caller's mutable repo.
    local = replace(cfg, root=root, source_globs=[glob.escape(str(p)) for p in files], test_globs=[])
    definitions, scala_sources = [], {}
    for row in public_api_details(local):
        if row['visibility'] != 'public':
            continue
        row = {**row, 'id': f"{row['file']}:{row['line']}:{row['qualified_name']}"}
        if apis and not {row['id'], row['qualified_name'], row['name']}.intersection(apis):
            continue
        if Path(row['file']).suffix == '.scala':
            if row['file'] not in scala_sources:
                scala_sources[row['file']] = (root / row['file']).read_text()
            # Keep the original id/qualified_name and selection semantics. These
            # additional facts disambiguate receivers for the model only.
            row.update(_scala_receiver_facts(scala_sources[row['file']], row['line'], row['name']))
        definitions.append(row)
    definitions.sort(key=lambda r: (r['file'], r['line'], r['id']))
    if apis:
        known = {r[k] for r in definitions for k in ('id', 'qualified_name', 'name')}
        if set(apis) - known:
            raise ValueError('Requested API not found: ' + ', '.join(sorted(set(apis) - known)))
    if not definitions:
        raise ValueError('No public APIs discovered; configure a language adapter/definition pattern')
    if len({row['id'] for row in definitions}) != len(definitions):
        raise ValueError('Discovery returned duplicate function IDs')
    return study, root, attachment, cfg, definitions, refs

@lru_cache(maxsize=128)
def _scala_package(source):
    """Accept leading, unbraced package declarations; ignore comments/literals."""
    tokens = _scala_tokens(source)
    cursor, packages = 0, []
    while cursor < len(tokens) and tokens[cursor].value == 'package':
        line = tokens[cursor].line
        cursor += 1
        parts = []
        while cursor < len(tokens) and tokens[cursor].line == line and tokens[cursor].value != ';':
            parts.append(tokens[cursor].value)
            cursor += 1
        if (not parts or any(not re.fullmatch(r'[A-Za-z_$][\w$]*', part)
                             for part in parts[::2])
                or len(parts) % 2 != 1 or any(part != '.' for part in parts[1::2])):
            raise ValueError('Unsupported Scala package declaration')
        packages.append(''.join(parts))
        if cursor < len(tokens) and tokens[cursor].value == ';':
            cursor += 1
    if any(token.value == 'package' for token in tokens[cursor:]):
        raise ValueError('Non-leading Scala package declarations require explicit resolution')
    return '.'.join(packages)

def _scala_receiver_facts(source, line, name):
    """Add lexical facts without redefining discovery identity or public scope."""
    facts = dict.fromkeys(('receiver', 'owner_kind', 'owner_path', 'qualified_receiver',
                           'source_qualified_name', 'owner_declaration'))
    try:
        owner = owner_at_line(source, line, name)
        package = _scala_package(source)
    except ValueError as exc:
        return {**facts, 'qualification_status': 'unresolved', 'qualification_reason': str(exc)}
    qualified = '.'.join(filter(None, (package, owner['owner_path'])))
    declaration_line = owner['declaration_line']
    return {**owner, 'qualified_receiver': qualified,
            'source_qualified_name': qualified + '.' + name,
            'owner_declaration': {'line': declaration_line,
                                  'text': source.splitlines()[declaration_line - 1]},
            'qualification_status': 'resolved_lexical',
            'qualification_reason': 'Direct named-owner member; not a type, visibility or dispatch proof.'}

def _semantic_context(cfg, root, attachment):
    """Expose discovery semantics and explicit profile, never model credentials."""
    configured = Path(cfg.raw.get('files', {}).get('project_profile', 'configs/project_profile.yaml'))
    path = (cfg.root / configured).resolve()
    repository = Path(attachment['repository']).resolve()
    if path.is_relative_to(repository):
        path = root / path.relative_to(repository)
    profile, refs = {}, []
    if path.exists():
        if path.is_symlink() or (path.is_relative_to(root) and not path.resolve().is_relative_to(root)):
            raise ValueError('Profile symlinks cannot escape the pinned source tree')
        profile = _engine_config_module().yaml.safe_load(path.read_text()) or {}
        if not isinstance(profile, dict):
            raise ValueError('Project profile must be a mapping')
        refs.append(bind(path))
    config = {'source_globs': cfg.source_globs, 'test_globs': cfg.test_globs,
              'public_def_regex': cfg.public_def_regex, 'exclude_names': cfg.exclude_names,
              'visibility': cfg.visibility, 'surface_filter': cfg.surface_filter,
              'exclude_path_patterns': cfg.raw.get('codebase', {}).get('exclude_path_patterns', []),
              'discovery_scope': 'All discovered public definitions in tracked configured sources; no LLM intent filter.'}
    return {'configuration': config, 'project_profile': profile,
            'profile_status': 'supplied' if profile else 'not_supplied'}, refs

def _source_windows(root, definitions):
    """Capture bounded literal source evidence, keyed by original function ID."""
    refs, file_lines = {}, {}
    for row in definitions:
        path = root / row['file']
        if row['file'] not in file_lines:
            file_lines[row['file']] = path.read_text().splitlines()
            refs[row['file']] = bind(path)
        lines = file_lines[row['file']]
        first, last = max(0, row['line'] - 4), min(len(lines), row['line'] + 60)
        row['source_window'] = {'start_line': first + 1, 'end_line': last,
                                'text': '\n'.join(lines[first:last]),
                                'complete_file': first == 0 and last == len(lines)}
        # Preserve package/import/container declarations needed to place a new
        # module correctly. These are observed lines, not an inferred receiver.
        candidates = [(i + 1, line) for i, line in enumerate(lines[:row['line']])
                      if re.match(r'^\s*(?:(?:public|final|abstract|sealed|case)\s+)*'
                                  r'(?:package|import|from|class|object|trait|impl|mod)\b', line)]
        candidates.sort(key=lambda item: (bool(re.match(r'^\s*(?:import|from)\b', item[1])), item[0]))
        declaration_text = '\n'.join(f'{i}: {line}' for i, line in candidates)
        row['declaration_context'] = {
            'text': declaration_text[:2000], 'source_characters': len(declaration_text),
            'truncated': len(declaration_text) > 2000,
            'meaning': 'Preceding declaration lines; lexical observations, not proof of nesting or receiver identity.'}
    return list(refs.values())

def alias_target(value):
    if value is None:
        return None
    if not isinstance(value, str) or not value or '\\' in value or '\x00' in value:
        raise ValueError('Alias destination must be a relative source filename')
    path = PurePosixPath(value)
    if path.is_absolute() or any(p in ('', '.', '..') for p in value.split('/')) or any(p.startswith('.') for p in path.parts):
        raise ValueError('Alias destination cannot escape the source tree or use hidden paths')
    if path.suffix not in ('.py', '.scala', '.java', '.rs'):
        raise ValueError('Alias destination needs a supported source extension')
    return path.as_posix()

def _finish_proposal(preview, attachment, output, result, readme_ref, attempt):
    """Persist review artifacts from a recorded result; never install or execute them."""
    if proposal_response_error(result):
        raise ValueError('Incomplete, refused or invalid proposal response')
    if not all(verify_artifact(ref) for ref in preview['artifacts']):
        raise ValueError('Source changed during generation; do not install these suggestions')
    original_checkout(preview['study'])
    suggestions = validate_suggestions(json.loads(result['payload']['code']), preview['context'])
    atomic_json(output / 'suggestions.json', suggestions)
    batch_id = preview['context'].get('batch_id')
    aliases = [{**row, 'alias_id': digest(row)[:20], 'source_batch': batch_id} for row in suggestions['aliases']]
    hints = [{**row, 'hint_id': digest(row)[:20], 'source_batch': batch_id} for row in suggestions['hints']]
    artifacts = {}
    if readme_ref:
        if not verify_artifact(readme_ref):
            raise ValueError('Supplied README changed during generation')
        shutil.copyfile(readme_ref['path'], output / 'README.md')
        artifacts['readme'] = bind(output / 'README.md')
    if suggestions['aliases']:
        target = preview['context']['alias_destination']
        code = output / ('alias_source' + Path(target).suffix)
        code.write_text(suggestions['alias_code'])
        interface = output / 'ALIASES.md'
        interface.write_text(suggestions['alias_interface'])
        artifacts['alias'] = {**bind(code), 'target': target}
        artifacts['alias_interface'] = {**bind(interface), 'source_batch': batch_id,
                                        'alias_ids': [row['alias_id'] for row in aliases]}
    if suggestions['hints']:
        path = output / 'error_hints.json'
        atomic_json(path, {'schema_version': 1, 'status': 'unverified',
                          'source': 'development evidence only',
                          'hints': [{**row, 'status': 'unverified'} for row in hints]})
        artifacts['error_hints'] = bind(path)
        # A companion per-function log connects each suggestion to the exact
        # development record; existing error logs and evaluation records are immutable.
        (output / 'function_fix_hints.jsonl').write_text(''.join(
            json.dumps({'function': row['function_id'], 'status': 'suggested_unverified', **row}, ensure_ascii=False) + '\n'
            for row in hints))
    refactors = None
    if suggestions['refactors']:
        path = output / 'refactor_suggestions.json'
        atomic_json(path, {'schema_version': 1, 'status': 'unverified_review_candidates',
                          'preview_sha256': preview['preview_sha256'],
                          'source_batch': preview['context'].get('batch_id'),
                          'refactors': [{**row, 'refactor_id': digest(row)[:20], 'status': 'unverified'}
                                        for row in suggestions['refactors']]})
        refactors = bind(path)
    if not artifacts and not refactors:
        return {'status': 'no_supported_suggestions', 'output': str(output), 'notes': suggestions['notes'], 'llm_calls': 1}
    proposal = {'schema_version': 1, 'baseline_revision': attachment['revision'],
                'study': preview['study'], 'status': 'proposed_unvalidated', 'artifacts': artifacts,
                'preview_sha256': preview['preview_sha256'], 'aliases': aliases, 'notes': suggestions['notes'],
                'model_attempt': bind(attempt / 'process.json'),
                'request': bind(attempt / 'request.json'),
                'scope': preview['context']['coverage'], 'requires_validation': True,
                'source_batch': preview['context'].get('batch_id'), 'refactor_suggestions': refactors}
    if not artifacts:
        proposal['status'] = 'review_candidates_only'
    atomic_json(output / 'proposal.json', proposal)
    return {'status': proposal['status'], 'proposal': str(output / 'proposal.json'),
            'alias_count': len(suggestions['aliases']), 'hint_count': len(suggestions['hints']),
            'refactor_count': len(suggestions['refactors']), 'llm_calls': 1}

def _model_settings(path):
    config = _engine_config_module().yaml.safe_load(Path(path).read_text())
    if not isinstance(config, dict) or not isinstance(config.get('model'), dict):
        raise ValueError('Model configuration needs a model mapping')
    model = config['model']
    _text(model.get('name'), 'model.name')
    command = model.get('command')
    if not isinstance(command, list) or not command or any(not isinstance(c, str) or not c for c in command):
        raise ValueError('model.command must be a nonempty argument list')
    for field in ('max_output_tokens', 'timeout_s'):
        if type(model.get(field)) is not int or model[field] <= 0:
            raise ValueError(f'model.{field} must be a positive integer')
    temperature = model.get('temperature', 0)
    if type(temperature) not in (int, float) or not math.isfinite(temperature) or temperature < 0:
        raise ValueError('model.temperature must be finite and nonnegative')
    return {**model, 'temperature': temperature}

def _text(value, field, empty=False):
    if not isinstance(value, str) or (not empty and not value.strip()):
        raise ValueError(field + ' must be ' + ('text' if empty else 'nonempty text'))
    return value

def matching_fix_hints(bundle, function_id, error):
    """Return only same-function literal matches; hints never become verified here."""
    return [{**hint, 'status': 'unverified'} for hint in bundle.get('hints', [])
            if hint.get('function_id') == function_id and isinstance(hint.get('error_contains'), str)
            and hint['error_contains'] and hint['error_contains'] in error]

def proposal_response_error(result, model=None):
    """Do not install syntactically valid partial/refused provider suggestions."""
    payload = result.get('payload')
    if result.get('status') != 'ok' or not isinstance(payload, dict):
        return 'provider_attempt_failed'
    if not isinstance(payload.get('code'), str) or not payload['code'].strip():
        return 'provider_empty_or_invalid_output'
    status = payload.get('response_status')
    if ((status is not None and status != 'completed') or payload.get('truncated')
            or payload.get('incomplete_reason')):
        return 'provider_incomplete_or_noncompleted'
    if payload.get('refusals') or payload.get('response_kind') in ('refusal', 'empty_model_output'):
        return 'provider_refusal_or_empty_output'
    if model == 'gpt-5.3-codex':
        if status != 'completed':
            return 'provider_completion_status_missing'
        if not isinstance(payload.get('budget'), dict) or payload['budget'].get('state') != 'settled':
            return 'provider_usage_unsettled'
    return None

def validate_suggestions(value, context, *, reserved_names=None):
    """Validate referential/schema integrity, without claiming code correctness."""
    if not isinstance(value, dict):
        raise ValueError('Model suggestions must be a JSON object')
    expected = {'aliases', 'alias_code', 'alias_interface', 'hints', 'notes'}
    if set(value) not in (expected, expected | {'refactors'}):
        raise ValueError('Model response must contain aliases, alias_code, alias_interface, hints, notes and optional refactors')
    value = {**value, 'refactors': value.get('refactors', [])}
    functions = {row['id']: row for row in context['apis']}
    evidence = {row['id']: row for row in context['development_errors']}
    aliases, hints = value['aliases'], value['hints']
    if not isinstance(aliases, list) or len(aliases) > 20 or not isinstance(hints, list) or len(hints) > 100:
        raise ValueError('aliases/hints must be bounded lists')
    for field in ('alias_code', 'alias_interface', 'notes'):
        _text(value[field], field, empty=True)
    names = set()
    original_names = {row['name'] for row in functions.values()} | set(reserved_names or [])
    for alias in aliases:
        if not isinstance(alias, dict) or set(alias) != {'name', 'target_function', 'rationale'}:
            raise ValueError('Invalid alias record')
        name = _text(alias['name'], 'alias.name')
        if not re.fullmatch(r'[A-Za-z_][A-Za-z0-9_]*', name) or name in names or name in original_names:
            raise ValueError('Alias name must be a distinct new identifier')
        names.add(name)
        if _text(alias['target_function'], 'target_function') not in functions:
            raise ValueError('Alias target was not in the model input')
        _text(alias['rationale'], 'alias.rationale')
    if aliases:
        if alias_target(context['alias_destination']) is None:
            raise ValueError('No alias destination was requested')
        _text(value['alias_code'], 'alias_code')
        _text(value['alias_interface'], 'alias_interface')
        if context['alias_destination'].endswith('.py'):
            tree = ast.parse(value['alias_code'])
            defined = {n.name for n in ast.walk(tree) if isinstance(n, (ast.FunctionDef, ast.AsyncFunctionDef))}
            if not names <= defined:
                raise ValueError('Python alias source does not define each proposed name')
    elif value['alias_code'].strip() or value['alias_interface'].strip():
        raise ValueError('Alias source/interface supplied without alias records')
    for hint in hints:
        required = {'function_id', 'evidence_ids', 'error_contains', 'likely_cause',
                    'fix_steps', 'suggested_fix_code', 'validation'}
        if not isinstance(hint, dict) or set(hint) != required:
            raise ValueError('Invalid hint record')
        if _text(hint['function_id'], 'function_id') not in functions:
            raise ValueError('Hint function was not in the model input')
        refs = hint['evidence_ids']
        if not isinstance(refs, list) or not refs or any(not isinstance(r, str) or r not in evidence for r in refs):
            raise ValueError('Hint must cite supplied development evidence')
        if any(evidence[r]['function_id'] != hint['function_id'] for r in refs):
            raise ValueError('Hint evidence belongs to a different function')
        pattern = _text(hint['error_contains'], 'error_contains')
        if any(pattern not in evidence[r]['error'] for r in refs):
            raise ValueError('Hint match text must occur in every cited diagnostic')
        for field in ('likely_cause', 'validation'):
            _text(hint[field], field)
        _text(hint['suggested_fix_code'], 'suggested_fix_code', empty=True)
        if not isinstance(hint['fix_steps'], list) or not hint['fix_steps']:
            raise ValueError('Hint needs concrete fix_steps')
        for step in hint['fix_steps']:
            _text(step, 'fix_steps')
    validate_refactors(value['refactors'], functions)
    return value

@mcp.tool()
def attach_codebase(repository: str, config: str, output: str) -> dict:
    """Create five real branches in a separate local clone; never patch the input checkout."""
    return attach(repository, config, output)

@mcp.tool()
def inspect_study(directory: str) -> dict:
    """Inspect generated preparation records; does not launch evaluation or validate approval."""
    return prepared_study_status(directory)

@mcp.tool()
def operating_instructions() -> str:
    """Read the toolkit's current implementation boundaries and end-to-end instructions."""
    return (Path(__file__).resolve().parents[1] / 'README.md').read_text(encoding='utf-8')

def response_record(response):
    """Keep partial output and usage, and expose provider completion evidence."""
    code = response.text or ''
    record = {'code': code, 'model_version': response.model_version}
    candidates = getattr(response, 'candidates', None)
    candidate = (candidates or [None])[0]
    reason = getattr(candidate, 'finish_reason', None)
    block = getattr(getattr(response, 'prompt_feedback', None), 'block_reason', None)
    record.update(finish_reason=getattr(reason, 'value', reason),
                  finish_message=getattr(candidate, 'finish_message', None),
                  prompt_block_reason=getattr(block, 'value', block),
                  completion_metadata_expected=hasattr(response, 'candidates'))
    record['truncated'] = record['finish_reason'] == 'MAX_TOKENS'
    usage = response.usage_metadata
    if usage is not None:
        record['usage'] = {
            'input_tokens': usage.prompt_token_count,
            'output_tokens': (usage.candidates_token_count or 0) + (usage.thoughts_token_count or 0),
        }
    return classify_record(record)

def _path(value, label):
    if not isinstance(value, str) or not value.strip() or not Path(value).is_absolute():
        raise NativeBridgeError(label + ' must be an explicit absolute path')
    path = Path(value)
    if any(p.is_symlink() for p in (path, *path.parents)):
        raise NativeBridgeError(label + ' must not traverse a symlink')
    return path.resolve()

def active_controller_hashes():
    root = Path(__file__).resolve().parent.parent
    return {name: hashlib.sha256((root / name).read_bytes()).hexdigest() for name in CONTROLLER_FILES}

def guarded_native_contract(spec):
    """Read-only policy/implementation validation for preparation and session pins."""
    if spec.provider != PROVIDER or spec.model != MODEL:
        raise NativeBridgeError('Native audited provider and gpt-5.3-codex must be explicitly selected')
    config = getattr(spec, 'bridge', None)
    if not isinstance(config, dict) or set(config) != FIELDS:
        raise NativeBridgeError('Native bridge requires exactly its documented configuration fields')
    if config['policy'] != 'study-v2':
        raise NativeBridgeError('Native bridge requires a new explicit study-v2 budget')
    stage = config['stage']
    if not isinstance(stage, str) or not re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9._-]{0,95}', stage):
        raise NativeBridgeError('Stage must be a stable nonempty label')
    cap = config['max_output_tokens']
    if type(cap) is not int or not 0 < cap <= 128000:
        raise NativeBridgeError('max_output_tokens must be an integer from 1 to 128000')
    evidence = _path(config['evidence_dir'], 'evidence_dir')
    ledger_path = _path(config['budget_ledger'], 'budget_ledger')
    if ledger_path == evidence or evidence in ledger_path.parents:
        raise NativeBridgeError('Keep the shared mutable ledger outside the stage evidence directory')
    ledger = BudgetLedger(ledger_path, config['max_cost_usd'], policy=config['policy'], study_id=config['study_id'])
    actual = active_controller_hashes()
    if config['controller_sha256'] != actual:
        raise NativeBridgeError('Pinned native bridge implementation differs from the active installation')
    result = {'schema_version': 1, 'provider': PROVIDER, 'model': MODEL,
              'stage': stage, 'budget_ledger': str(ledger_path), 'budget_identity': ledger.identity,
              'max_output_tokens': cap, 'evidence_dir': str(evidence), 'controller_sha256': actual}
    return {**result, 'identity_sha256': digest(result)}

def _failure(exc):
    """Never persist raw SDK error bodies, URLs, headers, or exception messages."""
    code = getattr(exc, 'code', None)
    request_id = getattr(exc, 'request_id', None)
    status = getattr(exc, 'status_code', None)
    return {'type': type(exc).__name__,
            'status_code': status if type(status) is int and 100 <= status <= 599 else None,
            'code': code if isinstance(code, str) and re.fullmatch(r'[a-z_]{1,64}', code) else None,
            'request_id': request_id if isinstance(request_id, str) and re.fullmatch(r'req_[a-zA-Z0-9]{1,128}', request_id) else None}

class BudgetLedger:
    def __init__(self, path, max_cost_usd='5', *, policy='legacy-v1', study_id=None):
        self.path = Path(path).expanduser().resolve()
        if policy not in ('legacy-v1', 'study-v2'):
            raise BudgetError('Unknown explicit budget policy')
        if policy == 'legacy-v1' and study_id is not None:
            raise BudgetError('Legacy ledgers do not accept a study identity')
        if policy == 'study-v2':
            import re
            if not isinstance(study_id, str) or not re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9._:-]{0,127}', study_id):
                raise BudgetError('Study policy requires a stable nonempty study_id')
        ceiling = 100 if policy == 'study-v2' else 5
        try:
            cap = Decimal(str(max_cost_usd)) * 1_000_000_000
            if not cap.is_finite() or cap <= 0 or cap > ceiling * 1_000_000_000 or cap != cap.to_integral_value():
                raise ValueError
            cap = int(cap)
        except (InvalidOperation, ValueError):
            raise BudgetError(f'Budget must be positive, at most ${ceiling}, and precise to nanodollars') from None
        self.identity = {'schema_version': 1, 'model': MODEL, 'max_cost_nanousd': cap,
                         'prices_nanousd_per_token': PRICES, 'framing_tokens': FRAMING_TOKENS}
        if policy == 'study-v2':
            self.identity.update(schema_version=2, policy=policy, study_id=study_id)

    def _save(self, data):
        fd, name = tempfile.mkstemp(prefix=self.path.name + '.', suffix='.tmp', dir=self.path.parent)
        try:
            with os.fdopen(fd, 'w') as output:
                json.dump(data, output, indent=2, allow_nan=False)
                output.write('\n')
                output.flush()
                os.fsync(output.fileno())
            os.replace(name, self.path)
            directory = os.open(self.path.parent, os.O_RDONLY)
            try:
                os.fsync(directory)
            finally:
                os.close(directory)
        finally:
            if os.path.exists(name):
                os.unlink(name)

    def _validate(self, data, marker):
        if not isinstance(data, dict):
            raise BudgetError('Invalid ledger document; refusing to spend')
        if any(data.get(key) != value for key, value in self.identity.items()):
            raise BudgetError('Ledger model, prices, cap or schema changed; automatic reset is forbidden')
        if not marker or data.get('ledger_id') != marker or not isinstance(data.get('records'), list):
            raise BudgetError('Ledger identity or records are invalid')
        seen = set()
        for row in data['records']:
            if (not isinstance(row, dict) or not isinstance(row.get('id'), str)
                    or row['id'] in seen or row.get('state') not in ('reserved', 'uncertain', 'settled')
                    or not _integer(row.get('reserved_nanousd'))
                    or not _integer(row.get('charged_nanousd'))
                    or not _integer(row.get('input_upper_tokens'))
                    or not _integer(row.get('max_output_tokens'))):
                raise BudgetError('Invalid ledger record; refusing to spend')
            expected = row['input_upper_tokens'] * PRICES['input'] + row['max_output_tokens'] * PRICES['output']
            if row['reserved_nanousd'] != expected:
                raise BudgetError('Ledger reservation is inconsistent')
            if row['state'] != 'settled' and row['charged_nanousd'] != expected:
                raise BudgetError('Unresolved reservation must remain fully charged')
            if row['state'] == 'settled' and row['charged_nanousd'] != self._actual(row.get('usage')):
                raise BudgetError('Settled ledger usage is inconsistent')
            seen.add(row['id'])

    @contextmanager
    def _locked(self):
        self.path.parent.mkdir(parents=True, exist_ok=True)
        fd = os.open(str(self.path) + '.lock', os.O_RDWR | os.O_CREAT, 0o600)
        with os.fdopen(fd, 'r+') as lock:
            fcntl.flock(lock, fcntl.LOCK_EX)
            marker = lock.read().strip()
            if self.path.exists():
                try:
                    data = json.loads(self.path.read_text())
                except (ValueError, OSError):
                    raise BudgetError('Cannot read budget ledger; refusing to reset it') from None
            else:
                if marker:
                    raise BudgetError('Budget ledger was removed; automatic recreation is forbidden')
                marker = uuid.uuid4().hex
                data = {**self.identity, 'ledger_id': marker, 'records': []}
                self._save(data)
                lock.write(marker)
                lock.flush()
                os.fsync(lock.fileno())
            self._validate(data, marker)
            yield data
            self._save(data)

    def reserve(self, system, prompt, max_output_tokens, request_sha256, settings_sha256):
        if not isinstance(system, str) or not isinstance(prompt, str):
            raise BudgetError('Only text requests can be reserved')
        if type(max_output_tokens) is not int or max_output_tokens <= 0:
            raise BudgetError('Output limit must be a positive integer')
        if any(not isinstance(value, str) or len(value) != 64
               or any(char not in '0123456789abcdef' for char in value)
               for value in (request_sha256, settings_sha256)):
            raise BudgetError('Request and settings hashes are required')
        bound = len(system.encode('utf-8')) + len(prompt.encode('utf-8')) + FRAMING_TOKENS
        amount = bound * PRICES['input'] + max_output_tokens * PRICES['output']
        with self._locked() as data:
            used = sum(row['charged_nanousd'] for row in data['records'])
            if data.get('blocked_reason') or used + amount > self.identity['max_cost_nanousd']:
                raise BudgetError('Shared budget cannot cover this request; no provider call permitted')
            row = {'id': uuid.uuid4().hex, 'state': 'reserved', 'created_at': _now(),
                   'request_sha256': request_sha256, 'settings_sha256': settings_sha256,
                   'input_upper_tokens': bound, 'max_output_tokens': max_output_tokens,
                   'reserved_nanousd': amount, 'charged_nanousd': amount}
            data['records'].append(row)
        return row['id']

    @staticmethod
    def _actual(usage):
        if not isinstance(usage, dict):
            return None
        incoming, cached, outgoing = (usage.get(key) for key in
                                      ('input_tokens', 'cached_input_tokens', 'output_tokens'))
        if not all(_integer(value) for value in (incoming, cached, outgoing)) or cached > incoming:
            return None
        return (incoming - cached) * PRICES['input'] + cached * PRICES['cached_input'] + outgoing * PRICES['output']

    def finish(self, reservation_id, *, usage=None, response_id=None, status=None, failure=None):
        """Only complete, final usage releases a reservation; uncertain calls stay charged."""
        violation = False
        with self._locked() as data:
            row = next((row for row in data['records'] if row['id'] == reservation_id), None)
            if row is None or row['state'] != 'reserved':
                raise BudgetError('Reservation is missing or already finalized')
            row.update(finished_at=_now(), response_id=response_id, response_status=status)
            amount = self._actual(usage) if status in ('completed', 'incomplete', 'failed', 'cancelled') else None
            if amount is None:
                row.update(state='uncertain', failure=failure or {'type': 'MissingFinalUsage'})
            else:
                row.update(state='settled', charged_nanousd=amount, usage=usage)
                violation = (amount > row['reserved_nanousd'] or
                             usage['input_tokens'] > row['input_upper_tokens'] or
                             usage['output_tokens'] > row['max_output_tokens'])
                if violation:
                    data['blocked_reason'] = 'Provider usage exceeded the conservative reservation'
            receipt = {'reservation_id': row['id'], 'state': row['state'],
                       'reserved_nanousd': row['reserved_nanousd'],
                       'charged_nanousd': row['charged_nanousd'],
                       'total_committed_nanousd': sum(item['charged_nanousd'] for item in data['records']),
                       'max_cost_nanousd': self.identity['max_cost_nanousd']}
        if violation:
            raise BudgetError('Provider usage exceeded reservation; ledger is blocked for review')
        return receipt

def __init__(self, path, max_cost_usd='5', *, policy='legacy-v1', study_id=None):
    self.path = Path(path).expanduser().resolve()
    if policy not in ('legacy-v1', 'study-v2'):
        raise BudgetError('Unknown explicit budget policy')
    if policy == 'legacy-v1' and study_id is not None:
        raise BudgetError('Legacy ledgers do not accept a study identity')
    if policy == 'study-v2':
        import re
        if not isinstance(study_id, str) or not re.fullmatch(r'[A-Za-z0-9][A-Za-z0-9._:-]{0,127}', study_id):
            raise BudgetError('Study policy requires a stable nonempty study_id')
    ceiling = 100 if policy == 'study-v2' else 5
    try:
        cap = Decimal(str(max_cost_usd)) * 1_000_000_000
        if not cap.is_finite() or cap <= 0 or cap > ceiling * 1_000_000_000 or cap != cap.to_integral_value():
            raise ValueError
        cap = int(cap)
    except (InvalidOperation, ValueError):
        raise BudgetError(f'Budget must be positive, at most ${ceiling}, and precise to nanodollars') from None
    self.identity = {'schema_version': 1, 'model': MODEL, 'max_cost_nanousd': cap,
                     'prices_nanousd_per_token': PRICES, 'framing_tokens': FRAMING_TOKENS}
    if policy == 'study-v2':
        self.identity.update(schema_version=2, policy=policy, study_id=study_id)

@staticmethod
def _actual(usage):
    if not isinstance(usage, dict):
        return None
    incoming, cached, outgoing = (usage.get(key) for key in
                                  ('input_tokens', 'cached_input_tokens', 'output_tokens'))
    if not all(_integer(value) for value in (incoming, cached, outgoing)) or cached > incoming:
        return None
    return (incoming - cached) * PRICES['input'] + cached * PRICES['cached_input'] + outgoing * PRICES['output']

@contextmanager
def _locked(self):
    self.path.parent.mkdir(parents=True, exist_ok=True)
    fd = os.open(str(self.path) + '.lock', os.O_RDWR | os.O_CREAT, 0o600)
    with os.fdopen(fd, 'r+') as lock:
        fcntl.flock(lock, fcntl.LOCK_EX)
        marker = lock.read().strip()
        if self.path.exists():
            try:
                data = json.loads(self.path.read_text())
            except (ValueError, OSError):
                raise BudgetError('Cannot read budget ledger; refusing to reset it') from None
        else:
            if marker:
                raise BudgetError('Budget ledger was removed; automatic recreation is forbidden')
            marker = uuid.uuid4().hex
            data = {**self.identity, 'ledger_id': marker, 'records': []}
            self._save(data)
            lock.write(marker)
            lock.flush()
            os.fsync(lock.fileno())
        self._validate(data, marker)
        yield data
        self._save(data)

def _validate(self, data, marker):
    if not isinstance(data, dict):
        raise BudgetError('Invalid ledger document; refusing to spend')
    if any(data.get(key) != value for key, value in self.identity.items()):
        raise BudgetError('Ledger model, prices, cap or schema changed; automatic reset is forbidden')
    if not marker or data.get('ledger_id') != marker or not isinstance(data.get('records'), list):
        raise BudgetError('Ledger identity or records are invalid')
    seen = set()
    for row in data['records']:
        if (not isinstance(row, dict) or not isinstance(row.get('id'), str)
                or row['id'] in seen or row.get('state') not in ('reserved', 'uncertain', 'settled')
                or not _integer(row.get('reserved_nanousd'))
                or not _integer(row.get('charged_nanousd'))
                or not _integer(row.get('input_upper_tokens'))
                or not _integer(row.get('max_output_tokens'))):
            raise BudgetError('Invalid ledger record; refusing to spend')
        expected = row['input_upper_tokens'] * PRICES['input'] + row['max_output_tokens'] * PRICES['output']
        if row['reserved_nanousd'] != expected:
            raise BudgetError('Ledger reservation is inconsistent')
        if row['state'] != 'settled' and row['charged_nanousd'] != expected:
            raise BudgetError('Unresolved reservation must remain fully charged')
        if row['state'] == 'settled' and row['charged_nanousd'] != self._actual(row.get('usage')):
            raise BudgetError('Settled ledger usage is inconsistent')
        seen.add(row['id'])

def digest(value):
    return hashlib.sha256(json.dumps(value, sort_keys=True, separators=(',', ':'),
                                    allow_nan=False).encode()).hexdigest()

def binding(path):
    path = Path(path).resolve()
    return {'path': str(path), 'sha256': digest(path.read_bytes())}

def development_diagnostics(path, ids):
    if path is None:
        return {}, []
    path = Path(path).resolve()
    grouped = {key: [] for key in ids}
    for line in path.read_text().splitlines():
        if not line.strip():
            continue
        row = json.loads(line)
        metadata = row.get('metadata') or {}
        if not isinstance(metadata, dict):
            raise ValueError('Diagnostic metadata must be an object')
        if row.get('split') != 'development' or row.get('function_id') not in grouped:
            raise ValueError('Diagnostics require split=development and exact manifest function_id')
        if any(str(obj.get(k, '')).lower() in ('held_out', 'held-out', 'evaluation', 'test')
               for obj in (row, metadata) for k in ('split', 'phase', 'scope')):
            raise ValueError('Held-out diagnostics are forbidden')
        allowed = {k: row[k] for k in ('function_id', 'split', 'error', 'code', 'root_cause') if k in row}
        if any(not isinstance(v, str) for v in allowed.values()):
            raise ValueError('Diagnostic fields must be text')
        grouped[row['function_id']].append(allowed)
    return grouped, [binding(path)]

def digest(value):
    raw = value if isinstance(value, bytes) else json.dumps(value, sort_keys=True, ensure_ascii=False).encode()
    return hashlib.sha256(raw).hexdigest()

def engine_imports():
    directory = Path(__file__).resolve().parents[1] / 'vendor/aideal_engine/src'
    if str(directory) not in sys.path:
        sys.path.insert(0, str(directory))
    import aideal.readme_generation as generation
    if Path(generation.__file__).resolve() != directory / 'aideal/readme_generation.py':
        raise ValueError('A different native engine is already imported')
    return generation

def repository_files(repository, revision, cfg):
    def git(*args):
        return subprocess.check_output(['git', '-c', 'core.fsmonitor=false', '-C', str(repository), *args])
    if git('rev-parse', 'HEAD').decode().strip() != revision:
        raise ValueError('Repository HEAD differs from the pinned manifest revision')
    tracked = set(git('ls-tree', '-r', '--name-only', '-z', revision).decode().split('\0'))
    groups = []
    for patterns in (cfg.source_globs, cfg.test_globs):
        selected = set()
        for pattern in patterns:
            for name in glob.glob(str(cfg.root / pattern), recursive=True):
                path = Path(name)
                if not path.is_file():
                    continue
                if path.is_symlink() or not path.resolve().is_relative_to(repository):
                    raise ValueError('Source/test input escapes pinned repository')
                rel = path.resolve().relative_to(repository).as_posix()
                if rel not in tracked:
                    raise ValueError('Untracked source/test input: ' + rel)
                if path.read_bytes() != git('show', revision + ':' + rel):
                    raise ValueError('Source/test bytes differ from pinned revision: ' + rel)
                selected.add(path.resolve())
        groups.append(sorted(selected))
    if not groups[0]:
        raise ValueError('No pinned source files selected')
    return groups

def validate_definitions(manifest, discovered, repository):
    seen = set()
    rows = {}
    for entry in manifest['entries']:
        if not all(isinstance(entry.get(k), str) and entry[k].strip() for k in ('id', 'heading')):
            raise ValueError('Entry id and heading must be nonempty strings')
        defs = entry.get('definitions')
        if not isinstance(defs, list) or not defs:
            raise ValueError('Each entry needs explicit definition descriptors')
        matched = []
        for definition in defs:
            if not all(isinstance(definition.get(k), str) and definition[k] for k in ('path', 'name', 'receiver', 'signature')):
                raise ValueError('Definition needs path, name, receiver and exact signature')
            path = PurePosixPath(definition['path'])
            if path.is_absolute() or '..' in path.parts or type(definition.get('line')) is not int:
                raise ValueError('Invalid definition path/line')
            matches = [d for d in discovered if d['visibility'] == 'public' and
                       (d['file'], d['line'], d['name'], d['signature']) ==
                       (str(path), definition['line'], definition['name'], definition['signature'])]
            if len(matches) != 1:
                raise ValueError('Unknown/ambiguous exact definition: ' + entry['id'])
            key = (str(path), definition['line'])
            if key in seen:
                raise ValueError('Definition assigned to multiple entries')
            seen.add(key)
            row = matches[0]
            if path.suffix == '.scala':
                from .scala_owners import owner_at_line
                owner = owner_at_line((repository / path).read_text(), definition['line'], definition['name'])
                if (definition['receiver'], definition.get('owner_kind')) != (owner['receiver'], owner['owner_kind']):
                    raise ValueError('Receiver/kind disagrees with enclosing Scala declaration')
                if definition.get('owner_path', owner['owner_path']) != owner['owner_path']:
                    raise ValueError('Nested owner path disagrees with the declaration')
                qualified = definition.get('qualified_receiver')
                if qualified and not (qualified == owner['owner_path'] or qualified.endswith('.' + owner['owner_path'])):
                    raise ValueError('Qualified receiver disagrees with lexical owner path')
                row = {**row, 'lexical_owner_path': owner['owner_path']}
            elif row.get('owner'):
                if not definition['receiver'].endswith(row['owner']):
                    raise ValueError('Receiver disagrees with discovered owner')
            else:
                receiver = definition['receiver'].split('.')[-1]
                text = (repository / path).read_text()
                if not re.search(r'\b(?:class|object|trait|interface|struct|enum|impl)\s+' + re.escape(receiver) + r'\b', text):
                    raise ValueError('Declared receiver not found in definition file')
            matched.append({**row, **{k: definition[k] for k in ('receiver', 'owner_kind', 'qualified_receiver') if k in definition}})
        if len({(d['file'], d['receiver'], d.get('owner_kind'), d.get('lexical_owner_path'), d['name']) for d in matched}) != 1:
            raise ValueError('A family cannot merge different receivers or method names')
        receiver, name = matched[0]['receiver'], matched[0]['name']
        if entry['id'] == name or '.' not in entry['id']:
            raise ValueError('Bare-name identities are not accepted')
        rows[entry['id']] = matched
    return rows

def _provider_request(request, contract):
    return {'model': contract['model'], 'system': request['system'], 'prompt': request['prompt'],
            'max_output_tokens': contract['max_output_tokens'], 'temperature': 0,
            'native_context': {'stage': contract['stage'], 'contract_sha256': contract['identity_sha256']}}

def _read(path):
    path = Path(path)
    if any(p.is_symlink() for p in (path, *path.parents)) or not path.is_file():
        raise ValueError('Missing or redirected provider evidence: ' + str(path))
    data = path.read_bytes()
    return json.loads(data), hashlib.sha256(data).hexdigest()

def _without_timing(record):
    """Timing is bound by receipt hashes; legacy receipts may lack all three fields."""
    if any(key in record for key in TIMING):
        start, end = (datetime.fromisoformat(record[key]) for key in TIMING[:2])
        seconds = record['seconds']
        if (start.tzinfo is None or end.tzinfo is None
                or type(seconds) not in (int, float) or not math.isfinite(seconds) or seconds < 0):
            raise ValueError('Invalid provider receipt timing')
    return {key: value for key, value in record.items() if key not in TIMING}

def invoke_recorded(invoke, spec, system, prompt, contract):
    """Invoke native text once, then require one matching newly saved receipt.

    The bridge owns unique call directories. Concurrent unrelated calls are
    ignored; multiple identical new requests fail closed instead of guessing.
    """
    root = Path(contract['evidence_dir'])
    previous = set(root.glob('call-*'))
    text = invoke(spec, system, prompt)
    request = {'system': system, 'prompt': prompt}
    expected = _provider_request(request, contract)
    matches = []
    for directory in set(root.glob('call-*')) - previous:
        if (directory / 'request.json').is_file():
            saved, _ = _read(directory / 'request.json')
            if saved == expected:
                matches.append(directory)
    if len(matches) != 1:
        raise ValueError('Native result has no unique newly saved provider receipt')
    return {'text': text, 'provider_evidence': receipt_binding(matches[0], text, request, contract)}

def receipt_binding(call_dir, text, request, contract):
    """Validate cross-file identities and bind every original receipt byte."""
    root = Path(contract['evidence_dir'])
    call_dir = Path(call_dir)
    if call_dir.parent != root or not call_dir.name.startswith('call-'):
        raise ValueError('Provider receipt is outside its bound stage')
    stage, stage_hash = _read(root / 'contract.json')
    records, hashes = {}, {}
    for name in FILES:
        records[name], hashes[name] = _read(call_dir / name)
    if stage != contract or records['contract.json'] != contract:
        raise ValueError('Provider evidence contract changed')
    expected = _provider_request(request, contract)
    result, settings = records['result.json'], records['settings.json']
    request_hash, settings_hash = digest(expected), digest(settings)
    if records['request.json'] != expected or result.get('request_sha256') != request_hash:
        raise ValueError('Provider evidence request changed')
    if (result.get('adapter_settings') != settings or result.get('adapter_settings_sha256') != settings_hash
            or settings.get('instructions_sha256') != digest(request['system'])
            or settings.get('input_sha256') != digest(request['prompt'])
            or settings.get('budget_policy_identity') != contract['budget_identity']
            or settings.get('budget_ledger') != contract['budget_ledger']):
        raise ValueError('Provider evidence settings changed')
    response = {key: value for key, value in _without_timing(result).items()
                if key not in ('adapter_settings', 'adapter_settings_sha256', 'request_sha256', 'budget')}
    if records['response.json'] != response or _without_timing(records['outcome.json']) != {
            'status': 'completed', 'request_sha256': request_hash, 'result_sha256': digest(result)}:
        raise ValueError('Provider outcome or response differs from its result')
    if (result.get('code') != text or not isinstance(text, str) or not text.strip()
            or result.get('response_status') != 'completed' or result.get('response_kind') != 'solution'
            or result.get('refusals') or result.get('truncated') or result['budget'].get('state') != 'settled'):
        raise ValueError('Saved phase text differs from complete provider evidence')
    if records['reservation.json'] != {'reservation_id': result['budget']['reservation_id'],
            'request_sha256': request_hash, 'settings_sha256': settings_hash}:
        raise ValueError('Provider reservation evidence changed')
    return {'schema_version': 1, 'call_directory': str(call_dir), 'file_sha256': hashes,
            'stage_contract_sha256': stage_hash, 'ledger': _ledger_binding(contract, result)}

def verify_provider_evidence(binding, text, request, contract):
    if not isinstance(binding, dict) or receipt_binding(binding['call_directory'], text, request, contract) != binding:
        raise ValueError('Saved provider receipt binding changed')

def load_verified(directory):
    """Fail before any provider call if input, output or provider policy changed."""
    session = json.loads((directory / 'session.json').read_text())
    if session['identity_sha256'] != digest({k: v for k, v in session.items() if k != 'identity_sha256'}):
        raise ValueError('Prepared session identity changed')
    if digest(session['requests']) != session['requests_sha256']:
        raise ValueError('Prepared requests changed')
    if digest((directory / 'base.md').read_bytes()) != session['base_sha256']:
        raise ValueError('Immutable base snapshot changed')
    for item in session['inputs']:
        path = Path(item['path'])
        if not path.is_file() or digest(path.read_bytes()) != item['sha256']:
            raise ValueError('Session input changed: ' + str(path))
    manifest = session['manifest']
    head = subprocess.check_output(['git', '-C', manifest['repository'], 'rev-parse', 'HEAD']).decode().strip()
    if head != manifest['revision']:
        raise ValueError('Pinned repository HEAD changed')
    cfg = _engine_config_module().load_config(session['config_path'])
    if cfg.raw != session['effective_config']:
        raise ValueError('Effective layered configuration changed')
    from .native_provider_bridge import guarded_native_contract
    specs = {role: cfg.model_for_role(role) for role in session['provider_contracts']}
    for role, spec in specs.items():
        if guarded_native_contract(spec) != session['provider_contracts'][role]:
            raise ValueError('Guarded native provider contract changed')
    for index, request in enumerate(session['requests']):
        entry = directory / f'entry_{index:04d}'
        if json.loads((entry / 'prepared.json').read_text()) != request:
            raise ValueError('Prepared entry changed')
        for name in request['phases']:
            state_path = entry / (name + '.state.json')
            if not state_path.exists():
                continue
            state = json.loads(state_path.read_text())
            if state.get('status') != 'complete':
                raise ValueError('Prior incomplete/failed invocation requires explicit reconciliation')
            saved = json.loads((entry / (name + '.request.json')).read_text())
            if digest(saved) != state.get('request_sha256') or digest(state.get('text')) != state.get('text_sha256'):
                raise ValueError('Saved phase evidence changed')
            contract = session['provider_contracts'][request['phase_roles'][name]]
            verify_provider_evidence(state.get('provider_evidence'), state['text'], saved, contract)
        candidate = entry / 'candidate.md'
        final_name = 'entry' if session['mode'] == 'full' else 'rewrite'
        final_state = entry / (final_name + '.state.json')
        if candidate.exists():
            if not final_state.exists() or candidate.read_bytes() != candidate_bytes(json.loads(final_state.read_text())['text'], request['heading']):
                raise ValueError('Saved candidate changed')
    return session, specs

def run_readme_session(directory, max_entries=None):
    """Generate candidates only. There is no execution-based acceptance claim.

    Existing complete phases resume by exact hashes. New refresh entries call
    fresh deep-dive then one rewrite. No legacy journals/caches are consulted.
    """
    directory = Path(directory).resolve()
    if max_entries is not None and (type(max_entries) is not int or max_entries < 1):
        raise ValueError('max_entries must be positive')
    with session_lock(directory):
        session, specs = load_verified(directory)
        engine_imports()
        from aideal.llm import invoke_text
        candidates = {}
        for index, prepared in enumerate(session['requests']):
            if max_entries is not None and index >= max_entries:
                break
            root = directory / f'entry_{index:04d}'
            def call_for(name):
                role = prepared['phase_roles'][name]
                return lambda system, prompt: invoke_recorded(invoke_text, specs[role], system, prompt,
                                                              session['provider_contracts'][role])
            def contract_for(name):
                return session['provider_contracts'][prepared['phase_roles'][name]]
            if session['mode'] == 'refresh':
                report = phase(root, 'deep_dive', prepared['phases']['deep_dive'], call_for('deep_dive'), contract_for('deep_dive'))
                load_verified(directory)  # Recheck bindings after any paid phase.
                template = prepared['phases']['rewrite']
                request = {k: v.replace(REPORT_MARKER, report) for k, v in template.items()}
                # The exact rendered request carries the input report identity.
                request['deep_dive_sha256'] = digest(report)
                text = phase(root, 'rewrite', request, call_for('rewrite'), contract_for('rewrite'))
            else:
                text = phase(root, 'entry', prepared['phases']['entry'], call_for('entry'), contract_for('entry'))
            load_verified(directory)
            candidate = candidate_bytes(text, prepared['heading'])
            path = root / 'candidate.md'
            if path.exists() and path.read_bytes() != candidate:
                raise ValueError('Saved candidate changed')
            atomic_bytes(path, candidate)
            candidates[prepared['id']] = text
        if len(candidates) != len(session['requests']):
            return {'status': 'partial_candidates', 'completed_entries': len(candidates),
                    'total_entries': len(session['requests']), 'output': None}
        base = (directory / 'base.md').read_bytes()
        output = compose(base, session['manifest']['entries'], candidates)
        path = directory / 'README.md'
        if path.exists() and path.read_bytes() != output:
            raise ValueError('Existing composed output changed')
        atomic_bytes(path, output)
        result = {'status': 'authored_not_execution_validated', 'identity_sha256': session['identity_sha256'],
                  'output': str(path), 'output_sha256': digest(output), 'base_sha256': session['base_sha256'],
                  'candidate_sha256': {key: digest(candidate_bytes(text, next(e['heading'] for e in session['manifest']['entries'] if e['id'] == key)))
                                       for key, text in candidates.items()},
                  'completed_entries': len(candidates), 'cache_policy': session['cache_policy'],
                  'validation_status': 'not_executed', 'legacy_deep_dive_reused': False}
        completion = directory / 'completion.json'
        if completion.exists() and json.loads(completion.read_text()) != result:
            raise ValueError('Completion receipt changed')
        atomic_json(completion, result)
        return result

def call_for(name):
    role = prepared['phase_roles'][name]
    return lambda system, prompt: invoke_recorded(invoke_text, specs[role], system, prompt,
                                                  session['provider_contracts'][role])

@contextmanager
def session_lock(directory):
    with (directory / '.session.lock').open('a') as stream:
        fcntl.flock(stream, fcntl.LOCK_EX | fcntl.LOCK_NB)
        yield

def candidate_bytes(text, heading):
    if not isinstance(text, str) or not text.strip() or 'TODO' in text:
        raise ValueError('Incomplete generated entry')
    data = text.strip().encode('utf-8') + b'\n\n'
    marks = headings(data)
    if marks != [{'start_byte': 0, 'heading': heading}]:
        raise ValueError('Candidate must contain exactly the intended API entry and no other top-level section')
    return data

def compose(data, entries, candidates):
    ordered = validate_spans(data, entries)
    if set(candidates) - {e['id'] for e in entries}:
        raise ValueError('Unknown candidate identity')
    chunks, cursor = [], 0
    for entry in ordered:
        start, end = entry['span']['start_byte'], entry['span']['end_byte']
        chunks.append(data[cursor:start])
        value = candidates.get(entry['id'])
        chunks.append(candidate_bytes(value, entry['heading']) if value is not None else data[start:end])
        cursor = end
    chunks.append(data[cursor:])
    return b''.join(chunks)

def headings(data):
    """Return real top-level heading byte offsets, ignoring fenced examples."""
    if not isinstance(data, bytes):
        raise ValueError('Catalog must be UTF-8 bytes')
    data.decode('utf-8')
    found, fence, offset = [], None, 0
    for line in data.splitlines(keepends=True):
        match = FENCE.match(line)
        if fence:
            if match and match[1][:1] == fence[:1] and len(match[1]) >= len(fence) and not match[2].strip():
                fence = None
        elif match:
            fence = match[1]
        elif HEADING.match(line):
            api = API.match(line)
            found.append({'start_byte': offset, 'heading': api[1].decode() if api else None})
        offset += len(line)
    if fence:
        raise ValueError('Unclosed Markdown code fence')
    return found

def validate_spans(data, entries):
    actual = {row['heading']: row for row in inspect_sections(data)}
    names = [e['heading'] for e in entries]
    ids = [e['id'] for e in entries]
    if len(set(names)) != len(names) or len(set(ids)) != len(ids):
        raise ValueError('Duplicate heading or target identity')
    if set(names) != set(actual):
        raise ValueError('Manifest must map every base API heading exactly once; reconcile the scope first')
    for entry in entries:
        span, section = entry['span'], actual[entry['heading']]
        start, end = span['start_byte'], span['end_byte']
        if type(start) is not int or type(end) is not int or start != section['start_byte'] or not start < end <= section['end_byte']:
            raise ValueError('Invalid or overlapping entry span: ' + entry['id'])
        if end != len(data) and data[end - 1:end] != b'\n':
            raise ValueError('Entry span must end on a line boundary')
        if len(headings(data[start:end])) != 1:
            raise ValueError('Entry span contains another top-level section')
    return sorted(entries, key=lambda e: e['span']['start_byte'])

def _blocks(text):
    """Markdown paragraphs, preserving each fenced code block as an atomic unit."""
    blocks, current, fence = [], [], None
    for line in text.splitlines(keepends=True):
        marker = re.match(r'^\s*(`{3,}|~{3,})', line)
        if marker:
            if fence is None:
                fence = marker[1]
            elif (marker[1][0] == fence[0] and len(marker[1]) >= len(fence)
                  and not line[marker.end():].strip()):
                fence = None
        if not line.strip() and fence is None:
            if current:
                blocks.append(''.join(current))
                current = []
        else:
            current.append(line)
    if current:
        blocks.append(''.join(current))
    return blocks

def public_failure(payload):
    """Accept only an adapter's explicitly public, diagnostic-backed attribution."""
    value = payload.get('public_failure')
    fields = ('function_id', 'requirement_id', 'diagnostic')
    if not isinstance(value, dict) or set(value) != set(fields):
        return None
    if not all(isinstance(value[k], str) and value[k].strip() for k in fields):
        return None
    feedback = payload.get('public_feedback', '')
    if not isinstance(feedback, str) or value['diagnostic'] not in feedback:
        return None
    return {key: value[key] for key in fields}

def report(frozen, rows):
    common = frozen['config']['common']
    conditions = conditions_for(frozen['config'])
    metrics = score(frozen['bank'], common['trial_ids'], rows,
                    study_sha256=frozen['study_sha256'], max_snippet_fixes=common['max_snippet_fixes'],
                    arms=conditions, baseline=conditions[0])
    pairs = []
    by_key = {(r['arm'], r['case_id'], r['trial_id']): r for r in rows}
    for baseline, treatment in combinations(conditions, 2):
        for kind in ('micro', 'puzzle'):
            paired = []
            for c in frozen['bank']['cases']:
                if c['kind'] != kind:
                    continue
                for trial in common['trial_ids']:
                    a, b = [by_key.get((arm, c['id'], trial), {}) for arm in (baseline, treatment)]
                    if a.get('status') in ('pass', 'fail') and b.get('status') in ('pass', 'fail'):
                        paired.append((a['status'], b['status']))
            recovered = sum(a == 'fail' and b == 'pass' for a, b in paired)
            regressed = sum(a == 'pass' and b == 'fail' for a, b in paired)
            n = metrics[baseline][kind]['selected']
            pairs.append({'baseline': baseline, 'treatment': treatment, 'kind': kind,
                          'paired_completed': len(paired), 'selected': n,
                          'recoveries': recovered, 'regressions': regressed,
                          'paired_delta_percentage_points': 100 * (recovered - regressed) / len(paired) if paired else None,
                          'final_lift_percentage_points': 100 * (recovered - regressed) / n if n and len(paired) == n else None})
    resources = {}
    for condition in conditions:
        values = [r.get('resources', {}) for r in rows if r['arm'] == condition]
        resources[condition] = {key: sum(v.get(key, 0) for v in values) for key in
                               ('provider_calls', 'provider_seconds', 'execution_seconds', 'reported_input_tokens', 'reported_output_tokens')}
        resources[condition]['calls_without_usage'] = sum(v.get('calls_without_usage', 0) for v in values)
    return {'study_sha256': frozen['study_sha256'], 'conditions': list(conditions),
            'metrics': metrics, 'paired_comparisons': pairs,
            'generation_classifications': generation_counts(rows, conditions),
            'resources': resources, 'all_complete': all(metrics[a][k]['unresolved'] == 0 for a in conditions for k in ('micro', 'puzzle')),
            'scope': frozen['bank'].get('scope_note', ''), 'holdout_review': frozen['config']['holdout_review']}

def verify(root):
    """Check artifact identity and archived reporting independently of live jobs."""
    root = Path(root)
    manifest = load(root / "evidence/manifest.json")
    changed = [r["path"] for r in manifest["files"]
               if not (root / r["path"]).is_file() or file_hash(root / r["path"]) != r["sha256"]]
    arm = load(root / "configs/active_arm.json")
    flags = tuple(arm[k] for k in ("readme", "aliases", "error_hints"))
    if arm["arm"] not in ARMS or flags != ARMS[arm["arm"]]:
        changed.append("invalid active-arm treatment matrix")
    return {"verified": not changed, "bound_files": len(manifest["files"]), "changed": changed,
            "arm": arm["arm"], "new_ablation_results_available": False}

def _value(value):
    """Accept enum values from SDK records as well as their JSON representation."""
    return getattr(value, 'value', value)

def classify_record(record):
    """Attach the normalized state while retaining code, usage, and raw metadata."""
    state = solution_state(record)
    record['solution_state'] = state
    record['response_kind'] = {
        'complete': 'solution', 'incomplete': 'incomplete_model_output',
        'refusal': 'refusal', 'empty': 'empty_model_output',
        'provider_failure': 'provider_failure',
    }[state['status']]
    return record

def solution_state(record):
    """Return an auditable completion decision for an adapter response dictionary.

    ``status`` is complete, incomplete, refusal, empty, or provider_failure.
    Only complete nonempty answers are executable. A legacy response without
    completeness metadata remains supported, but its unverified status is stated
    explicitly in ``reason``. The input dictionary and its code are not modified.
    """
    code = record.get('code')
    status = _value(record.get('response_status'))
    details = record.get('incomplete_details') or {}
    incomplete = record.get('incomplete_reason') or details.get('reason')
    finish = _value(record.get('finish_reason'))
    block = _value(record.get('prompt_block_reason'))
    selected = _selected_messages(record)
    message_statuses = [_value(item.get('status')) for item in selected]
    evidence = {'provider_status': status, 'incomplete_reason': incomplete,
                'finish_reason': finish, 'prompt_block_reason': block,
                'selected_message_statuses': message_statuses,
                'code_characters': len(code) if isinstance(code, str) else 0}

    def result(state, reason):
        return {'status': state, 'reason': reason, 'executable': state == 'complete',
                'evidence': evidence}

    if not isinstance(code, str):
        return result('provider_failure', 'invalid_code_field')
    if status in ('failed', 'cancelled') or record.get('error_code'):
        return result('provider_failure', 'provider_' + (status or 'error'))
    if record.get('refusals'):
        return result('refusal', 'provider_refusal')
    if block not in (None, '', 'BLOCKED_REASON_UNSPECIFIED'):
        return result('refusal', 'prompt_blocked_' + str(block).lower())
    blocked_finishes = {'SAFETY', 'RECITATION', 'BLOCKLIST', 'PROHIBITED_CONTENT',
                        'SPII', 'IMAGE_SAFETY', 'IMAGE_PROHIBITED_CONTENT'}
    if finish in blocked_finishes or incomplete == 'content_filter':
        return result('refusal', 'content_filter' if incomplete == 'content_filter'
                      else 'finish_' + str(finish).lower())
    if incomplete == 'max_output_tokens' or finish == 'MAX_TOKENS' or record.get('truncated') is True:
        return result('incomplete', 'max_output_tokens')
    if incomplete:
        return result('incomplete', str(incomplete))
    if status and status != 'completed':
        return result('incomplete', 'provider_' + str(status))
    if finish and finish != 'STOP':
        return result('incomplete', 'finish_' + str(finish).lower())
    for message_status in message_statuses:
        if message_status != 'completed':
            return result('incomplete', 'message_' + str(message_status or 'status_missing'))
    # Some custom adapters only report a kind. Use it as a fallback, preserving
    # more precise raw-provider reasons when both representations are present.
    for kind, state in (('provider_failure', 'provider_failure'),
                        ('refusal', 'refusal'), ('incomplete_model_output', 'incomplete')):
        if record.get('response_kind') == kind:
            return result(state, kind)
    if record.get('completion_metadata_expected') and not (status or finish or block):
        return result('incomplete', 'missing_completion_metadata')
    if not code.strip():
        return result('empty', 'no_model_code')
    if status == 'completed' or finish == 'STOP' or selected:
        return result('complete', 'provider_completed')
    return result('complete', 'legacy_nonempty_unverified')

def result(state, reason):
    return {'status': state, 'reason': reason, 'executable': state == 'complete',
            'evidence': evidence}

def scaffold_spec(config):
    """Read a configured harness or render a language-only, fail-closed skeleton."""
    config = Path(config).expanduser().resolve()
    engine = _engine_config_module()
    cfg = engine.load_config(config)
    execute = cfg.comprehension.get('execute', {}) or {}
    scaffold = execute.get('scaffold')
    if scaffold:
        path = (cfg.root / scaffold).resolve()
        if not path.is_file():
            raise ValueError(f'Configured scaffold is missing: {path}')
        return cfg, {'filename': path.name, 'text': path.read_text(encoding='utf-8'),
                     'origin': bind(path), 'method': 'configured_harness', 'imports_pending': False}
    frame = execute.get('scaffold_frame')
    imports = execute.get('imports', []) or []
    imports_pending = not isinstance(imports, list)
    if imports_pending:
        imports = []  # Automatic import mining belongs to validated adapter preparation.
    if frame:
        filename = execute.get('test_filename')
        if not filename:
            raise ValueError('A custom scaffold_frame requires comprehension.execute.test_filename')
        text = frame.replace('{imports}', '\n'.join(imports))
        origin = bind(config)
        method = 'configured_frame'
    else:
        language = cfg.language.lower()
        if language not in TEMPLATES:
            raise ValueError('Provide a scaffold or scaffold_frame for language: ' + cfg.language)
        template, filename = TEMPLATES[language]
        path = Path(__file__).resolve().parents[1] / 'templates/harness' / template
        text = path.read_text(encoding='utf-8').replace('{{imports}}', '\n'.join(imports))
        origin = bind(path)
        method = 'language_skeleton'
    if Path(filename).name != filename or filename in ('.', '..'):
        raise ValueError('Scaffold filename must be a filename, not a path')
    return cfg, {'filename': filename, 'text': text, 'origin': origin,
                 'method': method, 'imports_pending': imports_pending}

def relocate(value):
    path = (cfg.root / value).resolve()
    if path == repository or repository in path.parents:
        return str(worktree / path.relative_to(repository))
    return str(path)

@dataclass(frozen=True)
class Token:
    value: str
    line: int

def _body_start(tokens, start):
    """First declaration body outside constructor/type parameters, or no body."""
    depths = {'(': 0, '[': 0}
    for index in range(start, len(tokens)):
        value = tokens[index].value
        # A bodyless declaration ends before an unrelated expression on the
        # next line. Do not steal that expression's lambda/initializer brace.
        if (not any(depths.values()) and index and tokens[index].line > tokens[index - 1].line
                and value not in ('{', 'extends', 'with', '(', '[', 'private', 'protected')
                and tokens[index - 1].value not in ('extends', 'with', '.', ',')):
            return None
        if value in depths:
            depths[value] += 1
        elif value == ')':
            depths['('] -= 1
        elif value == ']':
            depths['['] -= 1
        elif not any(depths.values()):
            if value == '{':
                return index
            if value in ('}', ';', 'class', 'object', 'trait', 'def', 'val', 'var', 'package'):
                return None
        if any(v < 0 for v in depths.values()):
            return None
    return None

def _tokens(source):
    tokens = []
    i, line, n = 0, 1, len(source)
    while i < n:
        if source[i].isspace():
            line += source[i] == '\n'
            i += 1
        elif source.startswith('//', i):
            end = source.find('\n', i)
            i = n if end < 0 else end
        elif source.startswith('/*', i):
            level = 1
            i += 2
            while i < n and level:
                if source.startswith('/*', i):
                    level += 1
                    i += 2
                elif source.startswith('*/', i):
                    level -= 1
                    i += 2
                else:
                    line += source[i] == '\n'
                    i += 1
            if level:
                raise ValueError('Unterminated Scala comment')
        elif source.startswith('"""', i):
            end = source.find('"""', i + 3)
            if end < 0:
                raise ValueError('Unterminated Scala triple-quoted string')
            end += 3
            # Scala permits quote characters immediately before the final
            # three delimiters, e.g. four trailing quotes for a quoted label.
            while end < n and source[end] == '"':
                end += 1
            line += source[i:end].count('\n')
            i = end
        elif source[i] == '"' or (source[i] == "'" and re.match(r"'(?:\\.|[^'\\\n])'", source[i:])):
            quote = source[i]
            i += 1
            while i < n and source[i] != quote:
                if source[i] == '\\':
                    i += 2
                else:
                    line += source[i] == '\n'
                    i += 1
            if i >= n:
                raise ValueError('Unterminated Scala literal')
            i += 1
        elif source[i] == '`':
            end = source.find('`', i + 1)
            if end < 0 or '\n' in source[i:end]:
                raise ValueError('Invalid Scala quoted identifier')
            tokens.append(Token(source[i + 1:end], line))
            i = end + 1
        else:
            match = re.match(r'[A-Za-z_$][\w$]*|[^\s]', source[i:])
            value = match.group()
            tokens.append(Token(value, line))
            i += len(value)
    return tokens

@lru_cache(maxsize=128)
def definitions_with_owners(source):
    """Return direct named-owner member sites; local/anonymous scopes map to None."""
    tokens = _tokens(source)
    bodies = {}
    for index, token in enumerate(tokens[:-1]):
        if token.value not in ('class', 'object', 'trait'):
            continue
        if index and tokens[index - 1].value in ('.', 'classOf'):
            continue
        name = tokens[index + 1].value
        if not re.fullmatch(r'[A-Za-z_$][\w$]*', name):
            continue
        body = _body_start(tokens, index + 2)
        if body is not None:
            if body in bodies:
                raise ValueError('Ambiguous Scala owner header')
            bodies[body] = {'receiver': name, 'owner_kind': token.value, 'declaration_line': token.line}
    stack, result = [], {}
    for index, token in enumerate(tokens):
        if token.value == '{':
            owner = bodies.get(index)
            # A named class inside a method/anonymous block is local as well;
            # its methods are not members of the enclosing receiver's API.
            if owner and any(item is None for item in stack):
                owner = None
            if owner:
                parents = [item['receiver'] for item in stack if item]
                owner = {**owner, 'owner_path': '.'.join(parents + [owner['receiver']])}
            stack.append(owner)
        elif token.value == '}':
            if not stack:
                raise ValueError('Unbalanced Scala source braces')
            stack.pop()
        elif token.value == 'def' and index + 1 < len(tokens):
            owner = stack[-1] if stack else None
            key = (token.line, tokens[index + 1].value)
            if key in result:
                raise ValueError('Multiple same-line definition sites require explicit resolution')
            result[key] = dict(owner) if owner else None
    if stack:
        raise ValueError('Unbalanced Scala source braces')
    return result

def owner_at_line(source: str, line: int, name: str | None = None) -> dict:
    """Require one definition at a one-based source line and return its lexical owner."""
    if type(line) is not int or line < 1:
        raise ValueError('Source line must be a positive integer')
    rows = [value for (where, method), value in definitions_with_owners(source).items()
            if where == line and (name is None or method == name)]
    if len(rows) != 1 or rows[0] is None:
        raise ValueError('Definition has no unique brace-bodied Scala receiver')
    return dict(rows[0])

def _digest(value):
    payload = value if isinstance(value, bytes) else json.dumps(value, sort_keys=True).encode()
    return hashlib.sha256(payload).hexdigest()

def _files(root, patterns):
    env = {**os.environ, 'GIT_OPTIONAL_LOCKS': '0'}
    skipped = []
    def git(*args):
        return subprocess.run(['git', '-C', str(root), *args], capture_output=True,
                              timeout=15, env=env)
    try:
        found = git('rev-parse', '--show-toplevel')
    except FileNotFoundError:
        if (root / '.git').exists():
            raise ValueError('Git is required to scan tracked repository sources')
        found = None
    if found is not None and found.returncode == 0:
        if Path(os.fsdecode(found.stdout).strip()).resolve() != root:
            raise ValueError('Pass the Git repository root, not a subdirectory')
        listing = git('ls-files', '--cached', '-z')
        if listing.returncode:
            raise ValueError('Unable to enumerate tracked Git sources')
        paths = [os.fsdecode(p) for p in listing.stdout.split(b'\0') if p]
        head = git('rev-parse', '--verify', 'HEAD')
        revision = head.stdout.decode().strip() if head.returncode == 0 else None
        mode = 'git_tracked_worktree'
    else:
        if (root / '.git').exists():
            raise ValueError('Cannot read the Git repository; refusing a filesystem fallback')
        paths = []
        def fail_discovery(error):
            raise ValueError('Unable to enumerate source scope: ' + str(error))
        for base, dirs, files in os.walk(root, followlinks=False, onerror=fail_discovery):
            skipped.extend({'path': (Path(base) / d).relative_to(root).as_posix(),
                            'reason': 'excluded_directory'} for d in dirs if d.lower() in EXCLUDED)
            dirs[:] = sorted(d for d in dirs if d.lower() not in EXCLUDED)
            paths.extend((Path(base) / f).relative_to(root).as_posix() for f in files)
            paths.extend((Path(base) / d).relative_to(root).as_posix() for d in dirs
                         if (Path(base) / d).is_symlink())
            dirs[:] = [d for d in dirs if not (Path(base) / d).is_symlink()]
        revision, mode = None, 'filesystem'
    selected = []
    for name in sorted(set(paths)):
        path = Path(name)
        if any(part.lower() in EXCLUDED for part in path.parts[:-1]):
            skipped.append({'path': name, 'reason': 'excluded_directory'})
        elif _matches(name, patterns) and (patterns or path.suffix.lower() in LANGUAGES
                                          or (root / path).is_symlink()):
            selected.append(name)
    return selected, skipped, mode, revision

def git(*args):
    return subprocess.run(['git', '-C', str(root), *args], capture_output=True,
                          timeout=15, env=env)

def _lexical_functions(raw, path, language):
    text = raw.decode('utf-8')
    if language == 'java' and re.search(r'\\u+[0-9a-fA-F]{4}', text):
        raise ValueError('Java Unicode preprocessing requires a compiler parser')
    tokens = _tokens(text, language)
    values = [t[0] for t in tokens]
    pairs, stack = {}, []
    for i, value in enumerate(values):
        if value in ('(', '[', '{'):
            stack.append((value, i))
        elif value in (')', ']', '}'):
            if not stack or stack[-1][0] != {')': '(', ']': '[', '}': '{'}[value]:
                raise ValueError('Unbalanced delimiters; lexical extraction incomplete')
            _, start = stack.pop()
            pairs[start] = i
    if stack:
        raise ValueError('Unbalanced delimiters; lexical extraction incomplete')
    result, excluded, i = [], 0, 0
    while i < len(values):
        name_at = i + 1 if values[i] == {'scala': 'def', 'rust': 'fn'}.get(language) else i
        if language != 'java' and name_at == i:
            i += 1
            continue
        name = values[name_at] if name_at < len(values) else ''
        if not re.fullmatch(r'[A-Za-z_$][\w$]*', name):
            i += 1
            continue
        cursor = name_at + 1
        if language == 'java' and (cursor >= len(values) or values[cursor] != '('):
            i += 1
            continue
        seen_params = False
        while cursor < len(values) and values[cursor] not in ('{', '}', ';', '='):
            if values[cursor] in ('(', '['):
                seen_params |= values[cursor] == '('
                cursor = pairs[cursor] + 1
            else:
                cursor += 1
        if language == 'scala' and cursor < len(values) and values[cursor] == '=':
            cursor += 1
            while cursor < len(values) and values[cursor] == '\n':
                cursor += 1
        if not seen_params or cursor >= len(values) or values[cursor] != '{':
            i += 1
            continue
        start = i
        while start and values[start - 1] not in (';', '{', '}', '\n'):
            start -= 1
        prefix = values[start:i]
        if language == 'java':
            modifiers = {'public', 'private', 'protected', 'static', 'final', 'abstract', 'synchronized', 'native', 'strictfp', 'default'}
            if (name in {'if', 'for', 'while', 'switch', 'catch', 'synchronized', 'try'}
                    or not any(v not in modifiers for v in prefix)
                    or any(v in prefix for v in ('=', 'new', 'class', 'record', 'interface', '@', '.', 'return'))):
                i += 1
                continue
            close_params = pairs[name_at + 1]
            if close_params + 1 != cursor and values[close_params + 1] != 'throws':
                i += 1
                continue
        end = pairs[cursor]
        body = values[cursor + 1:end]
        meaningful = [v for v in body if v not in ('\n', '{', '}')]
        separators = body.count(';') + (body.count('\n') if language == 'scala' else 0)
        if len(meaningful) < 14 or separators < (2 if language == 'java' else 1):
            excluded += 1
        else:
            header = values[start:cursor]
            header[name_at - start] = '<function-name>'
            result.append({'name': name, 'line': tokens[i][1], 'end_line': tokens[end][1],
                'kind': 'method' if language == 'java' else 'function_or_method',
                'signature': text[tokens[start][2]:tokens[cursor][2]].strip(),
                '_key': _digest([header, body])})
        i = end + 1
    return result, excluded

def _matches(path, patterns):
    def match(parts, pattern):
        if not pattern:
            return not parts
        if pattern[0] == '**':
            return match(parts, pattern[1:]) or bool(parts) and match(parts[1:], pattern)
        return bool(parts) and fnmatch.fnmatchcase(parts[0], pattern[0]) and match(parts[1:], pattern[1:])
    return not patterns or any(match(path.split('/'), p.split('/')) for p in patterns)

def match(parts, pattern):
    if not pattern:
        return not parts
    if pattern[0] == '**':
        return match(parts, pattern[1:]) or bool(parts) and match(parts[1:], pattern)
    return bool(parts) and fnmatch.fnmatchcase(parts[0], pattern[0]) and match(parts[1:], pattern[1:])

def _python_functions(raw, path):
    tree = ast.parse(raw, filename=path, type_comments=True)
    result, excluded = [], 0
    def visit(body, prefix=''):
        nonlocal excluded
        for node in body:
            if isinstance(node, ast.ClassDef):
                visit(node.body, prefix + node.name + '.')
            elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
                executable = node.body
                if executable and isinstance(executable[0], ast.Expr) and isinstance(
                        executable[0].value, ast.Constant) and isinstance(executable[0].value.value, str):
                    executable = executable[1:]
                abstract = any(ast.unparse(d).split('.')[-1] == 'abstractmethod' for d in node.decorator_list)
                if abstract or len(executable) < 2 or sum(1 for n in executable for _ in ast.walk(n)) < 12:
                    excluded += 1
                    continue
                # Only the declared function name is omitted; all bindings/literals remain.
                structure = {field: ast.dump(value, include_attributes=False) if isinstance(value, ast.AST)
                             else [ast.dump(v, include_attributes=False) for v in value] if isinstance(value, list)
                             else value for field, value in ast.iter_fields(node) if field != 'name'}
                signature = ('async ' if isinstance(node, ast.AsyncFunctionDef) else '') + node.name + '(' + ast.unparse(node.args) + ')'
                if node.returns:
                    signature += ' -> ' + ast.unparse(node.returns)
                result.append({'name': prefix + node.name, 'line': node.lineno,
                    'end_line': node.end_lineno, 'kind': 'method' if prefix else 'function',
                    'decorators': [ast.unparse(d) for d in node.decorator_list], 'type_comment': node.type_comment,
                    'signature': signature, '_key': _digest([type(node).__name__, structure])})
    visit(tree.body)
    return result, excluded

def visit(body, prefix=''):
    nonlocal excluded
    for node in body:
        if isinstance(node, ast.ClassDef):
            visit(node.body, prefix + node.name + '.')
        elif isinstance(node, (ast.FunctionDef, ast.AsyncFunctionDef)):
            executable = node.body
            if executable and isinstance(executable[0], ast.Expr) and isinstance(
                    executable[0].value, ast.Constant) and isinstance(executable[0].value.value, str):
                executable = executable[1:]
            abstract = any(ast.unparse(d).split('.')[-1] == 'abstractmethod' for d in node.decorator_list)
            if abstract or len(executable) < 2 or sum(1 for n in executable for _ in ast.walk(n)) < 12:
                excluded += 1
                continue
            # Only the declared function name is omitted; all bindings/literals remain.
            structure = {field: ast.dump(value, include_attributes=False) if isinstance(value, ast.AST)
                         else [ast.dump(v, include_attributes=False) for v in value] if isinstance(value, list)
                         else value for field, value in ast.iter_fields(node) if field != 'name'}
            signature = ('async ' if isinstance(node, ast.AsyncFunctionDef) else '') + node.name + '(' + ast.unparse(node.args) + ')'
            if node.returns:
                signature += ' -> ' + ast.unparse(node.returns)
            result.append({'name': prefix + node.name, 'line': node.lineno,
                'end_line': node.end_lineno, 'kind': 'method' if prefix else 'function',
                'decorators': [ast.unparse(d) for d in node.decorator_list], 'type_comment': node.type_comment,
                'signature': signature, '_key': _digest([type(node).__name__, structure])})

def _tokens(text, language):
    """Keep literal bytes/identifiers; discard comments without treating their braces as code."""
    tokens, i, line = [], 0, 1
    while i < len(text):
        start, start_line, char = i, line, text[i]
        if char.isspace():
            if char == '\n':
                line += 1
                if language == 'scala':
                    tokens.append(('\n', start_line, i))
            i += 1
            continue
        if text.startswith('//', i):
            end = text.find('\n', i)
            i = len(text) if end < 0 else end
            continue
        if text.startswith('/*', i):
            depth, i = 1, i + 2
            while depth and i < len(text):
                if text.startswith('/*', i) and language in {'scala', 'rust'}:
                    depth, i = depth + 1, i + 2
                elif text.startswith('*/', i):
                    depth, i = depth - 1, i + 2
                else:
                    i += 1
            if depth:
                raise ValueError('Unterminated block comment')
            line += text[start:i].count('\n')
            if language == 'scala' and '\n' in text[start:i]:
                tokens.append(('\n', start_line, start))
            continue
        raw = _RUST_RAW.match(text, i) if language == 'rust' else None
        if raw:
            close = '"' + raw.group(1)
            end = text.find(close, raw.end())
            if end < 0:
                raise ValueError('Unterminated Rust raw string')
            i = end + len(close)
        elif text.startswith('"""', i) and language in {'scala', 'java'}:
            end = text.find('"""', i + 3)
            if language == 'java':
                while end >= 0 and (len(text[:end]) - len(text[:end].rstrip('\\'))) % 2:
                    end = text.find('"""', end + 3)
            if end < 0:
                raise ValueError('Unterminated multiline string')
            i = end + 3
        elif char == '"' or (char == "'" and _CHAR.match(text, i)):
            quote, i = char, i + 1
            while i < len(text) and text[i] != quote:
                i += 2 if text[i] == '\\' else 1
            if i >= len(text):
                raise ValueError('Unterminated string')
            i += 1
        else:
            if char == "'" and language == 'java':
                raise ValueError('Invalid or unsupported Java character literal')
            word = _WORD.match(text, i)
            i = word.end() if word else i + 1
        value = text[start:i]
        line += value.count('\n')
        tokens.append((value, start_line, start))
    return tokens

def compare_duplicate_reports(before, after):
    """Compare observed candidates, refusing to claim reduction after coverage failures."""
    reasons = []
    for field in ('schema_version', 'analyzer', 'settings', 'scope'):
        if field not in before or field not in after or before[field] != after[field]:
            reasons.append(f'Incompatible or missing {field}')
    for label, report in (('before', before), ('after', after)):
        if report.get('schema_version') != 1:
            reasons.append(f'{label} has an unsupported report schema')
        if report.get('errors') or report.get('coverage', {}).get('failed_files', 1):
            reasons.append(f'{label} has incomplete/error coverage')
        if not report.get('coverage', {}).get('scanned_files'):
            reasons.append(f'{label} has no scanned source files')
        counts = report.get('counts')
        required = ('eligible_functions', 'duplicate_groups', 'functions_in_groups', 'redundant_instances')
        if not isinstance(counts, dict) or any(type(counts.get(k)) is not int or counts[k] < 0 for k in required):
            reasons.append(f'{label} has an invalid count record')
    before_paths = {r['path'] for r in before.get('inputs', [])}
    after_paths = {r['path'] for r in after.get('inputs', [])}
    comparable = not reasons
    reduction = ({key: before['counts'][key] - after['counts'][key]
                  for key in ('duplicate_groups', 'functions_in_groups', 'redundant_instances')}
                 if comparable else None)
    return {'schema_version': 1, 'comparable': comparable, 'reasons': reasons,
            'before': before.get('counts'), 'after': after.get('counts'), 'reduction': reduction,
            'added_files': sorted(after_paths - before_paths), 'removed_files': sorted(before_paths - after_paths),
            'before_input_sha256': before.get('input_sha256'), 'after_input_sha256': after.get('input_sha256'),
            'semantic_equivalence': 'not_checked', 'api_compatibility': 'not_checked',
            'interpretation': 'Counts concern structural candidates only. A reduction does not prove equivalent behavior, successful refactoring, or preserved API coverage. Partial lexical extraction may miss changed syntax. Different roots are allowed; repository lineage is not established.'}

def _baseline(root, revision):
    root = Path(root).resolve(strict=True)
    if git(root, 'rev-parse', '--show-toplevel') != str(root) or git(root, 'rev-parse', 'HEAD') != revision:
        raise ValueError('Development source is not the exact pinned Git root/revision')
    _check_worktree(root, revision, {})
    return root

def _body(code):
    match = re.fullmatch(r'\s*```[^
]*
(.*?)
```\s*', code, re.S)
    return match[1] if match else code

def _destination(root, output):
    output = Path(output).resolve()
    if output == root or output.is_relative_to(root) or output.exists():
        raise ValueError('Use a new development output outside the source checkout')
    return output

def _diagnoses(value, preview):
    if not isinstance(value, dict) or set(value) != {'diagnoses'} or not isinstance(value['diagnoses'], list):
        raise ValueError('Author must return one structured diagnoses list')
    cases = {case['evidence_id']: case for case in preview['cases']}
    accepted, seen = [], set()
    fields = {'evidence_id', 'classification', 'reason', 'source_quote', 'hint', 'corrected_code'}
    for row in value['diagnoses']:
        if not isinstance(row, dict) or set(row) != fields or row.get('evidence_id') not in cases or row['evidence_id'] in seen:
            raise ValueError('Diagnosis must identify one unique supplied development case')
        seen.add(row['evidence_id'])
        if row['classification'] not in ('api_requirement', 'not_api_requirement', 'uncertain') or not isinstance(row['reason'], str) or not row['reason'].strip():
            raise ValueError('Diagnosis needs a classification and reason')
        if row['classification'] != 'api_requirement':
            if row['hint'] is not None or row['corrected_code'] not in ('', None):
                raise ValueError('Unsupported diagnosis cannot supply installable guidance')
            continue
        case, hint = cases[row['evidence_id']], row['hint']
        required = {'function_id', 'requirement_id', 'requirement', 'diagnostic', 'action', 'validation'}
        if not isinstance(hint, dict) or set(hint) != required or hint['function_id'] != case['function_id']:
            raise ValueError('Hint must address its independently attributed function')
        source_fragments = [case['facts']['source_window'],
                            *(record['text'] for record in case['facts'].get('namespace_declarations', []))]
        if (not isinstance(row['source_quote'], str) or len(row['source_quote'].strip()) < 8
                or not any(row['source_quote'] in fragment for fragment in source_fragments)):
            raise ValueError('A requirement diagnosis must cite an exact supplied source fragment')
        if not isinstance(hint['diagnostic'], str) or hint['diagnostic'] not in case['diagnostic']:
            raise ValueError('Hint diagnostic must occur in its Original R0 failure')
        if not isinstance(row['corrected_code'], str) or not row['corrected_code'].strip():
            raise ValueError('Supply a complete candidate correction for independent validation')
        accepted.append(row)
    if seen != set(cases):
        raise ValueError('Every supplied failure needs a diagnosis, including unsupported ones')
    return accepted

def _facts(root, identity):
    relative, number, name = _identity(identity)
    candidate = root / relative
    path = candidate.resolve(strict=True)
    if (not path.is_relative_to(root) or any(part.startswith('.') for part in Path(relative).parts)
            or candidate.is_symlink() or path.suffix not in ('.py', '.scala', '.java', '.rs')
            or path.stat().st_size > 2_000_000):
        raise ValueError('Unsafe or oversized development source')
    if relative not in git(root, 'ls-files', '--', relative).splitlines():
        raise ValueError('Development API source must be committed')
    lines = path.read_text().splitlines(keepends=True)
    actual, signature = _declaration(lines, number - 1, name)
    if actual != number - 1:
        raise ValueError('Canonical ID does not identify the exact source declaration')
    window = ''.join(lines[max(0, actual - 8):actual + 72])
    if len(window) > 12000:
        raise ValueError('Source window exceeds bounded authoring input; narrow this development case')
    return {'function_id': identity, 'path': relative, 'line': number, 'signature': signature,
            'source_window': window, 'source_window_start_line': max(0, actual - 8) + 1,
            'namespace_declarations': [{'line': i + 1, 'text': line.rstrip('\r\n')}
                                       for i, line in enumerate(lines[:80])
                                       if re.match(r'^\s*package\s+[A-Za-z_][\w.]*\s*;?\s*$', line)],
            'source': bind(path)}

def _group_hints(diagnoses):
    """Consolidate identical requirements while retaining every triggering case."""
    grouped = {}
    for diagnosis in diagnoses:
        hint = diagnosis['hint']
        key = hint['function_id'], hint['requirement_id']
        if key in grouped and grouped[key]['hint'] != hint:
            raise ValueError('Conflicting definitions for the same function and requirement')
        group = grouped.setdefault(key, {'hint': hint, 'evidence_ids': []})
        group['evidence_ids'].append(diagnosis['evidence_id'])
    return list(grouped.values())

def _open(path):
    value = load(path)
    if value.get('sha256') != digest({k: v for k, v in value.items() if k != 'sha256'}):
        raise ValueError('Development record changed')
    if not all(verify_artifact(ref) for ref in value['artifacts']):
        raise ValueError('Development evidence changed')
    _baseline(value['source_root'], value['baseline_revision'])
    return value

def _outcome(process):
    payload = process.get('payload')
    keys = ('execution_pass', 'oracle_pass', 'target_reached')
    if process.get('status') != 'ok' or not isinstance(payload, dict) or any(type(payload.get(k)) is not bool for k in keys):
        raise ValueError('Checker did not supply three explicit outcome booleans')
    if not isinstance(payload.get('public_feedback'), str):
        raise ValueError('Checker needs a public diagnostic')
    return payload, all(payload[k] for k in keys)

def _scope(value):
    if value.get('split') != 'development' or value.get('condition') != 'original' or type(value.get('round')) is not int or value['round'] != 0:
        raise ValueError('Only Original DEVELOPMENT R0 evidence can develop source hints')

def _validated_content(proposal):
    """The source log records measured development checks, not model assertions."""
    root = Path(proposal['source_root'])
    contents = {}
    for row in proposal['sources']:
        original = (root / row['path']).read_bytes()
        if hashlib.sha256(original).hexdigest() != row['baseline_sha256']:
            raise ValueError('Validated source no longer matches its baseline')
        text = original.decode('utf-8')
        for group in _group_hints(proposal['diagnoses']):
            hint = group['hint']
            if hint['function_id'].rsplit(':', 2)[0] != row['path']:
                continue
            fields = {**hint, 'status': 'validated_development',
                      'validation': 'Development checks passed: trigger reproduced; corrected and valid pass; '
                                    'nearby failure does not select this requirement. Evidence: '
                                    + ', '.join(group['evidence_ids']) + '. ' + hint['validation']}
            text = insert_source_hint(text, hint['function_id'], fields, source_path=row['path'])
        if strip_source_hints(text) != strip_source_hints(original.decode('utf-8')):
            raise ValueError('Validated source changed executable content')
        contents[row['path']] = text.encode('utf-8')
    return contents

def _verified(ref):
    if not isinstance(ref, dict) or not verify_artifact(ref):
        raise ValueError('Missing or changed development artifact')
    return load(ref['path'])

def verify_development_validation(path):
    """Reconstruct all saved checks and exact installable bytes without rerunning."""
    result = _open(path)
    if result.get('status') != 'validated':
        raise ValueError('Only validated source hints can be installed')
    _verified(result['proposal'])
    proposal = _open(result['proposal']['path'])
    preview, plan = _verified(proposal['preview']), _verified(result['validation_plan'])
    source_proposal = _verified(proposal['source_proposal'])
    if result['source_proposal'] != proposal['source_proposal'] or result['sources'] != proposal['sources']:
        raise ValueError('Validation source proposal differs')
    if result['api_function_ids'] != preview['api_function_ids']:
        raise ValueError('Validation API mapping differs')
    index = index_source_hints(Path(source_proposal['output']) / 'source',
                              [row['path'] for row in proposal['sources']], preview['api_function_ids'])
    cases = {row['evidence_id']: row for row in preview['cases']}
    saved = {(row['evidence_id'], row['role']): row for row in result['checks']}
    expected_keys = {(row['evidence_id'], role) for row in proposal['diagnoses'] for role in ROLES}
    if set(saved) != expected_keys or len(saved) != len(result['checks']):
        raise ValueError('Missing, duplicate or unexpected development validation check')
    expected_hints = []
    for diagnosis in proposal['diagnoses']:
        identifier, hint = diagnosis['evidence_id'], diagnosis['hint']
        expected_hints.append({'function_id': hint['function_id'], 'requirement_id': hint['requirement_id'], 'evidence_id': identifier})
        control = plan['controls'][identifier]
        codes = {'trigger': cases[identifier]['code'], 'corrected': diagnosis['corrected_code'],
                 'valid': Path(control['valid_code']['path']).read_text(),
                 'nearby_negative': Path(control['nearby_code']['path']).read_text()}
        for role in ROLES:
            row = saved[identifier, role]
            request = {'protocol': PROTOCOL, 'split': 'development', 'role': role,
                       'case_id': identifier, 'code': codes[role], 'source_root': proposal['source_root'],
                       'source_revision': proposal['baseline_revision'],
                       'checker_context_path': control['checker_context']['path']}
            if _verified(row['request']) != request:
                raise ValueError('Validation request differs from its bound controls')
            payload, passed = _outcome(_verified(row['process']))
            if payload.get('request_sha256') != digest(request) or payload.get('source_revision') != proposal['baseline_revision']:
                raise ValueError('Validation process identity differs')
            previous = {'code': codes[role], 'feedback': payload['public_feedback']}
            if 'public_failure' in payload:
                previous['public_failure'] = payload['public_failure']
            selection = select_source_hints(index, previous)
            key = hint['function_id'], hint['requirement_id']
            matches = {(r['function_id'], r['requirement_id']) for r in selection['matched']}
            if not _valid_check(role, passed, key, matches, selection) or row['valid'] is not True or row['passed'] != passed or row['selection'] != selection or (row['function_id'], row['requirement_id']) != key:
                raise ValueError('Saved development check does not establish its claimed outcome')
    if result['expected_hints'] != expected_hints:
        raise ValueError('Validated hint scope changed')
    content = _validated_content(proposal)
    installed = {row['path']: row for row in result['installable_sources']}
    if set(installed) != set(content) or len(installed) != len(result['installable_sources']):
        raise ValueError('Installable source list differs')
    for relative, data in content.items():
        row = installed[relative]
        if not verify_artifact(row['artifact']) or Path(row['artifact']['path']).read_bytes() != data:
            raise ValueError('Installable source differs from validated comments')
        baseline = next(item['baseline_sha256'] for item in proposal['sources'] if item['path'] == relative)
        if row['baseline_sha256'] != baseline:
            raise ValueError('Installable baseline source differs')
    return result

def _validated(path):
    from .source_hint_development import verify_development_validation
    value = verify_development_validation(path)
    if value.get('status') != 'validated' or not value.get('installable_sources'):
        raise ValueError('Only replay-verified development guidance can be installed')
    return value

def _read_spec(path):
    data = path.read_bytes()
    if len(data) > 2_000_000:
        raise ValueError('Source hint spec exceeds size bound')
    spec = json.loads(data)
    required = {'schema_version', 'api_function_ids', 'source_sha256', 'hints'}
    if not isinstance(spec, dict) or set(spec) != required or spec['schema_version'] != 1:
        raise ValueError('Expected source hint spec schema_version 1 and exactly its four fields')
    apis, hashes, hints = spec['api_function_ids'], spec['source_sha256'], spec['hints']
    if not isinstance(apis, dict) or not apis or not all(
            isinstance(k, str) and k and isinstance(v, str) and v for k, v in apis.items()):
        raise ValueError('api_function_ids must map API names to canonical function IDs')
    if len(set(apis.values())) != len(apis):
        raise ValueError('Canonical function IDs must be unique')
    if not isinstance(hashes, dict) or not all(isinstance(k, str) and isinstance(v, str)
            and re.fullmatch(r'[0-9a-f]{64}', v) for k, v in hashes.items()):
        raise ValueError('source_sha256 must contain exact lowercase SHA-256 values')
    if not isinstance(hints, list) or not hints or len(hints) > 2000:
        raise ValueError('Provide between 1 and 2000 source hint proposals')
    return spec, data

def _relative_source(function_id):
    if not isinstance(function_id, str):
        raise ValueError('function_id must be a canonical string')
    parts = function_id.rsplit(':', 2)
    if len(parts) != 3 or not parts[1].isdigit() or int(parts[1]) < 1:
        raise ValueError('function_id must be path:line:name')
    relative = Path(parts[0])
    if relative.is_absolute() or '..' in relative.parts or '\\' in parts[0]:
        raise ValueError('Source path must stay inside the source root')
    if relative.as_posix() != parts[0] or relative.suffix not in ('.py', '.scala', '.java', '.rs'):
        raise ValueError('Use a normalized Python, Scala, Java or Rust source path')
    return relative, int(parts[1])

def _blocks(text):
    lines, comments = text.splitlines(keepends=True), _comment_lines(text)
    active, blocks = None, []
    for number, (_, content) in comments.items():
        if content == BEGIN:
            if active is not None:
                raise ValueError('Nested source hint markers')
            active = number
        elif content == END:
            if active is None:
                raise ValueError('Unpaired source hint END')
            if any(i not in comments for i in range(active, number + 1)):
                raise ValueError('Source hints must contain only whole-line comments')
            prefixes = {comments[i][0] for i in range(active, number + 1)}
            if len(prefixes) != 1:
                raise ValueError('Source hint comment prefixes differ')
            if prefixes == {'//'}:
                _reject_unicode_escapes(lines[active:number + 1])
            if sum(len(lines[i]) for i in range(active, number + 1)) > MAX_BLOCK_CHARACTERS:
                raise ValueError('Source hint exceeds bounded annotation size')
            blocks.append((active, number, [comments[i][1] for i in range(active + 1, number)]))
            active = None
    if active is not None:
        raise ValueError('Unpaired source hint BEGIN')
    return blocks

def _comment_lines(text):
    """Identify genuine whole-line comments, excluding strings/block comments.

    Handles Python triple strings and C/Scala/Java strings, plus Rust raw strings.
    Unknown/unterminated quoting fails conservatively by hiding later markers.
    """
    comments, quote, block, raw_end = {}, None, 0, None
    for number, line in enumerate(text.splitlines(keepends=True)):
        i = 0
        while i < len(line):
            if raw_end:
                end = line.find(raw_end, i)
                if end < 0:
                    break
                i, raw_end = end + len(raw_end), None
                continue
            if quote:
                if line.startswith(quote, i):
                    i, quote = i + len(quote), None
                elif line[i] == '\\':
                    i += 2
                else:
                    i += 1
                continue
            if block:
                if line.startswith('*/', i):
                    block -= 1
                    i += 2
                elif line.startswith('/*', i):
                    block += 1
                    i += 2
                else:
                    i += 1
                continue
            if line.startswith('//', i) or line[i] == '#':
                if not line[:i].strip():
                    prefix = '//' if line.startswith('//', i) else '#'
                    comments[number] = (prefix, line[i + len(prefix):].strip())
                break
            if line.startswith('/*', i):
                block, i = 1, i + 2
                continue
            raw = re.match(r'(?:br|r)(#+)?"', line[i:])
            if raw:
                raw_end = '"' + (raw[1] or '')
                i += raw.end()
                continue
            if line.startswith('"""', i) or line.startswith("'''", i):
                quote, i = line[i:i + 3], i + 3
                continue
            if line[i] in '\"\'':
                # Rust lifetimes are not string literals.
                if line[i] == "'" and re.match(r"'[A-Za-z_]\w*(?!')", line[i:]) and "'" not in line[i + 1:]:
                    i += 1
                    continue
                quote, i = line[i], i + 1
                continue
            i += 1
    return comments

def _declaration(lines, start, name):
    while start < len(lines) and not lines[start].strip():
        start += 1
    prefix = ''.join(lines[start:start + 12])
    # Only declaration syntax, never an arbitrary reference or call expression.
    patterns = (r'\b(?:async\s+)?def\s+' + re.escape(name) + r'\b',
                r'\bfn\s+' + re.escape(name) + r'\b',
                r'\b(?:public|protected|private|static|final|synchronized|abstract|native|default)\s+[^;={}]*?\b' + re.escape(name) + r'\s*\(')
    found = next((re.search(p, prefix) for p in patterns if re.search(p, prefix)), None)
    if found is None or prefix[:found.start()].count('\n') > 2:
        raise ValueError('Source hint must immediately precede its real function declaration')
    declaration_start = start + prefix[:found.start()].count('\n')
    if any(line.strip() and not line.lstrip().startswith(('@', 'pub ', 'public ', 'private ', 'protected ', 'static ', 'final '))
           for line in lines[start:declaration_start]):
        raise ValueError('Unexpected code between source hint and declaration')
    signature = ''
    depth = 0
    for line in lines[declaration_start:declaration_start + 12]:
        for i, char in enumerate(line):
            if char in '([':
                depth += 1
            elif char in ')]':
                depth -= 1
            if depth == 0 and (char == '{' or (char == '=' and line[i:i + 2] != '=>')
                               or (char == ':' and re.search(r'\bdef\s+', signature + line[:i]) and line[i + 1:].strip() == '')):
                signature += line[:i].rstrip()
                if len(signature) > 4000:
                    raise ValueError('Signature exceeds bound')
                return declaration_start, signature
        signature += line
        if len(signature) > 4000:
            break
    raise ValueError('Cannot identify bounded function signature')

def _fields(lines):
    result = {}
    for line in lines:
        key, separator, value = line.partition(':')
        if not separator or key not in REQUIRED + ('status',):
            raise ValueError('Unknown or malformed source hint field')
        if key in result:
            raise ValueError('Duplicate source hint field: ' + key)
        result[key] = value.strip()
    if any(not result.get(key) for key in REQUIRED):
        raise ValueError('Source hint is missing a required field')
    if not re.fullmatch(r'[A-Za-z0-9_.:-]+', result['requirement_id']):
        raise ValueError('Unsafe requirement identifier')
    # Broad compiler phrases are symptoms, not violated API requirements.
    diagnostic = result['diagnostic'].casefold().strip(' .:;')
    if len(diagnostic) < 8 or diagnostic in {
            'type mismatch', 'typeerror', 'valueerror', 'error', 'exception',
            'compilation failed', 'runtime error', 'assertion failed'}:
        raise ValueError('Source hint needs a specific requirement diagnostic')
    result.setdefault('status', 'unvalidated')
    return result

def _identity(function_id):
    match = re.fullmatch(r'(.+):(\d+):([^:/]+)', function_id)
    if not match or int(match[2]) < 1:
        raise ValueError('Canonical function ID must be path:line:name')
    path = Path(match[1])
    if path.is_absolute() or '..' in path.parts or '\\' in match[1]:
        raise ValueError('Canonical function path must stay inside worktree')
    return match[1], int(match[2]), match[3]

def index_source_hints(worktree, artifacts, api_function_ids):
    """Index explicit source files and report missing API coverage before a run."""
    root = Path(worktree).resolve(strict=True)
    reverse = {identity: api for api, identity in api_function_ids.items()}
    if len(reverse) != len(api_function_ids):
        raise ValueError('Canonical function IDs must be unique')
    records, bindings, seen_paths, seen_requirements, unmapped = [], [], set(), set(), []
    for artifact in artifacts:
        path = Path(artifact)
        path = (root / path if not path.is_absolute() else path).resolve(strict=True)
        if not path.is_relative_to(root) or not path.is_file():
            raise ValueError('Source hint artifact escapes worktree')
        relative = path.relative_to(root).as_posix()
        if relative in seen_paths:
            raise ValueError('Duplicate source hint artifact')
        seen_paths.add(relative)
        if path.suffix not in ('.py', '.scala', '.java', '.rs'):
            raise ValueError('Source hints support Python, Scala, Java and Rust source files')
        if path.stat().st_size > MAX_SOURCE_BYTES:
            raise ValueError('Source hint artifact exceeds source size bound')
        data = path.read_bytes()
        text, lines = data.decode('utf-8'), data.decode('utf-8').splitlines(keepends=True)
        bindings.append({'path': str(path), 'sha256': hashlib.sha256(data).hexdigest(), 'bytes': len(data)})
        blocks = _blocks(text)
        removed = {i for start, end, _ in blocks for i in range(start, end + 1)}
        for start, end, content in blocks:
            fields = _fields(content)
            source_path, baseline_line, name = _identity(fields['function_id'])
            if source_path != relative:
                raise ValueError('Source hint canonical path does not match its source file')
            after = end + 1
            while after < len(lines) and (after in removed or not lines[after].strip()):
                after += 1
            declaration_line, signature = _declaration(lines, after, name)
            original_line = declaration_line + 1 - sum(i < declaration_line for i in removed)
            if baseline_line != original_line:
                raise ValueError('Canonical baseline line does not identify the annotated declaration')
            key = fields['function_id'], fields['requirement_id']
            if key in seen_requirements:
                raise ValueError('Duplicate source requirement identity')
            seen_requirements.add(key)
            if fields['function_id'] not in reverse:
                unmapped.append(fields['function_id'])
                continue
            record = {**fields, 'api': reverse[fields['function_id']], 'path': relative,
                      'annotation_start_line': start + 1, 'annotation_end_line': end + 1,
                      'declaration_line': declaration_line + 1, 'signature': signature,
                      'source_window': ''.join(lines[declaration_line:declaration_line + 12])[:6000],
                      'source_sha256': bindings[-1]['sha256']}
            record['hint_sha256'] = hashlib.sha256(repr(sorted(record.items())).encode()).hexdigest()
            records.append(record)
    covered = {r['function_id'] for r in records}
    return {'schema_version': 1, 'records': records, 'artifacts': bindings,
            'api_function_ids': dict(api_function_ids),
            'coverage': {'total_functions': len(reverse), 'covered_functions': len(covered),
                         'hint_count': len(records), 'uncovered_function_ids': sorted(set(reverse) - covered),
                         'unmapped_function_ids': sorted(set(unmapped))}}

def render_source_hint(fields, comment_prefix='//'):
    """Render a reviewed proposal as ordinary source comments, never code."""
    if comment_prefix not in ('//', '#'):
        raise ValueError('Use a supported whole-line comment prefix')
    if any(not isinstance(value, str) or '\n' in value or '\r' in value
           for value in fields.values()):
        raise ValueError('Source hint values must be single-line text')
    if comment_prefix == '//':
        _reject_unicode_escapes(fields.values())
    checked = _fields([key + ': ' + value for key, value in fields.items()])
    return '\n'.join(comment_prefix + ' ' + line for line in
                     [BEGIN, *(key + ': ' + checked[key] for key in REQUIRED + ('status',)), END]) + '\n'

def select_source_hints(index, previous):
    """Select guidance only after function and requirement evidence agree."""
    from .failure_diagnosis import diagnose_failure
    diagnosis = diagnose_failure(index, previous)
    if diagnosis['status'] != 'identified':
        return {'diagnosis': diagnosis, 'matched': [], 'reason': diagnosis['status']}
    candidates = [r for r in index['records'] if r['function_id'] == diagnosis['function_id']]
    matched = [r for r in candidates if r['diagnostic'] in diagnosis['diagnostic']
               and (not diagnosis.get('requirement_id') or r['requirement_id'] == diagnosis['requirement_id'])]
    reason = 'matched' if matched else 'requirement_not_covered' if candidates else 'function_not_covered'
    return {'diagnosis': diagnosis, 'matched': matched, 'reason': reason}

def strip_source_hints(text):
    """Remove only recognized comment blocks, retaining every other exact byte."""
    lines = text.splitlines(keepends=True)
    for start, end, _ in reversed(_blocks(text)):
        del lines[start:end + 1]
    return ''.join(lines)

def _candidate(proposal_path, baseline, original):
    path = Path(proposal_path).expanduser().absolute()
    if path.is_symlink():
        raise ValueError('Refactor proposal must not be a symlink')
    path = path.resolve(strict=True)
    proposal = load(path)
    if (not isinstance(proposal, dict) or type(proposal.get('schema_version')) is not int
            or proposal['schema_version'] != 1 or proposal.get('kind') != 'source_refactor'
            or proposal.get('baseline_revision') != baseline):
        raise ValueError('Refactor proposal must match the exact attached baseline')
    if proposal.get('preserve_public_api') is not True:
        raise ValueError('Refactor comparison requires preserving the original public API')
    checks = proposal.get('validation_plan')
    if not isinstance(checks, list) or not checks or any(not isinstance(x, str) or not x.strip() for x in checks):
        raise ValueError('List concrete compatibility/regression checks in validation_plan')
    changes = proposal.get('changes')
    if not isinstance(changes, list) or not changes:
        raise ValueError('Refactor proposal needs explicit source changes')
    files, removed, data, targets = {}, [], {}, set()
    tracked = _trees(original, baseline)
    algorithm = _run(original, 'rev-parse', '--show-object-format')
    for index, row in enumerate(changes):
        if not isinstance(row, dict) or 'after' not in row:
            raise ValueError('Each source change needs an explicit after binding or null deletion')
        target = _relative(row.get('path'))
        if target.casefold() in targets or any(part.startswith('.') for part in Path(target).parts):
            raise ValueError('Duplicate, hidden or reserved refactor path')
        targets.add(target.casefold())
        if Path(target).suffix not in ('.py', '.java', '.scala', '.rs'):
            raise ValueError('Refactor paths must be supported source files; docs/config/tests stay separate')
        current = _safe_path(original, target)
        if current.exists() and target not in tracked:
            raise ValueError('Refactor baseline path is not tracked')
        before = hashlib.sha256(current.read_bytes()).hexdigest() if current.is_file() else None
        if 'before_sha256' not in row or row['before_sha256'] != before:
            raise ValueError('Refactor before_sha256 does not match baseline: ' + target)
        after = row.get('after')
        if after is None:
            if before is None:
                raise ValueError('Cannot delete an absent source file')
            removed.append(target)
            continue
        if not isinstance(after, dict) or not isinstance(after.get('path'), str):
            raise ValueError('Refactor replacement needs an absolute artifact binding')
        source = Path(after['path'])
        if not source.is_absolute() or '..' in source.parts:
            raise ValueError('Refactor replacement must be inside the proposal directory')
        try:
            relative = source.relative_to(path.parent).as_posix()
        except ValueError as exc:
            raise ValueError('Replacement must be inside the proposal directory') from exc
        source = _safe_path(path.parent, relative)
        content = source.read_bytes()
        if (not content or type(after.get('bytes')) is not int or after['bytes'] != len(content)
                or after.get('sha256') != hashlib.sha256(content).hexdigest()):
            raise ValueError('Refactor replacement hash/size changed; use after:null for deletion')
        key = f'source_{index:04d}'
        data[key] = content
        files[target] = {'role': key, 'sha256': hashlib.sha256(content).hexdigest(),
                         'bytes': len(content), 'git_blob': _blob(content, algorithm),
                         'mode': tracked[target][0] if target in tracked else '100644'}
    if any(a.startswith(b + '/') or b.startswith(a + '/') for a in targets for b in targets if a != b):
        raise ValueError('Conflicting source paths')
    return proposal, files, removed, data

def _current(records):
    path = _safe_path(records, 'current.json')
    if not path.exists():
        return None, {}
    pointer = load(path)
    if not isinstance(pointer, dict):
        raise ValueError('Invalid current refactor pointer')
    version = _version(pointer.get('version'))
    expected_path = _safe_path(records, version + '.json')
    if pointer.get('record') != bind(expected_path):
        raise ValueError('Current refactor record changed or escaped its directory')
    return version, _lineage(records, version, pointer['record']['sha256'])

def _other_pending(records, permitted):
    """Prevent a second lineage while an earlier install needs recovery."""
    for path in records.glob('*.pending.json'):
        _safe_path(records, path.name)
        if _version(path.name.removesuffix('.pending.json')) not in permitted:
            raise ValueError('Another refactor version needs recovery first')

def _version(value):
    if not isinstance(value, str) or re.fullmatch(r'[0-9a-f]{64}', value) is None:
        raise ValueError('Invalid refactor version identity')
    return value

def _binding(path):
    data = path.read_bytes()
    return {'path': str(path), 'sha256': hashlib.sha256(data).hexdigest(), 'bytes': len(data)}

def _categories(kind, process, payload, directory):
    status = process.get('status', 'in_progress_or_interrupted')
    if status not in ('ok', 'completed'):
        return [process.get('error_category') or status]
    if kind == 'provider':
        if payload.get('refusals') or payload.get('response_kind') == 'refusal':
            return ['provider_refusal']
        if payload.get('truncated') or payload.get('response_status') == 'incomplete':
            return ['provider_incomplete_output']
        if payload.get('response_status') not in (None, 'completed'):
            return ['provider_noncompleted_status']
        return [] if isinstance(payload.get('code'), str) and payload['code'].strip() else ['provider_empty_or_invalid_output']
    flags = ('execution_pass', 'oracle_pass', 'target_reached')
    if not all(type(payload.get(key)) is bool for key in flags):
        return ['unverified_checker_payload']
    result = []
    if not payload['execution_pass']:
        compile_log = directory / 'compile.stderr'
        result.append('candidate_compile_or_execution_failure')
        if compile_log.is_file() and compile_log.stat().st_size:
            result.append('compiler_diagnostic_present')
    else:
        if not payload['oracle_pass']:
            result.append('oracle_mismatch')
        if not payload['target_reached']:
            result.append('required_target_not_observed')
    return result

def _diagnostics(directory):
    """Heuristic tags point to saved lines; never expose diagnostic/private values."""
    tags = []
    for name in ('compile.stderr', 'run.stderr', 'program/program.stderr', 'program/debugger.stderr'):
        path = directory / name
        if not path.is_file() or any(p.is_symlink() for p in (path, *path.parents)):
            continue
        lines = path.read_text(errors='replace').splitlines()
        for tag, pattern in DIAGNOSTIC_RULES.items():
            matched = [i for i, line in enumerate(lines, 1) if re.search(pattern, line)]
            if matched:
                tags.append({'tag': tag, 'basis': 'heuristic_pattern_not_verified_root_cause',
                             'pattern': pattern, 'line_numbers': matched, 'evidence': _binding(path)})
    return tags

def _evidence(directory):
    return [_binding(p) for p in sorted(directory.rglob('*')) if p.is_file() and not p.is_symlink()
            and p.suffix not in ('.class', '.jar')
            and not any(parent.is_symlink() for parent in p.parents)]

def _files(root):
    """Prune library checkouts/private banks; do not traverse symlink directories."""
    for current, directories, names in os.walk(root, followlinks=False):
        directories[:] = [d for d in sorted(directories) if d not in
                          ('.git', 'repository.git', 'source', 'bank', '__pycache__')
                          and not (Path(current) / d).is_symlink()]
        for name in sorted(names):
            path = Path(current) / name
            if not path.is_symlink():
                yield path

def _identity(directory, request):
    identity = {'case_id': request.get('case_id'), 'trial_id': None,
                'condition': request.get('condition'), 'fix_round': None,
                'attempt_directory': directory.name}
    for parent in directory.parents:
        if parent.name.startswith('round_') and parent.name[6:].isdigit():
            identity['fix_round'] = int(parent.name[6:])
            unit = parent.parent.name
            if '--' in unit:
                identity['case_id'], identity['trial_id'] = unit.rsplit('--', 1)
            identity['condition'] = parent.parent.parent.name
            break
    if identity['fix_round'] is not None:
        identity['phase'] = 'initial' if identity['fix_round'] == 0 else 'code_repair'
    else:
        identity['phase'] = 'control' if any(p.name.startswith('control_') for p in directory.parents) else 'proposal'
    return identity

def _read(path):
    result = json.loads(path.read_text()) if path.is_file() and not any(p.is_symlink() for p in (path, *path.parents)) else {}
    if not isinstance(result, dict):
        raise ValueError('Expected an evidence object')
    return result

def _tokens(payload):
    usage = payload.get('usage') or {}
    return {key: usage.get(key) if type(usage.get(key)) is int and usage[key] >= 0 else None
            for key in TOKEN_KEYS}

def collect_telemetry(root):
    """Read saved evidence only. Unknown usage/time stays null, never fabricated."""
    root = Path(root).resolve(strict=True)
    paths = list(_files(root))
    entries, tasks, errors = {}, [], []
    for path in paths:
        if path.name == 'prepared.json' and path.parent.name.startswith('entry_'):
            try:
                prepared = _read(path)
                for phase in prepared.get('phases', {}):
                    state_path = path.parent / (phase + '.state.json')
                    state = _read(state_path)
                    call = (state.get('provider_evidence') or {}).get('call_directory') or state.get('provider_call_directory')
                    context = {'entry_id': prepared.get('id'), 'entry_phase': phase,
                               'state_status': state.get('status', 'not_started'),
                               'state_evidence': _binding(state_path) if state_path.is_file() else None}
                    if call:
                        entries[str(Path(call).resolve())] = context
                    tasks.append({'kind': 'readme_phase', **context, 'directory': str(path.parent),
                                  'started_at': state.get('started_at'), 'finished_at': state.get('finished_at'),
                                  'seconds': state.get('seconds'), 'provider_call_directory': call})
            except (ValueError, OSError, TypeError) as exc:
                errors.append({'path': str(path), 'error_type': type(exc).__name__})
    attempts = []
    directories = sorted({p.parent for p in paths if p.name == 'request.json'
                          and (p.parent.name.startswith(('provider_', 'attempt_', 'execution_'))
                               or p.parent.name == 'model_attempt') and p.parent.name != 'provider_audit'})
    for directory in directories:
        try:
            attempts.append(_subprocess(directory))
        except (ValueError, OSError, TypeError) as exc:
            errors.append({'path': str(directory), 'error_type': type(exc).__name__})
    native = sorted({p.parent for p in paths if p.name == 'request.json' and p.parent.name.startswith('call-')})
    for directory in native:
        try:
            attempts.append(_native(directory, entries.get(str(directory), {})))
        except (ValueError, OSError, TypeError) as exc:
            errors.append({'path': str(directory), 'error_type': type(exc).__name__})
    for path in paths:
        if path.name == 'result.json' and '--' in path.parent.name:
            try:
                row = _read(path)
            except (ValueError, OSError) as exc:
                errors.append({'path': str(path), 'error_type': type(exc).__name__})
                continue
            tasks.append({key: row.get(key) for key in ('arm', 'case_id', 'trial_id', 'status',
                          'first_attempt_pass', 'first_pass_round', 'last_checked_round')} |
                         {'kind': 'audience_unit', 'evidence': _binding(path)})
    providers = [a for a in attempts if a['kind'] == 'provider']
    totals = {key: {'reported_sum': sum(a['tokens'][key] or 0 for a in providers),
                    'calls_without_value': sum(a['tokens'][key] is None for a in providers)} for key in TOKEN_KEYS}
    return {'schema_version': 1, 'generated_at': datetime.now(timezone.utc).isoformat(), 'root': str(root),
            'scope': 'Local private evidence index. Links may expose checker/private fixture outputs; do not publish wholesale.',
            'limits': ['Read-only derived index, not new evaluation or accounting evidence.',
                       'Provider attempts are distinct from fix_round; retries do not add repair rounds.',
                       'Output tokens already include reasoning; non-reasoning may include formatting tokens.',
                       'Unknown historical timestamps/usage stay null; error categories are descriptive, not score changes.',
                       'Diagnostic tags are literal heuristic matches with evidence/line numbers, not verified root causes or model grading.',
                       'This is a live snapshot; writing evidence may be partial. Rerun after the worker stops.'],
            'tasks': tasks, 'attempts': attempts, 'provider_attempts': len(providers),
            'reported_tokens': totals, 'scan_errors': errors}

def bundle_proposals(proposals, output, *, readme=None):
    """Produce a complete multi-file version; installation remains a separate step.

    Inputs are exact per-batch proposal paths. Earlier library versions are not
    implicitly included: provide every batch to retain in this complete bundle.
    """
    if not proposals:
        raise ValueError('Supply at least one per-batch proposal')
    output = Path(output).expanduser().resolve()
    if output.exists():
        raise FileExistsError('Bundle output already exists')
    sources = [Path(p).expanduser().resolve(strict=True) for p in proposals]
    if len(set(sources)) != len(sources):
        raise ValueError('Duplicate proposal path')
    baseline = load(sources[0]).get('baseline_revision')
    if not baseline:
        raise ValueError('Missing baseline revision')
    checked, reviews = [], []
    for path in sources:
        proposal = load(path)
        refactors = proposal.get('refactor_suggestions')
        if refactors:
            if (not isinstance(refactors, dict) or not verify_artifact(refactors)
                    or not Path(refactors['path']).resolve().is_relative_to(path.parent)):
                raise ValueError('Refactor review evidence is missing, changed or outside its proposal')
            reviews.append(refactors)
        if proposal.get('artifacts') == {} and proposal.get('status') == 'review_candidates_only':
            if proposal.get('baseline_revision') != baseline or not refactors:
                raise ValueError('Refactor-only batch baseline or evidence is missing')
            checked.append((proposal, {}))
        else:
            checked.append(_read_proposal(path, baseline))
    source_refs = [bind(p) for p in sources]
    aliases, hints, interfaces, contents, targets, names = [], [], [], {}, set(), set()
    readmes = []
    for number, (proposal, data) in enumerate(checked, 1):
        for row in proposal.get('aliases', []):
            name = row.get('name')
            if not isinstance(name, str) or not name or name.casefold() in names:
                raise ValueError('Duplicate or missing exported alias name across batches')
            names.add(name.casefold())
            aliases.append(row)
        for key, binding in proposal['artifacts'].items():
            role = _artifact_role(key)
            if role == 'alias':
                target = binding['target']
                if any(target.casefold() == old or target.casefold().startswith(old + '/')
                       or old.startswith(target.casefold() + '/') for old in targets):
                    raise ValueError('Duplicate alias source destination or path prefix across batches')
                targets.add(target.casefold())
                contents[f'alias_{len(contents) + 1:04d}'] = (target, data[key])
            elif role == 'alias_interface':
                interfaces.append(f'## Proposal batch {number}\n\n' + data[key].decode())
            elif role == 'readme':
                readmes.append(data[key])
            elif role == 'error_hints':
                payload = json.loads(data[key])
                if not isinstance(payload.get('hints'), list):
                    raise ValueError('Error-hint artifact must contain a hints list')
                for hint in payload['hints']:
                    if not isinstance(hint, dict):
                        raise ValueError('Error hints must be objects')
                    marked = {**hint, 'status': 'unverified'}
                    if marked not in hints:
                        hints.append(marked)
    if readme:
        readme = Path(readme).expanduser().resolve(strict=True)
        readmes.append(readme.read_bytes())
        source_refs.append(bind(readme))
    if readmes and any(text != readmes[0] for text in readmes):
        raise ValueError('Conflicting improved README versions; select identical bytes')
    if not contents and not hints and not readmes:
        raise ValueError('No installable treatments; keep the separate refactor review candidates')
    output.mkdir(parents=True, exist_ok=False)
    artifacts = {}
    for key, (target, content) in contents.items():
        path = output / (key + Path(target).suffix)
        path.write_bytes(content)
        artifacts[key] = {**bind(path), 'target': target}
    if contents:
        path = output / 'ALIASES.md'
        path.write_text('# Alias interfaces\n\n' + '\n\n'.join(interfaces))
        artifacts['alias_interface'] = bind(path)
    if hints:
        path = output / 'error_hints.json'
        atomic_json(path, {'schema_version': 1, 'status': 'unverified',
                          'source': 'development evidence only', 'hints': hints})
        artifacts['error_hints'] = bind(path)
    if readmes:
        path = output / 'README.md'
        path.write_bytes(readmes[0])
        artifacts['readme'] = bind(path)
    if not artifacts:
        raise ValueError('No installable artifacts in supplied proposals')
    # Keep exact original proposals as provenance, not additional owned source.
    for index, path in enumerate(sources, 1):
        shutil.copyfile(path, output / f'batch_{index:04d}.json')
    review_bindings = []
    for index, ref in enumerate(reviews, 1):
        path = output / f'refactor_review_{index:04d}.json'
        shutil.copyfile(ref['path'], path)
        review_bindings.append(bind(path))
    result = {'schema_version': 2, 'baseline_revision': baseline,
              'status': 'proposed_unvalidated', 'artifacts': artifacts,
              'aliases': aliases, 'source_proposals': source_refs,
              'refactor_reviews': review_bindings,
              'source_proposals_sha256': digest(source_refs), 'requires_validation': True,
              'bundle_semantics': 'complete_replace_owned', 'llm_calls': 0}
    atomic_json(output / 'proposal.json', result)
    return {'proposal': str(output / 'proposal.json'), 'status': result['status'],
            'alias_source_files': len(contents), 'aliases': len(aliases),
            'hints': len(hints), 'llm_calls': 0}

def _bundle(proposal, data, algorithm):
    bundle = {arm: {} for arm in CONDITION_FOLDERS}
    for key, binding in proposal['artifacts'].items():
        role = _artifact_role(key)
        target = binding['target'] if role == 'alias' else FIXED_TARGETS[role]
        for arm in ROUTES[role]:
            bundle[arm][target] = {'role': role, 'sha256': binding['sha256'],
                                  'bytes': binding['bytes'], 'git_blob': _blob(data[key], algorithm)}
            if key != role:
                bundle[arm][target]['data_key'] = key
    return bundle

def _check_target_paths(root, baseline, files):
    for target, binding in files.items():
        path = _safe_path(root, target)
        if path.exists() and not path.is_file():
            raise ValueError(f'Treatment target conflicts with a directory: {target}')
        if binding['role'] == 'alias':
            target = target.casefold()
            if any(p.casefold() == target or p.casefold().startswith(target + '/')
                   or target.startswith(p.casefold() + '/')
                   for p in baseline):
                raise ValueError('Alias target must be a NEW path, absent from the baseline')

def _check_worktree(root, head, desired, *, installing=False):
    """Compare raw file/index blobs, without invoking attributes or Git filters."""
    algorithm = _run(root, 'rev-parse', '--show-object-format')
    tree, index = _trees(root, head), _trees(root)
    changes = {name: _binding_entry(binding) if binding is not None else None
               for name, binding in desired.items()}
    for name in set(tree) | set(index) | set(changes):
        before = tree.get(name)
        allowed = {before}
        if installing and name in changes:
            allowed.add(changes[name])
        # Removed AIDEAL files are represented by an explicit None entry.
        if installing and name in desired and desired[name] is None:
            allowed.add(None)
        if index.get(name) not in allowed:
            raise ValueError(f'Unrelated or changed staged edit: {name}')
        if _disk_entry(root, name, algorithm) not in allowed:
            raise ValueError(f'Unrelated or changed tracked/source edit: {name}')
    for name in _run(root, 'ls-files', '--others', '-z').split('\0'):
        if not name:
            continue
        if installing and name in changes:
            if _disk_entry(root, name, algorithm) == changes[name]:
                continue
        # Attachment instrumentation is deliberately untracked. New treatment
        # files are allowed only after this version has journaled ownership.
        if name.startswith('.aideal/') and not name.startswith('.aideal/treatments/'):
            _safe_path(root, name)
            continue
        raise ValueError(f'Unrelated untracked source/treatment file: {name}')
    scaffold = root / '.aideal'
    if scaffold.is_symlink():
        raise ValueError('Symlinked .aideal workspace is not allowed')
    if scaffold.is_dir():
        for path in scaffold.rglob('*'):
            if path.is_symlink():
                raise ValueError(f'Symlinked scaffold is not allowed: {path}')

def _committed(root, parent, head, files, removed, message):
    if _run(root, 'show', '-s', '--format=%P', head) != parent:
        return False
    if _run(root, 'show', '-s', '--format=%B', head) != message:
        return False
    before, after = _trees(root, parent), _trees(root, head)
    changes = {p: after.get(p) for p in set(before) | set(after) if before.get(p) != after.get(p)}
    return changes == _expected_changes(root, parent, files, removed)

def _disk_entry(root, name, algorithm):
    path = root / name
    if path.is_symlink():
        resolved = path.resolve()
        if resolved != root and root not in resolved.parents:
            raise ValueError(f'Escaping symlink in worktree: {path}')
        return ('120000', _blob(os.fsencode(os.readlink(path)), algorithm))
    if not path.exists():
        return None
    if not path.is_file():
        raise ValueError(f'Expected a regular tracked file: {path}')
    return ('100755' if path.stat().st_mode & 0o111 else '100644', _blob(path.read_bytes(), algorithm))

def _expected_changes(root, parent, files, removed):
    tree = _trees(root, parent)
    after = {name: _binding_entry(binding) for name, binding in files.items()}
    after.update({name: None for name in removed})
    return {name: value for name, value in after.items() if tree.get(name) != value}

def _read_proposal(path, baseline):
    path = Path(path).expanduser().absolute()
    if path.is_symlink():
        raise ValueError('Proposal must not be a symlink')
    path = path.resolve(strict=True)
    proposal = load(path)
    if (not isinstance(proposal, dict) or type(proposal.get('schema_version')) is not int
            or proposal['schema_version'] not in (1, 2) or proposal.get('baseline_revision') != baseline):
        raise ValueError('Proposal schema or baseline revision does not match the attachment')
    artifacts = proposal.get('artifacts')
    if (not isinstance(artifacts, dict) or not artifacts
            or any(_artifact_role(k) not in ROUTES for k in artifacts)
            or (proposal['schema_version'] == 1 and set(artifacts) - set(ROUTES))):
        raise ValueError('Supply at least one known treatment artifact')
    if any(_artifact_role(k) == 'alias' for k in artifacts) != ('alias_interface' in artifacts):
        raise ValueError('Alias source and alias interface must be supplied together')
    data = {}
    targets = set()
    for key, binding in artifacts.items():
        role = _artifact_role(key)
        if not isinstance(binding, dict) or not isinstance(binding.get('path'), str):
            raise ValueError(f'Invalid artifact binding: {role}')
        source = Path(binding['path'])
        if not source.is_absolute() or '..' in source.parts:
            raise ValueError('Artifact paths must be absolute and inside the proposal directory')
        try:
            relative = source.relative_to(path.parent).as_posix()
        except ValueError as exc:
            raise ValueError('Artifact escapes the proposal directory') from exc
        source = _safe_path(path.parent, relative)
        if not source.is_file():
            raise ValueError(f'Artifact is not a regular file: {source}')
        content = source.read_bytes()
        if (not content or type(binding.get('bytes')) is not int or binding['bytes'] != len(content)
                or binding.get('sha256') != hashlib.sha256(content).hexdigest()):
            raise ValueError(f'Artifact hash/size mismatch or empty artifact: {role}')
        if role == 'alias':
            target = _relative(binding.get('target'))
            if target.split('/')[0].casefold() == '.aideal':
                raise ValueError('Alias source must be outside the reserved .aideal directory')
        elif 'target' in binding and binding['target'] != FIXED_TARGETS[role]:
            raise ValueError(f'{role} has a fixed treatment target')
        target = binding.get('target', FIXED_TARGETS.get(role))
        if any(target.casefold() == old or target.casefold().startswith(old + '/')
               or old.startswith(target.casefold() + '/') for old in targets):
            raise ValueError('Duplicate or conflicting treatment destination')
        targets.add(target.casefold())
        data[key] = content
    return proposal, data

def _record(path, value):
    if path.parent.resolve() != path.parent or path.is_symlink() or path.with_suffix(path.suffix + '.tmp').is_symlink():
        raise ValueError('Symlink in application record path')
    atomic_json(path, value)

def _safe_path(root, relative):
    path = root
    for part in _relative(relative).split('/'):
        path = path / part
        if path.is_symlink():
            raise ValueError(f'Symlink is not allowed in a treatment path: {path}')
    return path

def _trees(root, revision=None):
    records = (_run(root, 'ls-tree', '-rz', revision) if revision else
               _run(root, 'ls-files', '--stage', '-z'))
    result = {}
    for record in records.split('\0'):
        if not record:
            continue
        metadata, path = record.split('\t', 1)
        mode, middle, last = metadata.split(' ')
        if not revision and last != '0':
            raise ValueError('Worktree has an unresolved index conflict')
        if mode not in ('100644', '100755', '120000'):
            raise ValueError('Treatment installation does not support submodule/gitlink entries')
        result[path] = (mode, last if revision else middle)
    return result

def _git(directory, *arguments):
    result = subprocess.run(
        ['git', '-C', str(directory), *arguments], capture_output=True, text=True,
    )
    if result.returncode:
        raise ValueError(result.stderr.strip() or 'Git command failed')
    return result.stdout.strip()
